import React from 'react';
import { Routes, Route, Navigate, useLocation } from 'react-router-dom';
import { Toaster } from 'sonner';

import RoutesDev from './devtools/__routes-dev';
import { DevDashboard, NotFoundPage, UnauthorizedPage } from '@shared/pages';
import { AppInitializer } from 'core/providers';
import { AppRouter } from '@domains/app/routes';
import { AuthRouter } from '@domains/auth/routes';
import { MarketingRouter } from '@domains/marketing/routes';

interface LegacyAuthRedirectProps {
  to: string;
}

const LegacyAuthRedirect: React.FC<LegacyAuthRedirectProps> = ({ to }) => {
  const location = useLocation();
  return <Navigate to={`${to}${location.search}${location.hash}`} replace />;
};

const App = () => (
  <AppInitializer>
    <Toaster position="top-center" richColors closeButton />

    <Routes>
      {/* App domain */}
      <Route path="/app/*" element={<AppRouter />} />
      {/* Onboarding (root) is defined inside AppRouter as absolute /onboarding */}
      <Route path="/onboarding" element={<AppRouter />} />

      {/* Auth domain */}
      <Route path="/auth/*" element={<AuthRouter />} />
      {/* Legacy auth aliases */}
      <Route path="/signin" element={<LegacyAuthRedirect to="/auth/login" />} />
      <Route path="/signup" element={<LegacyAuthRedirect to="/auth/signup" />} />
      <Route path="/login" element={<LegacyAuthRedirect to="/auth/login" />} />
      <Route
        path="/verify-email"
        element={<LegacyAuthRedirect to="/auth/verify-email" />}
      />
      <Route
        path="/email-sent"
        element={<LegacyAuthRedirect to="/auth/email-sent" />}
      />
      <Route
        path="/forgot-password"
        element={<LegacyAuthRedirect to="/auth/forgot-password" />}
      />

      {/* Shared/system routes */}
      <Route path="/unauthorized" element={<UnauthorizedPage />} />
      <Route path="/dev-dashboard" element={<DevDashboard />} />

      {process.env.NODE_ENV === 'development' && (
        <Route path="/__routes-dev" element={<RoutesDev />} />
      )}

      {/* Marketing domain */}
      <Route path="/*" element={<MarketingRouter />} />

      {/* Fallback */}
      <Route path="*" element={<NotFoundPage />} />
    </Routes>
  </AppInitializer>
);

export default App;

import React from 'react';
import { Route, Routes, Navigate, Outlet } from 'react-router-dom';
import { useSelector } from 'react-redux';

import {
  AllProductsTab,
  AdminAuditPage,
  AdminPage,
  AdminProductsPage,
  AdminUsersPage,
  AppLayout,
  Cart,
  ConsultationTab,
  CoursesTab,
  CreatorAnalytics,
  CreatorDashboard,
  CustomerDetail,
  DownloadPackagesTab,
  ExplorePage,
  GalacticaHome,
  LibraryPage,
  Onboarding,
  ProductForm,
  ProductLandingPageBuilder,
  ProductOverview,
  ProductPage,
  ProductPreview,
  ProductsList,
  CustomersList,
  SalesPage,
  SearchResultsPage,
  SettingsPage,
  StorefrontPage,
  CreatorStorefrontPage,
  WishlistTab,
} from '../pages';
import { ProtectedRoute } from '@core/providers';
import { getPrimaryRole, UserRole } from '@core/api';
import { selectAuthUser } from '@core/store/auth-store';

const RoleHome: React.FC = () => {
  const user = useSelector(selectAuthUser);
  const primaryRole = getPrimaryRole(user?.roles);

  if (primaryRole === UserRole.ADMIN) {
    return <AdminPage />;
  }

  if (primaryRole === UserRole.CREATOR) {
    return <CreatorDashboard />;
  }

  return <GalacticaHome />;
};

const AppRouter: React.FC = () => (
  <Routes>
    {/* Onboarding lives at root (same as your current setup) */}
    <Route
      path="/onboarding"
      element={
        <ProtectedRoute
          allowedRoles={[UserRole.ADMIN, UserRole.CREATOR, UserRole.USER]}
        >
          <Onboarding />
        </ProtectedRoute>
      }
    />

    {/* /app englobes the whole app part (public + protected routes) */}
    <Route path="/" element={<AppLayout />}>
      {/* Public routes under /app */}
      <Route path="explore" element={<ExplorePage />} />
      <Route path="explore/search" element={<SearchResultsPage />} />
      <Route path="product/:id" element={<ProductPage />} />
      <Route path="product/:id/:type" element={<ProductPage />} />
      <Route path="store/:creatorId" element={<StorefrontPage />} />

      {/* Protected wrapper */}
      <Route
        element={
          <ProtectedRoute
            allowedRoles={[UserRole.ADMIN, UserRole.CREATOR, UserRole.USER]}
          >
            <Outlet />
          </ProtectedRoute>
        }
      >
        {/* Shared dashboard home */}
        <Route index element={<RoleHome />} />

        <Route
          path="admin"
          element={
            <ProtectedRoute allowedRoles={[UserRole.ADMIN]}>
              <Outlet />
            </ProtectedRoute>
          }
        >
          <Route index element={<AdminPage />} />
          <Route path="users" element={<AdminUsersPage />} />
          <Route path="products" element={<AdminProductsPage />} />
          <Route path="products/create" element={<ProductForm />} />
          <Route path="audit" element={<AdminAuditPage />} />
        </Route>

        {/* Creator/Admin: products */}
        <Route
          path="products"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR, UserRole.ADMIN]}>
              <Outlet />
            </ProtectedRoute>
          }
        >
          <Route index element={<ProductsList />} />
          <Route path="create" element={<ProductForm />} />
          <Route path="edit/:id" element={<ProductForm />} />
          <Route path="edit/:type/:id" element={<ProductForm />} />
          <Route path=":productId/landing-page" element={<ProductLandingPageBuilder />} />
          <Route path=":productId/preview" element={<ProductPreview />} />
          <Route path=":productId" element={<ProductOverview />} />
        </Route>

        <Route
          path="customers"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR]}>
              <Outlet />
            </ProtectedRoute>
          }
        >
          <Route index element={<CustomersList />} />
          <Route path=":customerId" element={<CustomerDetail />} />
        </Route>

        <Route
          path="sales"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR]}>
              <SalesPage />
            </ProtectedRoute>
          }
        />

        <Route
          path="analytics"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR]}>
              <CreatorAnalytics />
            </ProtectedRoute>
          }
        />

        {/* User/Admin: library */}
        <Route
          path="library"
          element={
            <ProtectedRoute allowedRoles={[UserRole.USER, UserRole.ADMIN]}>
              <LibraryPage />
            </ProtectedRoute>
          }
        >
          <Route path="all-products" element={<AllProductsTab />} />
          <Route path="my-courses" element={<CoursesTab />} />
          <Route
            path="my-download-packages"
            element={<DownloadPackagesTab />}
          />
          <Route path="my-consultation" element={<ConsultationTab />} />
          <Route path="my-wishlist" element={<WishlistTab />} />
        </Route>

        <Route path="settings" element={<SettingsPage />} />
        <Route
          path="storefront"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR]}>
              <CreatorStorefrontPage />
            </ProtectedRoute>
          }
        />
        <Route
          path="my-page-preview"
          element={<Navigate to="/app/storefront" replace />}
        />
        <Route path="cart" element={<Cart />} />

        {/* Fallback inside /app */}
        <Route path="*" element={<Navigate to="/app" replace />} />
      </Route>
    </Route>
  </Routes>
);

export default AppRouter;

import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';

import { selectAuthUser } from 'core/store/auth-store';
import { User, UserRole } from 'core/api/models';
import {
  CountdownRedirect,
  MultiStepForm,
} from 'domains/app/features/onboarding';

import './onboarding.styles.scss';

const Onboarding: React.FC = () => {
  const user = useSelector(selectAuthUser);
  const [otherUser, setOtherUser] = useState<User | null>(null);

  useEffect(() => {
    const mockUser: User = {
      email: 'myemail@domain.test',
      firstName: 'Gica',
      lastName: 'Hagi',
      roles: [UserRole.USER],
      id: '',
      onboardingCompleted: false,
    };
    if (user) {
      setOtherUser(user);
    } else {
      setOtherUser(mockUser);
    }
  }, [user]);

  return (
    <div className="onboarding-page">
      {!otherUser?.onboardingCompleted ? (
        <MultiStepForm />
      ) : (
        <CountdownRedirect />
      )}
    </div>
  );
};

export default Onboarding;

