/* eslint-disable no-unused-vars */
import React, { ReactNode, useEffect, useRef, useState } from 'react';

import { useOnClickOutside } from '@shared/hooks';
import './dropdown.styles.scss';

interface DropdownProps {
  customClassName: string;
  /** The element that toggles the dropdown open/closed */
  trigger: (props: { open: boolean; toggle: () => void }) => ReactNode;
  /** The actual dropdown menu, rendered only when open=true */
  menu: (props: { close: () => void }) => ReactNode;
}

const Dropdown: React.FC<DropdownProps> = ({
  customClassName,
  trigger,
  menu,
}) => {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  const toggle = () => setOpen((o) => !o);
  const close = () => setOpen(false);

  useOnClickOutside(ref, close);

  useEffect(() => {
    if (!open) {
      return undefined;
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        close();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [open]);

  return (
    <div ref={ref} className="dropdown-root">
      {trigger({ open, toggle })}
      {open && (
        <div className={`dropdown-panel ${customClassName}`}>
          {menu({ close })}
        </div>
      )}
    </div>
  );
};

export default Dropdown;

@use '../../../styles/index.scss' as *;

.dropdown-root {
  display: inline-block;
  position: relative;

  .dropdown-panel {
    position: absolute;
    top: 100%;
    left: 0;
    z-index: var(--z-dropdown);
    width: 150px;
    background-color: var(--surface-2);
    border: 1px solid var(--border-subtle);
    border-radius: $radius-md;
    display: flex;
    flex-direction: column;
    gap: $spacing-1;
    padding: $spacing-2;
    box-shadow: var(--shadow-e2);

    button,
    a,
    [role='menuitem'] {
      min-height: 36px;
      display: flex;
      align-items: center;
      gap: $spacing-2;
      padding: 0 $spacing-3;
      border-radius: $radius-sm;
      color: var(--text-secondary);
      background: transparent;
      text-align: left;
      transition:
        background $transition-fast,
        color $transition-fast;

      &:hover {
        background: var(--overlay-hover);
        color: var(--text-primary);
      }

      &:active {
        background: var(--overlay-pressed);
      }

      &:focus-visible {
        outline: none;
        box-shadow:
          0 0 0 2px var(--surface-panel-elevated),
          0 0 0 4px var(--focus-ring);
      }
    }
  }
}

