import React from 'react';
import { Route, Routes, Navigate, Outlet } from 'react-router-dom';
import { useSelector } from 'react-redux';

import {
  AllProductsTab,
  AdminAuditPage,
  AdminPage,
  AdminProductsPage,
  AdminUsersPage,
  AppLayout,
  Cart,
  ConsultationTab,
  CoursesTab,
  CreatorAnalytics,
  CreatorDashboard,
  CustomerDetail,
  DownloadPackagesTab,
  ExplorePage,
  GalacticaHome,
  LibraryPage,
  Onboarding,
  ProductForm,
  ProductLandingPageBuilder,
  ProductOverview,
  ProductPage,
  ProductPreview,
  ProductsList,
  CustomersList,
  SalesPage,
  SearchResultsPage,
  SettingsPage,
  StorefrontPage,
  CreatorStorefrontPage,
  WishlistTab,
} from '../pages';
import { ProtectedRoute } from '@core/providers';
import { getPrimaryRole, UserRole } from '@core/api';
import { selectAuthUser } from '@core/store/auth-store';

const RoleHome: React.FC = () => {
  const user = useSelector(selectAuthUser);
  const primaryRole = getPrimaryRole(user?.roles);

  if (primaryRole === UserRole.ADMIN) {
    return <AdminPage />;
  }

  if (primaryRole === UserRole.CREATOR) {
    return <CreatorDashboard />;
  }

  return <GalacticaHome />;
};

const AppRouter: React.FC = () => (
  <Routes>
    {/* Onboarding lives at root (same as your current setup) */}
    <Route
      path="/onboarding"
      element={
        <ProtectedRoute
          allowedRoles={[UserRole.ADMIN, UserRole.CREATOR, UserRole.USER]}
        >
          <Onboarding />
        </ProtectedRoute>
      }
    />

    {/* /app englobes the whole app part (public + protected routes) */}
    <Route path="/" element={<AppLayout />}>
      {/* Public routes under /app */}
      <Route path="explore" element={<ExplorePage />} />
      <Route path="explore/search" element={<SearchResultsPage />} />
      <Route path="product/:id" element={<ProductPage />} />
      <Route path="product/:id/:type" element={<ProductPage />} />
      <Route path="store/:creatorId" element={<StorefrontPage />} />

      {/* Protected wrapper */}
      <Route
        element={
          <ProtectedRoute
            allowedRoles={[UserRole.ADMIN, UserRole.CREATOR, UserRole.USER]}
          >
            <Outlet />
          </ProtectedRoute>
        }
      >
        {/* Shared dashboard home */}
        <Route index element={<RoleHome />} />

        <Route
          path="admin"
          element={
            <ProtectedRoute allowedRoles={[UserRole.ADMIN]}>
              <Outlet />
            </ProtectedRoute>
          }
        >
          <Route index element={<AdminPage />} />
          <Route path="users" element={<AdminUsersPage />} />
          <Route path="products" element={<AdminProductsPage />} />
          <Route path="products/create" element={<ProductForm />} />
          <Route path="audit" element={<AdminAuditPage />} />
        </Route>

        {/* Creator/Admin: products */}
        <Route
          path="products"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR, UserRole.ADMIN]}>
              <Outlet />
            </ProtectedRoute>
          }
        >
          <Route index element={<ProductsList />} />
          <Route path="create" element={<ProductForm />} />
          <Route path="edit/:id" element={<ProductForm />} />
          <Route path="edit/:type/:id" element={<ProductForm />} />
          <Route path=":productId/landing-page" element={<ProductLandingPageBuilder />} />
          <Route path=":productId/preview" element={<ProductPreview />} />
          <Route path=":productId" element={<ProductOverview />} />
        </Route>

        <Route
          path="customers"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR]}>
              <Outlet />
            </ProtectedRoute>
          }
        >
          <Route index element={<CustomersList />} />
          <Route path=":customerId" element={<CustomerDetail />} />
        </Route>

        <Route
          path="sales"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR]}>
              <SalesPage />
            </ProtectedRoute>
          }
        />

        <Route
          path="analytics"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR]}>
              <CreatorAnalytics />
            </ProtectedRoute>
          }
        />

        {/* User/Admin: library */}
        <Route
          path="library"
          element={
            <ProtectedRoute allowedRoles={[UserRole.USER, UserRole.ADMIN]}>
              <LibraryPage />
            </ProtectedRoute>
          }
        >
          <Route path="all-products" element={<AllProductsTab />} />
          <Route path="my-courses" element={<CoursesTab />} />
          <Route
            path="my-download-packages"
            element={<DownloadPackagesTab />}
          />
          <Route path="my-consultation" element={<ConsultationTab />} />
          <Route path="my-wishlist" element={<WishlistTab />} />
        </Route>

        <Route path="settings" element={<SettingsPage />} />
        <Route
          path="storefront"
          element={
            <ProtectedRoute allowedRoles={[UserRole.CREATOR]}>
              <CreatorStorefrontPage />
            </ProtectedRoute>
          }
        />
        <Route
          path="my-page-preview"
          element={<Navigate to="/app/storefront" replace />}
        />
        <Route path="cart" element={<Cart />} />

        {/* Fallback inside /app */}
        <Route path="*" element={<Navigate to="/app" replace />} />
      </Route>
    </Route>
  </Routes>
);

export default AppRouter;

import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import { toast } from 'sonner';

import { ProductMinimised, AppDispatch } from 'core/api/models';
import { Button } from '@shared/ui';
import { selectAuthUser } from 'core/store/auth-store';
import {
  selectAllShopCartProducts,
  selectShopCartTotal,
  removeProductFromCart,
  moveCartItemToWishlist,
  clearShoppingCart,
} from 'core/store/shop-cart';
import { selectWishlistIds } from 'core/store/wishlist';
import { enrollInFreeProductAPI } from 'core/api/services';
import {
  formatCommerceAmount,
  getCartCheckoutKind,
  getCommerceErrorMessage,
  isSuccessfulOrderStatus,
  isTerminalUnsuccessfulOrderStatus,
  startPaidCheckout,
  validatePaidCart,
} from './cart-checkout.utils';
// eslint-disable-next-line @typescript-eslint/no-var-requires
const placeholderImage = require('../../../../../assets/image-placeholder.png');

import './cart.styles.scss';

const Cart: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const user = useSelector(selectAuthUser);
  const cartProducts = useSelector(selectAllShopCartProducts);
  const cartTotal = useSelector(selectShopCartTotal);
  const wishlistIds = useSelector(selectWishlistIds);
  const [checkingOut, setCheckingOut] = useState(false);
  const cartCheckoutKind = getCartCheckoutKind(cartProducts);
  const containsPaidProducts = cartCheckoutKind === 'PAID';
  const containsMixedProducts = cartCheckoutKind === 'MIXED';

  const handleRemoveFromCart = (prod: ProductMinimised) => {
    if (prod && prod.id) {
      dispatch(removeProductFromCart(prod.id));
    }
  };

  const handleMoveToWishlist = (prod: ProductMinimised) => {
    if (prod && prod.id) {
      dispatch(moveCartItemToWishlist(prod.id));
    }
  };

  const handleFreeCheckout = async () => {
    const productIds = cartProducts
      .map((product) => product.id)
      .filter((id): id is string => Boolean(id));
    if (productIds.length === 0 || containsPaidProducts) {
      return;
    }

    setCheckingOut(true);
    try {
      await Promise.all(productIds.map(enrollInFreeProductAPI));
      dispatch(clearShoppingCart());
      toast.success('Products added to your library');
      navigate('/app/library/all-products');
    } catch {
      toast.error('The free products could not be added to your library.');
    } finally {
      setCheckingOut(false);
    }
  };

  const handlePaidCheckout = async () => {
    const validation = validatePaidCart(cartProducts, user?.id);
    if (!validation.valid) {
      toast.error(validation.message);
      return;
    }

    setCheckingOut(true);
    try {
      const { session, order } = await startPaidCheckout(cartProducts);

      if (session.checkoutUrl) {
        return;
      }

      if (!order) {
        toast.info('Checkout started. Your cart has been saved.');
        return;
      }

      const amount = formatCommerceAmount(order.totalMinor, order.currency);

      if (isSuccessfulOrderStatus(order.status)) {
        dispatch(clearShoppingCart());
        toast.success(
          amount
            ? `Payment confirmed for ${amount}. Products added to your library.`
            : 'Payment confirmed. Products added to your library.',
        );
        navigate('/app/library/all-products');
        return;
      }

      if (order.status === 'PENDING') {
        toast.info('Payment is still pending. Your cart has been saved.');
        return;
      }

      if (isTerminalUnsuccessfulOrderStatus(order.status)) {
        toast.error('Payment was not completed. Your cart has been saved.');
      }
    } catch (error) {
      toast.error(getCommerceErrorMessage(error));
    } finally {
      setCheckingOut(false);
    }
  };

  const handleCheckout = () => {
    if (containsMixedProducts) {
      toast.error(
        'Free and paid products cannot be checked out together. Please split your cart.',
      );
      return;
    }

    if (containsPaidProducts) {
      void handlePaidCheckout();
      return;
    }

    void handleFreeCheckout();
  };

  return (
    <div className="cart-page">
      <h1 className="cart-page-title">Shopping Cart</h1>
      {cartProducts.length > 0 ? (
        <>
          <section className="cart-container">
            <div className="cart-container-line">
              <p>{cartProducts.length} products in your cart</p>
              <hr className="cart-underline"></hr>
            </div>
            <article className="cart-products-container">
              <div className="cart-products-list">
                {cartProducts.map((prod) => {
                  const isInWishlist = wishlistIds.has(prod.id);
                  const productTitle = prod.title ?? 'Untitled product';

                  return (
                    <div key={prod.id} className="cart-product">
                      <img
                        src={placeholderImage}
                        alt={productTitle}
                        className="product-card-image"
                      />
                      <div className="cart-product-details">
                        <h3>{productTitle}</h3>
                        <p>By {prod.createdByName}</p>
                        <p>4.7 ⭐⭐⭐⭐⭐ (32,025 ratings)</p>
                      </div>
                      <div className="cart-product-actions">
                        <button
                          type="button"
                          onClick={() => handleRemoveFromCart(prod)}
                        >
                          Remove
                        </button>
                        <button
                          type="button"
                          disabled={isInWishlist}
                          onClick={() => handleMoveToWishlist(prod)}
                        >
                          Move to wishlist
                        </button>
                      </div>
                      <div className="cart-product-price-tag">
                        €{prod.price}
                      </div>
                    </div>
                  );
                })}
              </div>
            </article>
            <aside className="cart-products-aside">
              <h4>Total:</h4>
              <h2>
                {cartTotal && cartTotal > 0 ? (
                  <span>€{cartTotal}</span>
                ) : (
                  <span>free</span>
                )}
              </h2>
              {containsPaidProducts && (
                <p className="cart-products-aside__notice" role="note">
                  Test payment — No real charge will be made during checkout.
                </p>
              )}

              <Button
                type="button"
                variant="primary"
                disabled={checkingOut}
                onClick={handleCheckout}
              >
                {checkingOut ? 'Processing...' : 'Proceed to checkout'}
              </Button>
              {containsMixedProducts && (
                <p role="alert" className="cart-products-aside__message">
                  Free and paid products cannot be checked out together. Please
                  split your cart.
                </p>
              )}
            </aside>
          </section>
        </>
      ) : (
        <p>You don&apos;t have any products in your shopping cart</p>
      )}
      <div className="cart-page-bottom">
        <h2>You might also like</h2>
      </div>
    </div>
  );
};

export default Cart;

