package com.myproject.video.video_platform.service.product;

import com.myproject.video.video_platform.common.enums.products.ProductStatus;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationAvailabilityDay;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationAvailabilityWindow;
import com.myproject.video.video_platform.entity.products.consultation.ConsultationProduct;
import com.myproject.video.video_platform.entity.products.course.CourseProduct;
import com.myproject.video.video_platform.entity.products.download.DownloadProduct;
import com.myproject.video.video_platform.entity.products.membership.MembershipProduct;
import com.myproject.video.video_platform.exception.product.ProductPublicationValidationException;
import org.springframework.stereotype.Component;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Component
public class ProductPublicationValidator {
    public void validate(Product product) {
        if (product.getStatus() != ProductStatus.PUBLISHED) return;
        Map<String, String> issues = new LinkedHashMap<>();
        if (product.getName() == null || product.getName().isBlank()) {
            issues.put("name", "Name is required");
        }
        if (product instanceof MembershipProduct) {
            issues.put("status", "Membership publication is not supported yet");
        } else if (product instanceof CourseProduct course) {
            requireFreeOrPositivePrice(product, issues);
            if (course.getSections() == null || course.getSections().isEmpty()) {
                issues.put("details.sections", "At least one section is required");
            } else if (course.getSections().stream().noneMatch(s -> s.getLessons() != null && !s.getLessons().isEmpty())) {
                issues.put("details.lessons", "At least one lesson is required");
            }
        } else if (product instanceof DownloadProduct download) {
            requireFreeOrPositivePrice(product, issues);
            boolean hasFile = download.getSectionDownloadProducts() != null
                    && download.getSectionDownloadProducts().stream()
                    .flatMap(section -> section.getFiles().stream())
                    .anyMatch(file -> file.getPath() != null && !file.getPath().isBlank());
            if (!hasFile) issues.put("details.files", "At least one confirmed file is required");
        } else if (product instanceof ConsultationProduct consultation) {
            if (product.getPrice() == null || product.getPrice().compareTo(BigDecimal.ZERO) <= 0) {
                issues.put("price", "Consultations require a positive price");
            }
            if (consultation.getDurationMinutes() == null || consultation.getDurationMinutes() <= 0) {
                issues.put("details.durationMinutes", "Duration must be positive");
            }
            if (consultation.getMeetingMethod() == null) {
                issues.put("details.meetingMethod", "Meeting method is required");
            } else if (consultation.getMeetingMethod() == ConsultationProduct.MeetingMethod.OTHER
                    && (consultation.getCustomLocation() == null || consultation.getCustomLocation().isBlank())) {
                issues.put("details.customLocation", "A custom location is required for OTHER");
            }
            validateAvailability(consultation, issues);
        }
        if (!issues.isEmpty()) throw new ProductPublicationValidationException(issues);
    }

    private static void requireFreeOrPositivePrice(Product product, Map<String, String> issues) {
        if (product.getPrice() == null || product.getPrice().compareTo(BigDecimal.ZERO) < 0) {
            issues.put("price", "Price must be free or positive");
        }
    }

    private static void validateAvailability(ConsultationProduct product, Map<String, String> issues) {
        boolean validRangeFound = false;
        for (ConsultationAvailabilityDay day : product.getWeeklyAvailability()) {
            if (!day.isEnabled()) continue;
            List<ConsultationAvailabilityWindow> windows = day.getWindows();
            for (int index = 0; index < windows.size(); index++) {
                ConsultationAvailabilityWindow current = windows.get(index);
                if (!current.getStartTime().isBefore(current.getEndTime())) {
                    issues.put("details.weeklyAvailability", "Availability start time must be before end time");
                    continue;
                }
                validRangeFound = true;
                for (int other = index + 1; other < windows.size(); other++) {
                    ConsultationAvailabilityWindow candidate = windows.get(other);
                    if (current.getStartTime().isBefore(candidate.getEndTime())
                            && candidate.getStartTime().isBefore(current.getEndTime())) {
                        issues.put("details.weeklyAvailability", "Availability windows cannot overlap");
                    }
                }
            }
        }
        if (!validRangeFound) {
            issues.put("details.weeklyAvailability", "At least one enabled valid availability range is required");
        }
    }
}

package com.myproject.video.video_platform.service.product.course;

import com.myproject.video.video_platform.common.enums.products.course.LessonType;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.products.authoring.ProductLessonCreateRequestDto;
import com.myproject.video.video_platform.dto.products.authoring.ProductLessonUpdateRequestDto;
import com.myproject.video.video_platform.dto.products.course.CourseLessonCreateRequestDto;
import com.myproject.video.video_platform.dto.products.course.CourseLessonResponseDto;
import com.myproject.video.video_platform.dto.products.course.CourseLessonUpdateRequestDto;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.products.course.CourseProduct;
import com.myproject.video.video_platform.entity.products.course.CourseLesson;
import com.myproject.video.video_platform.entity.products.course.CourseSection;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.repository.products.ProductRepository;
import com.myproject.video.video_platform.repository.products.course.CourseProductRepository;
import com.myproject.video.video_platform.repository.products.course.CourseLessonRepository;
import com.myproject.video.video_platform.repository.products.course.CourseSectionRepository;
import com.myproject.video.video_platform.service.product.ProductAuthorizationService;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.Optional;
import java.util.UUID;

@Service
@Slf4j
@RequiredArgsConstructor
public class CourseLessonService {

    private final ProductRepository productRepository;
    private final CourseProductRepository courseRepo;
    private final CourseSectionRepository sectionRepo;
    private final CourseLessonRepository lessonRepo;
    private final ProductAuthorizationService productAuthorizationService;

    /**
     * POST /api/sections/{sectionId}/lessons
     */
    @Transactional
    public CourseLessonResponseDto createLesson(CourseLessonCreateRequestDto dto) {

        UUID sectionId = UUID.fromString(dto.getSectionId());
        CourseSection section = sectionRepo.findById(sectionId)
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionId));

        productAuthorizationService.requireOwnerOrAdmin(section.getCourse());

        CourseLesson lesson = new CourseLesson();
        lesson.setTitle(dto.getTitle());
        LessonType lessonType = LessonType.valueOf(dto.getType().toUpperCase());
        lesson.setType(lessonType);
        applyLessonContent(lesson, lessonType, dto.getVideoUrl(), dto.getContent());
        lesson.setDescription(dto.getDescription());
        lesson.setPosition(
                dto.getPosition() == null
                        ? section.getLessons().size() + 1
                        : dto.getPosition()
        );
        lesson.setSection(section);

        section.getLessons().add(lesson);
        lessonRepo.save(lesson); // cascade saves lesson
        touchProductUpdatedAt(section.getCourse());

        CourseLessonResponseDto resp = new CourseLessonResponseDto();
        resp.setId(lesson.getId().toString());
        resp.setTitle(lesson.getTitle());
        resp.setType(lesson.getType().name());
        resp.setVideoUrl(lesson.getVideoUrl());
        resp.setContent(lesson.getContent());
        resp.setDescription(lesson.getDescription());
        resp.setPosition(lesson.getPosition());
        resp.setSectionId(section.getId().toString());
        return resp;
    }

    /**
     * PUT /api/lessons/{lessonId}
     */
    @Transactional
    public void updateLesson(CourseLessonUpdateRequestDto dto) {
        UUID lessonId = UUID.fromString(dto.getId());
        CourseLesson lesson = lessonRepo.findById(lessonId)
                .orElseThrow(() -> new ResourceNotFoundException("Lesson not found: " + dto.getId()));

        productAuthorizationService.requireOwnerOrAdmin(lesson.getSection().getCourse());

        lesson.setTitle(dto.getTitle());
        LessonType newType = LessonType.valueOf(dto.getType().toUpperCase());
        lesson.setType(newType);
        applyLessonContent(lesson, newType, dto.getVideoUrl(), dto.getContent());
        lesson.setDescription(dto.getDescription());
        if (dto.getPosition() != null) {
            lesson.setPosition(dto.getPosition());
        }
        lessonRepo.save(lesson);
        touchProductUpdatedAt(lesson.getSection().getCourse());
    }

    @Transactional
    public CourseLessonResponseDto createLesson(
            String productId,
            String sectionId,
            ProductLessonCreateRequestDto dto
    ) {
        Product product = loadOwnedProduct(productId);
        if (product.getType() != ProductType.COURSE) {
            throw new UnsupportedProductOperationException("Lessons are only supported for COURSE products.");
        }

        CourseSection section = loadOwnedSection(product.getId(), sectionId);

        CourseLesson lesson = new CourseLesson();
        lesson.setTitle(dto.getTitle());
        LessonType lessonType = LessonType.valueOf(dto.getType().toUpperCase());
        lesson.setType(lessonType);
        applyLessonContent(lesson, lessonType, dto.getVideoUrl(), dto.getContent());
        lesson.setDescription(dto.getDescription());
        lesson.setPosition(
                dto.getPosition() == null
                        ? section.getLessons().size() + 1
                        : dto.getPosition()
        );
        lesson.setSection(section);

        section.getLessons().add(lesson);
        CourseLesson saved = lessonRepo.save(lesson);
        touchProductUpdatedAt(section.getCourse());
        return mapLesson(saved);
    }

    @Transactional
    public CourseLessonResponseDto updateLesson(
            String productId,
            String sectionId,
            String lessonId,
            ProductLessonUpdateRequestDto dto
    ) {
        Product product = loadOwnedProduct(productId);
        if (product.getType() != ProductType.COURSE) {
            throw new UnsupportedProductOperationException("Lessons are only supported for COURSE products.");
        }

        CourseSection section = loadOwnedSection(product.getId(), sectionId);
        CourseLesson lesson = loadLesson(section.getId(), lessonId);

        if (dto.getTitle() != null) {
            lesson.setTitle(dto.getTitle());
        }

        LessonType effectiveType = lesson.getType();
        if (dto.getType() != null) {
            effectiveType = LessonType.valueOf(dto.getType().toUpperCase());
            lesson.setType(effectiveType);
            applyLessonContent(lesson, effectiveType, dto.getVideoUrl(), dto.getContent());
        } else if (effectiveType == LessonType.VIDEO && dto.getVideoUrl() != null) {
            lesson.setVideoUrl(dto.getVideoUrl());
        } else if (effectiveType == LessonType.ARTICLE && dto.getContent() != null) {
            lesson.setContent(dto.getContent());
        }

        if (dto.getDescription() != null) {
            lesson.setDescription(dto.getDescription());
        }
        if (dto.getPosition() != null) {
            lesson.setPosition(dto.getPosition());
        }

        CourseLesson saved = lessonRepo.save(lesson);
        touchProductUpdatedAt(section.getCourse());
        return mapLesson(saved);
    }

    @Transactional
    public void deleteLesson(String productId, String sectionId, String lessonId) {
        Product product = loadOwnedProduct(productId);
        if (product.getType() != ProductType.COURSE) {
            throw new UnsupportedProductOperationException("Lessons are only supported for COURSE products.");
        }

        CourseSection section = loadOwnedSection(product.getId(), sectionId);
        CourseLesson lesson = loadLesson(section.getId(), lessonId);

        CourseProduct course = lesson.getSection().getCourse();
        lessonRepo.delete(lesson);
        touchProductUpdatedAt(course);
    }

public void deleteLesson(String userId, String lessonId) {
        Optional<CourseLesson> lessonOptional = lessonRepo.findById(UUID.fromString(lessonId));
        if (lessonOptional.isPresent()) {
            productAuthorizationService.requireOwnerOrAdmin(lessonOptional.get().getSection().getCourse());

            CourseProduct course = lessonOptional.get().getSection().getCourse();
            lessonRepo.delete(lessonOptional.get());
            touchProductUpdatedAt(course);
            log.info("Deleted succesfully a Course lesson: {}", lessonId);
        } else
            throw new ResourceNotFoundException("Course lesson not found for ID: " + lessonId);

}

    private Product loadOwnedProduct(String productId) {
        Product product = productRepository.findById(UUID.fromString(productId))
                .orElseThrow(() -> new ResourceNotFoundException("Product not found: " + productId));

        productAuthorizationService.requireOwnerOrAdmin(product);
        return product;
    }

    private CourseSection loadOwnedSection(UUID productId, String sectionId) {
        CourseSection section = sectionRepo.findById(UUID.fromString(sectionId))
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionId));

        if (!section.getCourse().getId().equals(productId)) {
            throw new ResourceNotFoundException(
                    "Section not found for course " + productId + ": " + sectionId
            );
        }
        return section;
    }

    private CourseLesson loadLesson(UUID sectionId, String lessonId) {
        CourseLesson lesson = lessonRepo.findById(UUID.fromString(lessonId))
                .orElseThrow(() -> new ResourceNotFoundException("Lesson not found: " + lessonId));

        if (!lesson.getSection().getId().equals(sectionId)) {
            throw new ResourceNotFoundException(
                    "Lesson not found for section " + sectionId + ": " + lessonId
            );
        }
        return lesson;
    }

    private CourseLessonResponseDto mapLesson(CourseLesson lesson) {
        CourseLessonResponseDto dto = new CourseLessonResponseDto();
        dto.setId(lesson.getId().toString());
        dto.setTitle(lesson.getTitle());
        dto.setType(lesson.getType().name());
        dto.setVideoUrl(lesson.getVideoUrl());
        dto.setContent(lesson.getContent());
        dto.setDescription(lesson.getDescription());
        dto.setPosition(lesson.getPosition());
        dto.setSectionId(lesson.getSection().getId().toString());
        return dto;
    }

    private void applyLessonContent(CourseLesson lesson, LessonType type, String videoUrl, String content) {
        switch (type) {
            case VIDEO -> {
                lesson.setVideoUrl(videoUrl);
                lesson.setContent(null);
            }
            case ARTICLE -> {
                lesson.setContent(content);
                lesson.setVideoUrl(null);
            }
            case QUIZ -> {
                lesson.setVideoUrl(null);
                lesson.setContent(null);
            }
        }
    }

    private void touchProductUpdatedAt(CourseProduct course) {
        course.setUpdatedAt(LocalDateTime.now());
        courseRepo.save(course);
    }
}

package com.myproject.video.video_platform.service.product;

import com.myproject.video.video_platform.common.enums.s3folders.S3UploadFolder;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.dto.s3_files.ConfirmUploadRequestDto;
import com.myproject.video.video_platform.dto.s3_files.FileS3UploadResponseDto;
import com.myproject.video.video_platform.dto.s3_files.PresignedUrlResponseDto;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.products.download.FileDownloadProduct;
import com.myproject.video.video_platform.entity.products.download.SectionDownloadProduct;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.repository.products.ProductRepository;
import com.myproject.video.video_platform.repository.products.download.DownloadProductRepository;
import com.myproject.video.video_platform.repository.products.download.FileDownloadProductRepository;
import com.myproject.video.video_platform.repository.products.download.SectionDownloadProductRepository;
import com.myproject.video.video_platform.service.digitalocean.SpacesS3Service;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.time.Duration;
import java.time.LocalDateTime;
import java.util.UUID;

@Service
@Slf4j
@RequiredArgsConstructor
public class FilesService {

    @Value("${digitalocean.spaces.cdnEndpointUrl}")
    private String cdnEndpointUrl;

    @Value("${digitalocean.spaces.bucket-media}")
    private String s3mediaBucket;

    private final SpacesS3Service spacesS3Service;
    private final SectionDownloadProductRepository sectionRepository;
    private final DownloadProductRepository downloadProductRepository;
    private final FileDownloadProductRepository fileRepository;
    private final ProductRepository productRepository;
    private final ProductAuthorizationService productAuthorizationService;


    /**
     * Build key, check ownership, sign URL, return all info.
     */
    public PresignedUrlResponseDto generateLegacyPresignedUrl(
            String sectionIdStr,
            String folderTypeStr,
            String filename,
            Duration expiration
    ) {
        SectionDownloadProduct section = authorizeSectionUpload(sectionIdStr);
        S3UploadFolder folder  = S3UploadFolder.fromString(folderTypeStr);
        UUID fileId = UUID.randomUUID();

        String key = buildKey(section, folder, filename, fileId);
        String presigned = spacesS3Service.generatePresignedUrlForPut(key, expiration);
        String fileUrl   = cdnEndpointUrl + "/" + s3mediaBucket + "/" + key;

        PresignedUrlResponseDto dto = new PresignedUrlResponseDto();
        dto.setFileId(fileId.toString());
        dto.setPresignedUrl(presigned);
        dto.setKey(key);
        dto.setFileUrl(fileUrl);
        return dto;
    }

    public PresignedUrlResponseDto generatePresignedUrl(
            String productIdStr,
            String sectionIdStr,
            String filename,
            Duration expiration
    ) {
        SectionDownloadProduct section = authorizeSectionUpload(productIdStr, sectionIdStr);
        UUID fileId = UUID.randomUUID();

        String key = buildKey(section, S3UploadFolder.DOWNLOAD_SECTION_FILES, filename, fileId);
        String presigned = spacesS3Service.generatePresignedUrlForPut(key, expiration);
        String fileUrl = cdnEndpointUrl + "/" + s3mediaBucket + "/" + key;

        PresignedUrlResponseDto dto = new PresignedUrlResponseDto();
        dto.setFileId(fileId.toString());
        dto.setPresignedUrl(presigned);
        dto.setKey(key);
        dto.setFileUrl(fileUrl);
        return dto;
    }

    /** throws if the current user isn’t owner of that section */
    private SectionDownloadProduct authorizeSectionUpload(String sectionIdStr) {
        UUID sectionId = UUID.fromString(sectionIdStr);

        SectionDownloadProduct section = sectionRepository.findById(sectionId)
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionId));

        productAuthorizationService.requireOwnerOrAdmin(section.getDownloadProduct());
        return section;
    }

    private SectionDownloadProduct authorizeSectionUpload(String productIdStr, String sectionIdStr) {
        Product product = productRepository.findById(UUID.fromString(productIdStr))
                .orElseThrow(() -> new ResourceNotFoundException("Product not found: " + productIdStr));

        if (product.getType() != ProductType.DOWNLOAD) {
            throw new UnsupportedProductOperationException("File uploads are only supported for DOWNLOAD products.");
        }

        productAuthorizationService.requireOwnerOrAdmin(product);

        SectionDownloadProduct section = sectionRepository.findById(UUID.fromString(sectionIdStr))
                .orElseThrow(() -> new ResourceNotFoundException("Section not found: " + sectionIdStr));

        if (!section.getDownloadProduct().getId().equals(product.getId())) {
            throw new ResourceNotFoundException(
                    "Section not found for download product " + productIdStr + ": " + sectionIdStr
            );
        }

        return section;
    }

    /** place to construct S3 path for ANY upload type */
    private String buildKey(SectionDownloadProduct section,
                            S3UploadFolder folder,
                            String filename, UUID fileId) {

        String userId     = section.getDownloadProduct().getUser().getUserId().toString();
        String sectionId  = section.getId().toString();
        String safeName   = filename.replaceAll("\\s+", "_");
        return String.join("/",
                "users-content",
                userId,
                folder.getFolderName(),
                sectionId,
                fileId + "_" + safeName
        );
    }

    public FileS3UploadResponseDto confirmUpload(ConfirmUploadRequestDto dto) {
        SectionDownloadProduct section = authorizeSectionUpload(dto.getSectionId());

        FileDownloadProduct fileEntity = new FileDownloadProduct();
        fileEntity.setFileName(dto.getFileName());
        fileEntity.setUserId(section.getDownloadProduct().getUser().getUserId());
        fileEntity.setSection(section);
        fileEntity.setSize(dto.getFileSize());
        fileEntity.setPath(dto.getKey());
        fileEntity.setFileType(dto.getFileType());
        fileEntity.setUploadedAt(LocalDateTime.now());
        fileEntity.setDownloadCount(0);
        fileEntity = fileRepository.save(fileEntity);
        section.getDownloadProduct().setUpdatedAt(LocalDateTime.now());
        downloadProductRepository.save(section.getDownloadProduct());

        FileS3UploadResponseDto resp = new FileS3UploadResponseDto();
        resp.setFileId  (fileEntity.getId().toString());
        resp.setFileName(fileEntity.getFileName());

        resp.setUrl(dto.getFileUrl() != null
                ? dto.getFileUrl()
                : cdnEndpointUrl + "/" + s3mediaBucket + "/" + dto.getKey());
        return resp;
    }

    public FileS3UploadResponseDto confirmUpload(
            String productIdStr,
            String sectionIdStr,
            ConfirmUploadRequestDto dto
    ) {
        SectionDownloadProduct section = authorizeSectionUpload(productIdStr, sectionIdStr);

        FileDownloadProduct fileEntity = new FileDownloadProduct();
        fileEntity.setFileName(dto.getFileName());
        fileEntity.setUserId(section.getDownloadProduct().getUser().getUserId());
        fileEntity.setSection(section);
        fileEntity.setSize(dto.getFileSize());
        fileEntity.setPath(dto.getKey());
        fileEntity.setFileType(dto.getFileType());
        fileEntity.setUploadedAt(LocalDateTime.now());
        fileEntity.setDownloadCount(0);
        fileEntity = fileRepository.save(fileEntity);

        section.getDownloadProduct().setUpdatedAt(LocalDateTime.now());
        downloadProductRepository.save(section.getDownloadProduct());

        FileS3UploadResponseDto resp = new FileS3UploadResponseDto();
        resp.setFileId(fileEntity.getId().toString());
        resp.setFileName(fileEntity.getFileName());
        resp.setUrl(dto.getFileUrl() != null
                ? dto.getFileUrl()
                : cdnEndpointUrl + "/" + s3mediaBucket + "/" + dto.getKey());
        return resp;
    }

    public void deleteFile(String productIdStr, String sectionIdStr, String fileIdStr) {
        SectionDownloadProduct section = authorizeSectionUpload(productIdStr, sectionIdStr);

        FileDownloadProduct file = fileRepository.findById(UUID.fromString(fileIdStr))
                .orElseThrow(() -> new ResourceNotFoundException("File not found: " + fileIdStr));

        if (!file.getSection().getId().equals(section.getId())) {
            throw new ResourceNotFoundException(
                    "File not found for section " + sectionIdStr + ": " + fileIdStr
            );
        }

        fileRepository.delete(file);
        section.getDownloadProduct().setUpdatedAt(LocalDateTime.now());
        downloadProductRepository.save(section.getDownloadProduct());
    }
}

