.legacy-expansion-panel {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  background-color: #fff;
  margin-bottom: 15px;

  &.disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }

  &__header {
    width: 100%;
    background: none;
    border: none;
    padding: 0.75rem 1rem;
    text-align: left;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;

    &:hover:not(:disabled) {
      background-color: #f5f5f5;
    }

    &:focus {
      outline: 2px solid #007bff;
    }
  }

  &__header-text {
    flex: 1;
  }

  &__icon {
    margin-left: 0.5rem;
    transition: transform 0.2s ease;
    font-size: 0.8rem;

    &.expanded {
      transform: rotate(0deg);
    }

    &.collapsed {
      transform: rotate(90deg);
    }
  }

  &__content {
    overflow: hidden;
    transition: max-height 0.3s ease;
    max-height: 0; // collapsed state

    &.open {
      // max-height is set inline via React to content’s scrollHeight
    }
  }

  &__content-inner {
    padding: 0.75rem 1rem;
    border-top: 1px solid #eee;
    background-color: #fafafa;
  }
}

import React, { useState, ReactNode, useRef } from 'react';

import './legacy-expansion-panel.styles.scss';

interface LegacyExpansionPanelProps {
  /** Panel header/title */
  header: string;
  /** Content to show when expanded */
  children: ReactNode;
  /** Whether the panel is open by default */
  defaultExpanded?: boolean;
  /** Whether the panel is disabled (not clickable) */
  disabled?: boolean;
  /** Optional callback when toggled: (isOpen) => void */
  // eslint-disable-next-line no-unused-vars
  onToggle?: (isOpen: boolean) => void;
}

const LegacyExpansionPanel: React.FC<LegacyExpansionPanelProps> = ({
  header,
  children,
  defaultExpanded = false,
  disabled = false,
  onToggle,
}) => {
  const [isOpen, setIsOpen] = useState<boolean>(defaultExpanded);
  const contentRef = useRef<HTMLDivElement>(null);

  const togglePanel = () => {
    if (disabled) {
      return;
    }
    setIsOpen((prev) => {
      const next = !prev;
      onToggle?.(next);
      return next;
    });
  };

  return (
    <div className={`legacy-expansion-panel ${disabled ? 'disabled' : ''}`}>
      <button
        type="button"
        className="expansion-panel__header"
        onClick={togglePanel}
        aria-expanded={isOpen}
        aria-disabled={disabled}
        // aria-controls references the ID of the content region
        aria-controls="expansion-panel-content"
        disabled={disabled}
      >
        <span className="expansion-panel__header-text">{header}</span>
        <span
          className={`expansion-panel__icon ${
            isOpen ? 'expanded' : 'collapsed'
          }`}
          aria-hidden="true"
        >
          {isOpen ? '▾' : '▸'}
        </span>
      </button>

      <div
        id="expansion-panel-content"
        className={`expansion-panel__content ${isOpen ? 'open' : ''}`}
        ref={contentRef}
        role="region"
        aria-labelledby="expansion-panel-header"
        style={{
          maxHeight: isOpen
            ? `${contentRef.current?.scrollHeight ?? 0}px`
            : '0px',
        }}
      >
        <div className="expansion-panel__content-inner">{children}</div>
      </div>
    </div>
  );
};

export default LegacyExpansionPanel;

