package com.myproject.video.video_platform.service.security;


import com.myproject.video.video_platform.entity.user.User;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.filter.OncePerRequestFilter;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.Date;
import java.util.List;

/**
 * Handles generating and validating JWT tokens.
 */
@Service
@RequiredArgsConstructor
@Slf4j
public class JwtProvider {

    @Value("${jwt.secret}")
    private String jwtSecret;

    @Value("${jwt.expiration}")
    private Long jwtExpirationInMillis;

    /**
     * Generate a JWT token for the given email (subject).
     */
    public String generateToken(User user) {
        Date now    = new Date();
        Date expiry = new Date(now.getTime() + jwtExpirationInMillis);

        return Jwts.builder()
                .subject(user.getUserId().toString())
                .claim("email", user.getEmail())
                .claim("roles", user.getRoles().stream()
                        .map(role -> role.getRoleName())
                        .toList())
                .issuedAt(now)
                .expiration(expiry)
                .signWith(getSigningKey())
                .compact();
    }

    /**
     * Validate the JWT token.
     */
    public boolean validateToken(String token) {
        try {
            // If parsing succeeds, the token is valid
            Jwts.parser()
                    .verifyWith(getSigningKey())
                    .build()
                    .parseSignedClaims(token);
            return true;
        } catch (JwtException e) {
            log.error(e.getMessage());
            return false;
        }
    }

    /**
     * Extract the email (subject) from the token.
     */
    public String getEmailFromJwt(String token) {
        Claims claims = Jwts.parser()
                .verifyWith(getSigningKey())
                .build()
                .parseSignedClaims(token)
                .getPayload();

        return claims.get("email", String.class);
    }

    /**
     * Provide a custom JWT authentication filter to be added to the security chain.
     */
    public OncePerRequestFilter jwtAuthenticationFilter() {
        return new JwtAuthenticationFilter(this);
    }

    /**
     * Convert the string secret into a SecretKey for signing.
     */
    private SecretKey getSigningKey() {
        return Keys.hmacShaKeyFor(jwtSecret.getBytes(StandardCharsets.UTF_8));
    }

    public Claims parseClaims(String token) {
        return Jwts.parser()
                .verifyWith(getSigningKey())
                .build()
                .parseSignedClaims(token)
                .getPayload();
    }

    public String getSubjectFromJwt(String token) {
        return parseClaims(token).getSubject();
    }

    @SuppressWarnings("unchecked")
    public List<String> getRolesFromJwt(String token) {
        Object roles = parseClaims(token).get("roles");
        if (roles instanceof List<?>) {
            return ((List<?>) roles).stream()
                    .filter(String.class::isInstance)
                    .map(String.class::cast)
                    .toList();
        }
        return Collections.emptyList();
    }
}

package com.myproject.video.video_platform.service.admin;

import com.myproject.video.video_platform.common.enums.user.UserRole;
import com.myproject.video.video_platform.dto.admin.AdminUserDto;
import com.myproject.video.video_platform.entity.user.Role;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.user.UserNotFoundException;
import com.myproject.video.video_platform.repository.auth.RoleRepository;
import com.myproject.video.video_platform.repository.auth.UserRepository;
import com.myproject.video.video_platform.service.security.RefreshTokenService;
import jakarta.persistence.criteria.Join;
import jakarta.persistence.criteria.Predicate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.domain.Specification;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;

@Service
public class AdminUserService {

    private final UserRepository userRepository;
    private final RoleRepository roleRepository;
    private final RefreshTokenService refreshTokenService;
    private final AdminAuditService auditService;

    public AdminUserService(UserRepository userRepository,
                            RoleRepository roleRepository,
                            RefreshTokenService refreshTokenService,
                            AdminAuditService auditService) {
        this.userRepository = userRepository;
        this.roleRepository = roleRepository;
        this.refreshTokenService = refreshTokenService;
        this.auditService = auditService;
    }

    @Transactional(readOnly = true)
    public Page<AdminUserDto> searchUsers(String search, UserRole role, Pageable pageable) {
        return userRepository.findAll(userSpec(search, role), pageable).map(this::toDto);
    }

    @Transactional
    public AdminUserDto updateRole(String userId, UserRole nextRole) {
        User user = userRepository.findById(UUID.fromString(userId))
                .orElseThrow(() -> new UserNotFoundException("User not found: " + userId));

        String previousRole = singleRoleName(user);
        if (UserRole.ADMIN.name().equals(previousRole)
                && nextRole != UserRole.ADMIN
                && userRepository.countByRoleName(UserRole.ADMIN.name()) <= 1) {
            throw new AccessDeniedException("Cannot remove the last admin");
        }

        Role role = roleRepository.findByRoleName(nextRole.name());
        if (role == null) {
            throw new IllegalStateException("Role " + nextRole.name() + " is missing from the database");
        }

        user.setRoles(new HashSet<>(Set.of(role)));
        User saved = userRepository.save(user);
        refreshTokenService.deleteRefreshTokensForUser(saved.getEmail());

        auditService.recordCurrentAdminAction(
                "ROLE_CHANGE",
                "USER",
                saved.getUserId().toString(),
                previousRole,
                nextRole.name()
        );

        return toDto(saved);
    }

    private Specification<User> userSpec(String search, UserRole role) {
        return (root, query, cb) -> {
            if (query != null) {
                query.distinct(true);
            }
            List<Predicate> predicates = new ArrayList<>();
            if (search != null && !search.isBlank()) {
                String term = "%" + search.trim().toLowerCase() + "%";
                predicates.add(cb.or(
                        cb.like(cb.lower(root.get("firstName")), term),
                        cb.like(cb.lower(root.get("lastName")), term),
                        cb.like(cb.lower(root.get("email")), term)
                ));
            }
            if (role != null) {
                Join<User, Role> roleJoin = root.join("roles");
                predicates.add(cb.equal(roleJoin.get("roleName"), role.name()));
            }
            return cb.and(predicates.toArray(Predicate[]::new));
        };
    }

    private AdminUserDto toDto(User user) {
        return AdminUserDto.builder()
                .id(user.getUserId().toString())
                .firstName(user.getFirstName())
                .lastName(user.getLastName())
                .email(user.getEmail())
                .roles(user.getRoles().stream().map(Role::getRoleName).toList())
                .enabled(user.isEnabled())
                .authProvider(user.getAuthProvider())
                .onboardingCompleted(user.isOnboardingcompleted())
                .createdAt(user.getCreatedAt())
                .build();
    }

    private String singleRoleName(User user) {
        return user.getRoles().stream()
                .findFirst()
                .map(Role::getRoleName)
                .orElse(null);
    }
}

package com.myproject.video.video_platform.controller.admin;

import com.myproject.video.video_platform.common.enums.products.ProductStatus;
import com.myproject.video.video_platform.common.enums.products.ProductType;
import com.myproject.video.video_platform.common.enums.user.UserRole;
import com.myproject.video.video_platform.dto.admin.AdminAuditLogDto;
import com.myproject.video.video_platform.dto.admin.AdminRoleUpdateRequest;
import com.myproject.video.video_platform.dto.admin.AdminUserDto;
import com.myproject.video.video_platform.dto.products.ProductMinimised;
import com.myproject.video.video_platform.service.admin.AdminAuditService;
import com.myproject.video.video_platform.service.admin.AdminProductService;
import com.myproject.video.video_platform.service.admin.AdminUserService;
import jakarta.validation.Valid;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.web.PageableDefault;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/admin")
@PreAuthorize("hasRole('ADMIN')")
public class AdminController {

    private final AdminUserService adminUserService;
    private final AdminProductService adminProductService;
    private final AdminAuditService adminAuditService;

    public AdminController(AdminUserService adminUserService,
                           AdminProductService adminProductService,
                           AdminAuditService adminAuditService) {
        this.adminUserService = adminUserService;
        this.adminProductService = adminProductService;
        this.adminAuditService = adminAuditService;
    }

    @GetMapping("/users")
    public Page<AdminUserDto> users(
            @RequestParam(required = false) String search,
            @RequestParam(required = false) UserRole role,
            @PageableDefault(size = 20, sort = "createdAt") Pageable pageable) {
        return adminUserService.searchUsers(search, role, pageable);
    }

    @PatchMapping("/users/{userId}/role")
    public AdminUserDto updateRole(@PathVariable String userId,
                                   @Valid @RequestBody AdminRoleUpdateRequest request) {
        return adminUserService.updateRole(userId, request.getRole());
    }

    @GetMapping("/products")
    public Page<ProductMinimised> products(
            @RequestParam(required = false) String search,
            @RequestParam(required = false) String ownerId,
            @RequestParam(required = false) ProductType type,
            @RequestParam(required = false) ProductStatus status,
            @PageableDefault(size = 20, sort = "createdAt") Pageable pageable) {
        return adminProductService.searchProducts(search, ownerId, type, status, pageable);
    }

    @GetMapping("/audit")
    public Page<AdminAuditLogDto> audit(
            @RequestParam(required = false) String actorId,
            @RequestParam(required = false) String targetType,
            @RequestParam(required = false) String targetId,
            @RequestParam(required = false) String action,
            @PageableDefault(size = 20, sort = "createdAt") Pageable pageable) {
        return adminAuditService.search(actorId, targetType, targetId, action, pageable);
    }
}

import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import { AppDispatch, UserRole } from 'core/api/models';
import {
  fetchAdminUsers,
  selectAdminError,
  selectAdminLoading,
  selectAdminUsersPage,
  selectRoleUpdatingUserId,
  updateAdminUserRole,
} from 'core/store/admin-store';

import './admin-page.styles.scss';

const roles = [UserRole.ADMIN, UserRole.CREATOR, UserRole.USER];

const AdminUsersPage: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const usersPage = useSelector(selectAdminUsersPage);
  const loading = useSelector(selectAdminLoading);
  const error = useSelector(selectAdminError);
  const roleUpdatingUserId = useSelector(selectRoleUpdatingUserId);
  const [search, setSearch] = useState('');
  const [role, setRole] = useState<UserRole | ''>('');
  const [page, setPage] = useState(0);

  useEffect(() => {
    dispatch(fetchAdminUsers({ search, role, page, size: 20 }));
  }, [dispatch, search, role, page]);

  const handleRoleChange = (userId: string, nextRole: UserRole) => {
    dispatch(updateAdminUserRole({ userId, role: nextRole }));
  };

  return (
    <section className="admin-page">
      <header className="admin-page__header">
        <h1>Users</h1>
        <p>Role changes replace the user role and force re-login.</p>
      </header>

      <div className="admin-toolbar">
        <input
          aria-label="Search users"
          placeholder="Search name or email"
          value={search}
          onChange={(event) => {
            setPage(0);
            setSearch(event.target.value);
          }}
        />
        <select
          aria-label="Filter by role"
          value={role}
          onChange={(event) => {
            setPage(0);
            setRole(event.target.value as UserRole | '');
          }}
        >
          <option value="">All roles</option>
          {roles.map((item) => (
            <option key={item} value={item}>
              {item}
            </option>
          ))}
        </select>
      </div>

      {error && <p className="admin-error">{error}</p>}
      {loading && <p>Loading...</p>}

      <div className="admin-table-wrap">
        <table className="admin-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Role</th>
              <th>Provider</th>
              <th>Status</th>
              <th>Created</th>
            </tr>
          </thead>
          <tbody>
            {usersPage?.content.map((user) => {
              const currentRole = user.roles[0] ?? UserRole.USER;
              return (
                <tr key={user.id}>
                  <td>{`${user.firstName ?? ''} ${user.lastName ?? ''}`.trim()}</td>
                  <td>{user.email}</td>
                  <td>
                    <select
                      aria-label={`Role for ${user.email}`}
                      value={currentRole}
                      disabled={roleUpdatingUserId === user.id}
                      onChange={(event) =>
                        handleRoleChange(user.id, event.target.value as UserRole)
                      }
                    >
                      {roles.map((item) => (
                        <option key={item} value={item}>
                          {item}
                        </option>
                      ))}
                    </select>
                  </td>
                  <td>{user.authProvider ?? 'manual'}</td>
                  <td>{user.enabled === false ? 'Disabled' : 'Enabled'}</td>
                  <td>{user.createdAt ? new Date(user.createdAt).toLocaleString() : '-'}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="admin-pagination">
        <button disabled={page === 0} onClick={() => setPage((value) => value - 1)}>
          Previous
        </button>
        <span>
          Page {usersPage ? usersPage.number + 1 : page + 1} of{' '}
          {usersPage?.totalPages || 1}
        </span>
        <button
          disabled={Boolean(usersPage?.last)}
          onClick={() => setPage((value) => value + 1)}
        >
          Next
        </button>
      </div>
    </section>
  );
};

export default AdminUsersPage;

