            <dd>{customer.location || 'Unavailable'}</dd>
          </div>
          <div>
            <dt>Language</dt>
            <dd>{customer.language || 'Unavailable'}</dd>
          </div>
          <div>
            <dt>Timezone</dt>
            <dd>{customer.timezone || 'Unavailable'}</dd>
          </div>
          <div>
            <dt>Customer since</dt>
            <dd>{formatCustomerDate(customer.customerSince)}</dd>
          </div>
        </dl>
