        <input
          aria-label="Target type"
          placeholder="Target type"
          value={targetType}
          onChange={(event) => {
            setPage(0);
            setTargetType(event.target.value);
          }}
        />
        <input
          aria-label="Target id"
          placeholder="Target id"
          value={targetId}
          onChange={(event) => {
            setPage(0);
            setTargetId(event.target.value);
          }}
        />
