              <th>Actor</th>
              <th>Action</th>
              <th>Target</th>
              <th>Before</th>
              <th>After</th>
            </tr>
          </thead>
          <tbody>
            {auditPage?.content.map((entry) => (
              <tr key={entry.id}>
                <td>{new Date(entry.createdAt).toLocaleString()}</td>
                <td>{entry.actorUserId}</td>
                <td>{entry.action}</td>
                <td>
                  <span>{entry.targetType}</span>
                  <small>{entry.targetId}</small>
                </td>
