import '@uppy/dashboard/dist/style.css';

interface UppyFileUploaderProps {
  // Callback to receive the list of native File objects
  // eslint-disable-next-line no-unused-vars
  onFilesChange?: (files: File[]) => void;
  // Allowed file types, e.g., ['image/*'] for image uploads
  allowedFileTypes?: string[];
  // Maximum number of files allowed
  maxNumberOfFiles?: number;
  // Maximum file size (in bytes)
  maxFileSize?: number;

  /**
   * If true, do not load any “import/Companion” plugins (GoogleDrive, Dropbox, etc.)
   */
  disableImporters?: boolean;
  uploadMode?: 'UPLOAD' | 'SELECT_ONLY';
  note?: string;
}

const UppyFileUploader: React.FC<UppyFileUploaderProps> = ({
  // eslint-disable-next-line @typescript-eslint/no-empty-function
  onFilesChange = () => {},
  allowedFileTypes, // default to image uploads
  maxNumberOfFiles,
  maxFileSize = 5 * 1024 * 1024, // default to 5 MB
  disableImporters = false,
  uploadMode = 'UPLOAD',
  note,
}) => {
  // Use state to hold the Uppy instance so that re-render occurs when it’s created
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const [uppy, setUppy] = useState<UppyType<any, any> | null>(null);
  const memoizedOnFilesChange = useCallback(onFilesChange, [onFilesChange]);

  useEffect(() => {
    // Create the Uppy instance with the provided restrictions
    const uppyInstance = new Uppy({
      restrictions: {
        maxNumberOfFiles: maxNumberOfFiles || 10,
        allowedFileTypes: allowedFileTypes || ['video/*', 'audio/*', 'text/*'],
        maxFileSize: maxFileSize || 100 * 1024 * 1024, // 100 MB in bytes
      },
      autoProceed: false,
      locale: en_US,
    });

    if (uploadMode === 'UPLOAD') {
      // Configure the upload endpoint (adjust '/upload' as needed)
      uppyInstance.use(XHRUpload, {
        endpoint: '/upload',
        fieldName: 'file',
        formData: true,
      });
    }

    // Add additional plugins with the default Companion service

    if (!disableImporters) {
      uppyInstance.use(GoogleDrive, {
        companionUrl: 'https://companion.uppy.io',
      });
      uppyInstance.use(Dropbox, { companionUrl: 'https://companion.uppy.io' });
      uppyInstance.use(OneDrive, { companionUrl: 'https://companion.uppy.io' });
      uppyInstance.use(Url, { companionUrl: 'https://companion.uppy.io' });
      uppyInstance.use(Unsplash, { companionUrl: 'https://companion.uppy.io' });
    }

    // If image uploads are allowed, add the ThumbnailGenerator plugin
    if (allowedFileTypes && allowedFileTypes.includes('image/*')) {
      uppyInstance.use(ThumbnailGenerator, {
        thumbnailWidth: 200,
        waitForThumbnailsBeforeUpload: true,
      });
    }

    // Listen for file-added and file-removed events to update the file list
    const updateFiles = () => {
      const files: File[] = uppyInstance
        .getFiles()
        .map((file) => file.data as File);
      memoizedOnFilesChange(files);
    };

    uppyInstance.on('file-added', updateFiles);
    uppyInstance.on('file-removed', updateFiles);

    // Optionally, listen for progress or thumbnail events for debugging
    uppyInstance.on('upload-progress', (file, progress) => {
      const percent = progress.bytesTotal
        ? Math.round((progress.bytesUploaded / progress.bytesTotal) * 100)
        : 0;
      console.log(`Uploading ${file?.name}: ${percent}%`);
    });
    uppyInstance.on('thumbnail:generated', (file, preview) => {
      console.log(`Thumbnail generated for ${file.name}`, preview);
    });

    // Save the instance in state so that the Dashboard renders
    setUppy(uppyInstance);

    // Cleanup on unmount
    return () => {
      // if (uppyInstance && typeof uppyInstance.destroy === 'function') {
      uppyInstance.destroy();
      // }
    };
  }, [
    allowedFileTypes,
    maxFileSize,
    maxNumberOfFiles,
    memoizedOnFilesChange,
    disableImporters,
    uploadMode,
  ]);

  // const mergedLocale: Locale<number> | undefined = customDropText ? {...en_US, strings: {
  //         ...en_US.strings,
  //         dropPasteImport: customDropText,
  //       },
  //     }
  //   : undefined;

  return (
    <div className="custom-uppy-dashboard">
      {uppy ? (
        <Dashboard
          uppy={uppy}
          plugins={
            disableImporters
              ? []
              : ['GoogleDrive', 'Dropbox', 'OneDrive', 'Url', 'Unsplash']
          }
          height={disableImporters ? 200 : 200}
          note={note}
          hideUploadButton={true}
          proudlyDisplayPoweredByUppy={true}
        />
      ) : (
        <p>Initializing uploader...</p>
      )}
    </div>
  );
};

export default UppyFileUploader;

import React, { useState } from 'react';

import { Button, UppyFileUploader, Input, Select, Textarea } from '@shared/ui';
import {
  MembershipContentStatus,
  MEMBERSHIP_CONTENT_STATUS_OPTIONS,
  MembershipVideoDraft,
  createMembershipVideoFileRef,
  formatMembershipFileSize,
} from './models';

interface MembershipVideoEditorProps {
  value: MembershipVideoDraft;
  // eslint-disable-next-line no-unused-vars
  onChange: (value: MembershipVideoDraft) => void;
  onSave: () => Promise<void> | void;
  onCancel: () => void;
  isSaving?: boolean;
  saveError?: string | null;
  saveLabel?: string;
}

const VIDEO_ALLOWED_FILE_TYPES = ['video/*'];
const MAX_VIDEO_FILE_SIZE = 500 * 1024 * 1024;

const isValidVideoDraft = (value: MembershipVideoDraft) =>
  value.title.trim().length > 0 && Boolean(value.video);

const MembershipVideoEditor: React.FC<MembershipVideoEditorProps> = ({
  value,
  onChange,
  onSave,
  onCancel,
  isSaving = false,
  saveError,
  saveLabel = 'Save',
}) => {
  const [hasSubmitted, setHasSubmitted] = useState(false);
  const titleError =
    hasSubmitted && !value.title.trim() ? 'Enter a video title.' : undefined;
  const videoError =
    hasSubmitted && !value.video ? 'Select a video file.' : undefined;

  const handleFilesChange = (files: File[]) => {
    const selectedVideo = files[0];

    onChange({
      ...value,
      video: selectedVideo ? createMembershipVideoFileRef(selectedVideo) : null,
    });
  };

  const handleSave = () => {
    setHasSubmitted(true);

    if (!isValidVideoDraft(value)) {
      return;
    }

    onSave();
  };

  return (
    <div className="membership-video-editor">
      <Input
        name="membership-video-title"
        label="Title"
        value={value.title}
        placeholder="Video title"
        error={titleError}
        onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
          onChange({ ...value, title: event.target.value })
        }
      />

      <Textarea
        name="membership-video-description"
        label="Description"
        value={value.description}
        placeholder="Describe this member-only video"
        block
        onChange={(event: React.ChangeEvent<HTMLTextAreaElement>) =>
          onChange({ ...value, description: event.target.value })
        }
      />

      <div className="membership-video-editor__video">
        <div className="membership-content-editor__field-heading">
          <span id="membership-video-file-label">Selected video</span>
          <small>
            Video upload will be connected when media storage is available.
          </small>
        </div>
        <UppyFileUploader
          allowedFileTypes={VIDEO_ALLOWED_FILE_TYPES}
          maxNumberOfFiles={1}
          maxFileSize={MAX_VIDEO_FILE_SIZE}
          disableImporters
          uploadMode="SELECT_ONLY"
          onFilesChange={handleFilesChange}
        />
        {videoError && (
          <span className="input-error-message" role="alert">
            {videoError}
          </span>
        )}
        {value.video && (
          <p className="membership-video-editor__selected">
            Selected file: {value.video.fileName} (
            {formatMembershipFileSize(value.video.size)})
          </p>
        )}
      </div>

      <Select
        name="membership-video-status"
        label="Status"
        value={value.status}
        options={MEMBERSHIP_CONTENT_STATUS_OPTIONS}
        onChange={(event: React.ChangeEvent<HTMLSelectElement>) =>
          onChange({
            ...value,
            status: event.target.value as MembershipContentStatus,
          })
        }
      />

      {saveError && (
        <p className="membership-content-editor__error" role="alert">
          {saveError}
        </p>
      )}

      <div className="membership-video-editor__actions">
        <Button
          type="button"
          variant="tertiary"
          onClick={onCancel}
          disabled={isSaving}
        >
          Cancel
        </Button>
        <Button
          type="button"
          variant="primary"
          onClick={handleSave}
          loading={isSaving}
        >
          {saveLabel}
        </Button>
      </div>
    </div>
  );
};

