package com.myproject.video.video_platform.service.security;

import com.myproject.video.video_platform.dto.authetication.LoginRequest;
import com.myproject.video.video_platform.dto.authetication.RegisterRequest;
import com.myproject.video.video_platform.common.enums.user.UserRole;
import com.myproject.video.video_platform.entity.user.Role;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.auth.AuthenticationException;
import com.myproject.video.video_platform.exception.user.UserNotFoundException;
import com.myproject.video.video_platform.repository.auth.RoleRepository;
import com.myproject.video.video_platform.repository.auth.UserRepository;
import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.Collections;
import java.util.Optional;
import java.util.UUID;

/**
 * Handles user registration and login logic.
 */
@Slf4j
@Service
public class AuthService {

    @Value("${app.domain}")
    private String appDomain;

    private final UserRepository userRepository;
    private final RoleRepository roleRepository;
    private final PasswordEncoder passwordEncoder;
    private final VerificationTokenService verificationTokenService;
    private final JwtProvider jwtProvider;
    private final RefreshTokenService refreshTokenService;
    private final CsrfProvider csrfProvider;

    public AuthService(UserRepository userRepository,
                       RoleRepository roleRepository,
                       PasswordEncoder passwordEncoder,
                       VerificationTokenService verificationTokenService,
                       JwtProvider jwtProvider,
                       RefreshTokenService refreshTokenService,
                       CsrfProvider csrfProvider) {
        this.userRepository = userRepository;
        this.roleRepository = roleRepository;
        this.passwordEncoder = passwordEncoder;
        this.verificationTokenService = verificationTokenService;
        this.jwtProvider = jwtProvider;
        this.refreshTokenService = refreshTokenService;
        this.csrfProvider = csrfProvider;
    }

    public void register(RegisterRequest request) {
        log.info("Register request: {}", request);

        Optional<User> userOptional = userRepository.findByEmail(request.getEmail());
        if (userOptional.isPresent()) {
            throw new AuthenticationException("User already exists with same email: " + request.getEmail());
        } else {
            User user = new User();
            user.setUserId(UUID.randomUUID());
            user.setFirstName(request.getFirstName());
            user.setLastName(request.getLastName());
            user.setEmail(request.getEmail());
            user.setPassword(passwordEncoder.encode(request.getPassword()));
            user.setEnabled(false);
            user.setOnboardingcompleted(false);

            Role userRole = getRequiredDefaultUserRole();
            user.setRoles(Collections.singleton(userRole));

            userRepository.save(user);
            log.info("User registered and token will be sent : {}", user);

            verificationTokenService.createAndSendToken(user);
            //TODO: send welcome email
        }
    }

    public void login(LoginRequest request, HttpServletResponse response) {
        User user = userRepository.findByEmail(request.getEmail()).orElseThrow(
                () -> new UserNotFoundException("No account with email: " + request.getEmail()) {});

        if (!passwordEncoder.matches(request.getPassword(), user.getPassword()))
            throw new AuthenticationException("Invalid credentials");

        if (!user.isEnabled())
            throw new AuthenticationException("User account not verified");

        setAuthCookies(response, user.getEmail());
    }

    public void logout(HttpServletResponse response) {
        // Clear cookies
        Cookie jwtCookie = new Cookie("JWT_TOKEN", null);
        jwtCookie.setHttpOnly(true);
        jwtCookie.setSecure(true);
        jwtCookie.setPath("/");
        jwtCookie.setDomain(appDomain);
        jwtCookie.setMaxAge(0);

        Cookie refreshCookie = new Cookie("REFRESH_TOKEN", null);
        refreshCookie.setHttpOnly(true);
        refreshCookie.setSecure(true);
        refreshCookie.setPath("/");
        refreshCookie.setMaxAge(0);
        refreshCookie.setDomain(appDomain);
        response.addCookie(refreshCookie);

        Cookie csrfCookie = new Cookie("XSRF-TOKEN", null);
        csrfCookie.setHttpOnly(false);
        csrfCookie.setSecure(true);
        csrfCookie.setDomain(appDomain);
        csrfCookie.setPath("/");
        csrfCookie.setMaxAge(0);

        response.addCookie(jwtCookie);
        response.addCookie(csrfCookie);
    }

    /**
     * Called when user wants to refresh the JWT using the refresh token.
     */
    @Transactional
    public void refreshTokens(HttpServletResponse response, String oldRefreshToken) {
        String userEmail = refreshTokenService.validateRefreshToken(oldRefreshToken);
        refreshTokenService.deleteRefreshToken(oldRefreshToken);
        setAuthCookies(response, userEmail);
    }

    public String extractCookie(HttpServletRequest request, String cookieName) {
        if (request.getCookies() != null) {
            for (Cookie c : request.getCookies()) {
                if (cookieName.equals(c.getName())) {
                    return c.getValue();
                }
            }
        }
        return null;
    }

    public void setAuthCookies(HttpServletResponse response,
                                String userEmail) {

        User user = userRepository.findByEmail(userEmail)
                .orElseThrow(() -> new UserNotFoundException("No account with email: " + userEmail));

        String jwtToken = jwtProvider.generateToken(user);
        String csrfToken = csrfProvider.generateCsrfToken();
        String refreshToken = refreshTokenService.createRefreshToken(userEmail);

        // JWT Cookie
        Cookie jwtCookie = new Cookie("JWT_TOKEN", jwtToken);
        jwtCookie.setHttpOnly(true);
        jwtCookie.setSecure(true);
        jwtCookie.setPath("/");
        jwtCookie.setMaxAge(3600);
        jwtCookie.setDomain(appDomain);
        jwtCookie.setAttribute("SameSite", "None");
        response.addCookie(jwtCookie);

        // Refresh Cookie
        Cookie refreshCookie = new Cookie("REFRESH_TOKEN", refreshToken);
        refreshCookie.setHttpOnly(true);
        refreshCookie.setSecure(true);
        refreshCookie.setPath("/");
        refreshCookie.setMaxAge(7 * 24 * 60 * 60); // 7 days
        refreshCookie.setDomain(appDomain);
        refreshCookie.setAttribute("SameSite", "None");
        response.addCookie(refreshCookie);

        // CSRF Cookie
        Cookie csrfCookie = new Cookie("XSRF-TOKEN", csrfToken);
        csrfCookie.setHttpOnly(false);
        csrfCookie.setSecure(true);
        csrfCookie.setAttribute("SameSite", "None");
        csrfCookie.setDomain(appDomain);
        csrfCookie.setPath("/");
        csrfCookie.setMaxAge(3600);
        response.addCookie(csrfCookie);
    }

    private Role getRequiredDefaultUserRole() {
        Role userRole = roleRepository.findByRoleName(UserRole.USER.name());
        if (userRole == null) {
            throw new IllegalStateException("Default role USER is missing from the database");
        }
        return userRole;
    }
}

package com.myproject.video.video_platform.service.security;


import com.myproject.video.video_platform.exception.auth.CsrfException;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;

@Slf4j
@Component
public class CsrfFilter extends OncePerRequestFilter {

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain)
            throws ServletException, IOException {

        String method = request.getMethod();
        String path = request.getRequestURI();
        // We only check CSRF for state-changing methods
        // AND we skip /api/auth/login (and optionally /api/auth/logout).
        if ((method.equalsIgnoreCase("POST")
                || method.equalsIgnoreCase("PUT")
                || method.equalsIgnoreCase("PATCH")
                || method.equalsIgnoreCase("DELETE"))
                && !path.equals("/api/auth/login")
                && !path.equals("/api/auth/logout")
                && !path.equals("/api/auth/refresh")
                && !path.equals("/api/auth/googleSignIn")) {

            String csrfCookie = extractCookie(request);
            String csrfHeader = request.getHeader("X-XSRF-TOKEN");

            if (csrfCookie == null || !csrfCookie.equals(csrfHeader)) {
                throw new CsrfException("CSRF token mismatch or missing.");
            }
        }

        filterChain.doFilter(request, response);
    }

    private String extractCookie(HttpServletRequest request) {
        if (request.getCookies() != null) {
            for (Cookie c : request.getCookies()) {
                if ("XSRF-TOKEN".equals(c.getName())) {
                    return c.getValue();
                }
            }
        }
        return null;
    }
}

package com.myproject.video.video_platform.service.security;

import com.myproject.video.video_platform.dto.authetication.TokenRequest;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.entity.auth.VerificationToken;
import com.myproject.video.video_platform.exception.auth.TokenExpiredException;
import com.myproject.video.video_platform.repository.auth.UserRepository;
import com.myproject.video.video_platform.repository.auth.VerificationTokenRepository;
import com.myproject.video.video_platform.service.mail.EmailService;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Optional;
import java.util.UUID;

/**
 * Service for creating and verifying email tokens.
 */
@Slf4j
@Service
public class VerificationTokenService {

    @Value("${app.frontend.url}")
    private String frontendUrl;

    private final VerificationTokenRepository tokenRepository;
    private final UserRepository userRepository;
    private final EmailService emailService;

    public VerificationTokenService(VerificationTokenRepository tokenRepository,
                                    UserRepository userRepository,
                                    EmailService emailService) {
        this.tokenRepository = tokenRepository;
        this.userRepository = userRepository;
        this.emailService = emailService;
    }

    public void createAndSendToken(User user) {
        String token = UUID.randomUUID().toString();
        VerificationToken verificationToken = new VerificationToken(
                token,
                user,
                Instant.now().plusSeconds(86400) // 1 day expiry
        );
        log.info("Create token for user: {}", user);
        tokenRepository.save(verificationToken);

        String link = frontendUrl + "/verify-email?token=" + token;
        emailService.sendVerificationEmail(user.getEmail(), link);
    }

    public void verifyToken(TokenRequest token) throws TokenExpiredException {
        Optional<VerificationToken> optionalToken = tokenRepository.findByToken(token.getToken());
        VerificationToken verificationToken = optionalToken.orElseThrow(
                () -> new RuntimeException("Invalid token!")
        );

        // Check expiry
        if (verificationToken.getExpiryDate().isBefore(Instant.now())) {
            throw new TokenExpiredException("Token expired!");
        }

        // Enable the user
        User user = verificationToken.getUser();
        user.setEnabled(true);
        userRepository.save(user);

        // Token used -> remove it or keep it for records
        tokenRepository.delete(verificationToken);
    }
}

package com.myproject.video.video_platform.exception;

import com.myproject.video.video_platform.dto.authetication.ErrorResponse;
import com.myproject.video.video_platform.dto.authetication.ValidationErrorResponse;
import com.myproject.video.video_platform.exception.auth.AuthenticationException;
import com.myproject.video.video_platform.exception.auth.CsrfException;
import com.myproject.video.video_platform.exception.auth.InvalidTokenException;
import com.myproject.video.video_platform.exception.auth.TokenExpiredException;
import com.myproject.video.video_platform.exception.auth.UserAlreadyExistingException;
import com.myproject.video.video_platform.exception.commerce.CommerceException;
import com.myproject.video.video_platform.exception.email.EmailSendingException;
import com.myproject.video.video_platform.exception.product.InvalidProductTypeException;
import com.myproject.video.video_platform.exception.product.PaymentRequiredException;
import com.myproject.video.video_platform.exception.product.ProductPublicationValidationException;
import com.myproject.video.video_platform.exception.product.ProductMediaException;
import com.myproject.video.video_platform.exception.product.QuizValidationException;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.product.UnsupportedProductOperationException;
import com.myproject.video.video_platform.exception.user.UserNotFoundException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(CommerceException.class)
    public ResponseEntity<ErrorResponse> handleCommerceException(CommerceException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), ex.getStatus().value());
        return new ResponseEntity<>(error, ex.getStatus());
    }

    @ExceptionHandler(AuthenticationException.class)
    public ResponseEntity<ErrorResponse> handleAuthenticationException(AuthenticationException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.UNAUTHORIZED.value());
        return new ResponseEntity<>(error, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(TokenExpiredException.class)
    public ResponseEntity<ErrorResponse> handleTokenExpiredException(TokenExpiredException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.UNAUTHORIZED.value());
        return new ResponseEntity<>(error, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGenericException(Exception ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value());
        return new ResponseEntity<>(error, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(UserNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleUserNotFoundException(UserNotFoundException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.NOT_FOUND.value());
        return new ResponseEntity<>(error, HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(EmailSendingException.class)
    public ResponseEntity<ErrorResponse> handleEmailSendingException(EmailSendingException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value());
        return new ResponseEntity<>(error, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ValidationErrorResponse> handleValidationExceptions(
            MethodArgumentNotValidException ex) {

        // Collect all field errors
        List<FieldError> fieldErrors = ex.getBindingResult().getFieldErrors();

        // Build a list or map of field -> error messages
        Map<String, String> errors = new HashMap<>();
        for (FieldError fieldError : fieldErrors) {
            errors.put(fieldError.getField(), fieldError.getDefaultMessage());
        }

        ValidationErrorResponse response = new ValidationErrorResponse(
                "Validation failed",
                errors
        );

        return new ResponseEntity<>(response, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(CsrfException.class)
    public ResponseEntity<ErrorResponse> handleCsrfException(CsrfException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.FORBIDDEN.value());
        return new ResponseEntity<>(error, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(AccessDeniedException.class)
    public ResponseEntity<ErrorResponse> handleAccessDeniedException(AccessDeniedException ex) {
        ErrorResponse error = new ErrorResponse("Access Denied", HttpStatus.FORBIDDEN.value());
        return new ResponseEntity<>(error, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(UserAlreadyExistingException.class)
    public ResponseEntity<ErrorResponse> handleUserAlreadyExistingException(UserAlreadyExistingException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value());
        return new ResponseEntity<>(error, HttpStatus.FORBIDDEN);
    }

    @ExceptionHandler(InvalidProductTypeException.class)
    public ResponseEntity<ErrorResponse> handleInvalidProductTypeException(InvalidProductTypeException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value());
        return new ResponseEntity<>(error, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(InvalidTokenException.class)
    public ResponseEntity<ErrorResponse> handleInvalidTokenException(InvalidTokenException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.UNAUTHORIZED.value());
        return new ResponseEntity<>(error, HttpStatus.UNAUTHORIZED);
    }

    @ExceptionHandler(ResourceNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleInvalidTokenException(ResourceNotFoundException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.NOT_FOUND.value());
        return new ResponseEntity<>(error, HttpStatus.NOT_FOUND);
    }

    @ExceptionHandler(QuizValidationException.class)
    public ResponseEntity<ValidationErrorResponse> handleQuizValidationException(QuizValidationException ex) {
        ValidationErrorResponse response = new ValidationErrorResponse(
                ex.getMessage(),
                ex.getErrors()
        );
        return new ResponseEntity<>(response, HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(ProductPublicationValidationException.class)
    public ResponseEntity<ValidationErrorResponse> handlePublicationValidation(
            ProductPublicationValidationException ex
    ) {
        return new ResponseEntity<>(
                new ValidationErrorResponse(ex.getMessage(), ex.getErrors()),
                HttpStatus.UNPROCESSABLE_ENTITY
        );
    }

    @ExceptionHandler(ProductMediaException.class)
    public ResponseEntity<ErrorResponse> handleProductMediaException(ProductMediaException ex) {
        return new ResponseEntity<>(new ErrorResponse(ex.getMessage(), HttpStatus.BAD_REQUEST.value()), HttpStatus.BAD_REQUEST);
    }

    @ExceptionHandler(UnsupportedProductOperationException.class)
    public ResponseEntity<ErrorResponse> handleUnsupportedProductOperationException(
            UnsupportedProductOperationException ex
    ) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.CONFLICT.value());
        return new ResponseEntity<>(error, HttpStatus.CONFLICT);
    }

    @ExceptionHandler(PaymentRequiredException.class)
    public ResponseEntity<ErrorResponse> handlePaymentRequiredException(PaymentRequiredException ex) {
        ErrorResponse error = new ErrorResponse(ex.getMessage(), HttpStatus.PAYMENT_REQUIRED.value());
        return new ResponseEntity<>(error, HttpStatus.PAYMENT_REQUIRED);
    }
}

