import { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';

let isRefreshing = false;
let failedQueue: Array<{
  resolve: (token: string) => void;
  reject: (error: unknown) => void;
}> = [];

const processQueue = (error: unknown, token: string | null = null) => {
  failedQueue.forEach((prom) => {
    if (error) {
      prom.reject(error);
    } else if (token) {
      prom.resolve(token);
    }
  });
  failedQueue = [];
};

/**
 * Attaches a response interceptor to handle 401s by
 * requesting a token refresh and replaying failed requests.
 */
export function attachRefreshTokenInterceptor(httpClient: AxiosInstance) {
  httpClient.interceptors.response.use(
    (response: AxiosResponse) => response,
    (error) => {
      const originalRequest = error.config as AxiosRequestConfig & {
        _retry?: boolean;
      };

      // If status is 401, and we haven't already retried this request:
      if (error.response?.status === 401 && !originalRequest._retry) {
        // If the request was the refresh endpoint itself, just reject:
        if (
          originalRequest.url &&
          originalRequest.url.includes('api/auth/refresh')
        ) {
          return Promise.reject(error);
        }

        if (isRefreshing) {
          // Queue up the request until the refresh finishes
          return new Promise((resolve, reject) => {
            failedQueue.push({ resolve, reject });
          })
            .then((token) => {
              // Once refreshed, retry the original
              originalRequest.headers!['Authorization'] = `Bearer ${token}`;
              return httpClient.request(originalRequest);
            })
            .catch((err) => Promise.reject(err));
        }

        originalRequest._retry = true;
        isRefreshing = true;

        return new Promise((resolve, reject) => {
          httpClient
            .post(
              'api/auth/refresh',
              {},
              { withCredentials: true }
            )
            .then((res) => {
              // Backend should have updated the cookie(s). If you need
              // a fresh Authorization: Bearer header, extract it from res here.
              const newToken = res.data.token; // or however your backend returns it
              processQueue(null, newToken);

              // Retry original request
              originalRequest.headers!['Authorization'] = `Bearer ${newToken}`;
              resolve(httpClient.request(originalRequest));
            })
            .catch((err) => {
              processQueue(err, null);
              reject(err);
            })
            .finally(() => {
              isRefreshing = false;
            });
        });
      }

      return Promise.reject(error);
    }
  );
}

package com.myproject.video.video_platform.service.security;


import com.myproject.video.video_platform.entity.user.User;
import io.jsonwebtoken.Claims;
import io.jsonwebtoken.JwtException;
import io.jsonwebtoken.Jwts;
import io.jsonwebtoken.security.Keys;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.filter.OncePerRequestFilter;

import javax.crypto.SecretKey;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.Date;
import java.util.List;

/**
 * Handles generating and validating JWT tokens.
 */
@Service
@RequiredArgsConstructor
@Slf4j
public class JwtProvider {

    @Value("${jwt.secret}")
    private String jwtSecret;

    @Value("${jwt.expiration}")
    private Long jwtExpirationInMillis;

    /**
     * Generate a JWT token for the given email (subject).
     */
    public String generateToken(User user) {
        Date now    = new Date();
        Date expiry = new Date(now.getTime() + jwtExpirationInMillis);

        return Jwts.builder()
                .subject(user.getUserId().toString())
                .claim("email", user.getEmail())
                .claim("roles", user.getRoles().stream()
                        .map(role -> role.getRoleName())
                        .toList())
                .issuedAt(now)
                .expiration(expiry)
                .signWith(getSigningKey())
                .compact();
    }

    /**
     * Validate the JWT token.
     */
    public boolean validateToken(String token) {
        try {
            // If parsing succeeds, the token is valid
            Jwts.parser()
                    .verifyWith(getSigningKey())
                    .build()
                    .parseSignedClaims(token);
            return true;
        } catch (JwtException e) {
            log.error(e.getMessage());
            return false;
        }
    }

    /**
     * Extract the email (subject) from the token.
     */
    public String getEmailFromJwt(String token) {
        Claims claims = Jwts.parser()
                .verifyWith(getSigningKey())
                .build()
                .parseSignedClaims(token)
                .getPayload();

        return claims.get("email", String.class);
    }

    /**
     * Provide a custom JWT authentication filter to be added to the security chain.
     */
    public OncePerRequestFilter jwtAuthenticationFilter() {
        return new JwtAuthenticationFilter(this);
    }

    /**
     * Convert the string secret into a SecretKey for signing.
     */
    private SecretKey getSigningKey() {
        return Keys.hmacShaKeyFor(jwtSecret.getBytes(StandardCharsets.UTF_8));
    }

    public Claims parseClaims(String token) {
        return Jwts.parser()
                .verifyWith(getSigningKey())
                .build()
                .parseSignedClaims(token)
                .getPayload();
    }

    public String getSubjectFromJwt(String token) {
        return parseClaims(token).getSubject();
    }

    @SuppressWarnings("unchecked")
    public List<String> getRolesFromJwt(String token) {
        Object roles = parseClaims(token).get("roles");
        if (roles instanceof List<?>) {
            return ((List<?>) roles).stream()
                    .filter(String.class::isInstance)
                    .map(String.class::cast)
                    .toList();
        }
        return Collections.emptyList();
    }
}

package com.myproject.video.video_platform.service.security;

import com.myproject.video.video_platform.entity.auth.RefreshToken;
import com.myproject.video.video_platform.exception.auth.AuthenticationException;
import com.myproject.video.video_platform.repository.auth.RefreshTokenRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.security.SecureRandom;
import java.time.Instant;
import java.time.temporal.ChronoUnit;
import java.util.Base64;
import java.util.Optional;

@Service
@RequiredArgsConstructor
public class RefreshTokenService {

    private final RefreshTokenRepository refreshTokenRepository;

    @Value("${app.refresh-expiry-days}")
    private int refreshExpiryDays;

    private static final SecureRandom secureRandom = new SecureRandom();

    public String createRefreshToken(String userEmail) {
        byte[] tokenBytes = new byte[64];
        secureRandom.nextBytes(tokenBytes);
        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(tokenBytes);

        RefreshToken refreshToken = new RefreshToken();
        refreshToken.setToken(token);
        refreshToken.setUserEmail(userEmail);
        refreshToken.setExpiryDate(Instant.now().plus(refreshExpiryDays, ChronoUnit.DAYS));
        refreshTokenRepository.save(refreshToken);

        return token;
    }

    public String validateRefreshToken(String token) {
        Optional<RefreshToken> opt = refreshTokenRepository.findByToken(token);
        if (opt.isEmpty()) {
            throw new AuthenticationException("Invalid refresh token");
        }
        RefreshToken rt = opt.get();

        if (rt.getExpiryDate().isBefore(Instant.now())) {
            // Remove expired token
            refreshTokenRepository.delete(rt);
            throw new AuthenticationException("Refresh token expired");
        }

        return rt.getUserEmail();
    }

    public void deleteRefreshToken(String token) {
        refreshTokenRepository.deleteByToken(token);
    }

    public void deleteRefreshTokensForUser(String userEmail) {
        refreshTokenRepository.deleteByUserEmail(userEmail);
    }
}

