import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import io.swagger.v3.oas.annotations.tags.Tag;
import jakarta.validation.Valid;

/**
 * Controller for handling user account actions.
 */
@RestController
@RequestMapping("/api/user")
@Tag(name = "Users", description = "Authenticated user profile management.")
public class UserController implements UserApiDoc {

    private final UserService userService;
    private final AuthService authService;

    public UserController(UserService userService, AuthService authService) {
        this.userService = userService;
        this.authService = authService;
    }

    /**
     * Endpoint to retrieve the authenticated user's basic info.
     * Requires a valid JWT, so Spring Security sets Authentication.
     */
    @GetMapping(value = "/userInfo", produces= MediaType.APPLICATION_JSON_VALUE)
    @Override
    public ResponseEntity<UserDto> getUserInfo(Authentication authentication) {
        UserDto userDto = userService.getUserInfo(authentication);
        return ResponseEntity.ok(userDto);
    }

    @PutMapping("/userInfo")
    @Override
    public ResponseEntity<UserDto> updateUserInfo(@Valid @RequestBody UpdateUserRequest req) {
        UserDto updatedUser = userService.updateUserInfo(req);
        return ResponseEntity.ok(updatedUser);
    }

    @PutMapping("/dev/role")
    public ResponseEntity<UserDto> changeDevRole(@Valid @RequestBody DevRoleChangeRequest req,
                                                 HttpServletResponse response) {
        UserDto updatedUser = userService.changeCurrentUserRoleForDev(req.getRole());
        authService.setAuthCookies(response, updatedUser.getEmail());
        return ResponseEntity.ok(updatedUser);
    }
}

package com.myproject.video.video_platform.service.user;

import com.myproject.video.video_platform.common.enums.user.UserRole;
import com.myproject.video.video_platform.dto.user.SocialMediaLinkResponse;
import com.myproject.video.video_platform.dto.user.SocialMediaLinkUpdateRequest;
import com.myproject.video.video_platform.dto.user.UpdateUserRequest;
import com.myproject.video.video_platform.dto.user.UserDto;
import com.myproject.video.video_platform.entity.user.Role;
import com.myproject.video.video_platform.entity.user.SocialMediaLink;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.product.ResourceNotFoundException;
import com.myproject.video.video_platform.exception.user.UserNotFoundException;
import com.myproject.video.video_platform.repository.auth.RoleRepository;
import com.myproject.video.video_platform.repository.auth.UserRepository;
import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;

@Service
public class UserService {

    private static final Log log = LogFactory.getLog(UserService.class);
    private final UserRepository userRepository;
    private final RoleRepository roleRepository;
    private final CurrentUserService currentUserService;
    private final boolean devRoleSwitchEnabled;

    public UserService(UserRepository userRepository,
                       RoleRepository roleRepository,
                       CurrentUserService currentUserService,
                       @Value("${app.dev-role-switch.enabled:false}") boolean devRoleSwitchEnabled) {
        this.userRepository = userRepository;
        this.roleRepository = roleRepository;
        this.currentUserService = currentUserService;
        this.devRoleSwitchEnabled = devRoleSwitchEnabled;
    }


    public UserDto getUserInfo(Authentication authentication) {
        // Extract the user’s principal (email) from the Authentication object.
        String userId = authentication.getPrincipal().toString();

        User user = userRepository.findByUserId(UUID.fromString(userId))
                .orElseThrow(() -> new UserNotFoundException("User not found: " + userId));

        return getUserDto(user);
    }

    private UserDto getUserDto(User user) {
        List<SocialMediaLinkResponse> linkResponses = user.getSocialLinks()
                .stream()
                .map(l -> new SocialMediaLinkResponse(
                        l.getId(), l.getPlatform(), l.getUrl(), l.getCreatedAt()))
                .collect(Collectors.toList());

        return UserDto.builder()
                .id(user.getUserId().toString())
                .firstName(user.getFirstName())
                .lastName(user.getLastName())
                .email(user.getEmail())
                .publicEmail(user.getPublicEmail())
                .roles(user.getRoles().stream().map(Role::getRoleName).toList())
                .title(user.getTitle())
                .bio(user.getBio())
                .taglineMission(user.getTaglineMission())
                .website(user.getWebsite())
                .city(user.getCity())
                .country(user.getCountry())
                .onboardingCompleted(user.isOnboardingcompleted())
                .socialLinks(linkResponses)
                .createdAt(user.getCreatedAt())
                .build();
    }

    public Optional<User> findByUserId(UUID uuid) {
        return userRepository.findById(uuid);
    }

    @Transactional
    public UserDto updateUserInfo(UpdateUserRequest req) {
        UUID currentUserId = currentUserService.getCurrentUserId();
        User user = userRepository.findById(currentUserId)
                .orElseThrow(() -> new ResourceNotFoundException("User not found: " + currentUserId));

        log.info("Updating user: " + currentUserId);

        if (req.getFirstName() != null)      user.setFirstName(requiredName(req.getFirstName(), "First name"));
        if (req.getLastName() != null)       user.setLastName(req.getLastName().trim());
        if (req.getPublicEmail() != null)    user.setPublicEmail(blankToNull(req.getPublicEmail()));
        if (req.getTitle() != null)          user.setTitle(req.getTitle());
        if (req.getBio() != null)            user.setBio(req.getBio());
        if (req.getTaglineMission() != null) user.setTaglineMission(req.getTaglineMission());
        if (req.getWebsite() != null)        user.setWebsite(req.getWebsite());
        if (req.getCity() != null)           user.setCity(req.getCity());
        if (req.getCountry() != null)        user.setCountry(req.getCountry());

        if (req.getSocialLinks() != null) {
            reconcileSocialLinks(user, req.getSocialLinks());
        }

        User saved = userRepository.save(user);

        log.info("Saved user: " + saved.getUserId());
        return getUserDto(saved);
    }

    private void reconcileSocialLinks(User user, List<SocialMediaLinkUpdateRequest> incoming) {
        List<SocialMediaLink> existing = new ArrayList<>(user.getSocialLinks());

        // Build set of incoming IDs to keep
        Set<UUID> keepIds = incoming.stream()
                .map(SocialMediaLinkUpdateRequest::getId)
                .filter(Objects::nonNull)
                .collect(Collectors.toSet());

        // Remove any existing link not in keepIds
        for (SocialMediaLink link : existing) {
            if (link.getId() != null && !keepIds.contains(link.getId())) {
                user.removeSocialLink(link);
            }
        }

        // Add or update incoming
        for (SocialMediaLinkUpdateRequest in : incoming) {
            if (in.getId() != null) {
                // update existing
                SocialMediaLink link = existing.stream()
                        .filter(l -> l.getId().equals(in.getId()))
                        .findFirst()
                        .orElseThrow(() -> new ResourceNotFoundException(
                                "SocialMediaLink ID not found: " + in.getId()));
                link.setPlatform(in.getPlatform());
                link.setUrl(in.getUrl());
            } else {
                // new link
                SocialMediaLink newLink = SocialMediaLink.builder()
                        .platform(in.getPlatform())
                        .url(in.getUrl())
                        .build();
                user.addSocialLink(newLink);
            }
        }
    }

    private static String requiredName(String value, String label) {
        String normalized = value.trim();
        if (normalized.isEmpty()) throw new IllegalArgumentException(label + " cannot be blank");
        return normalized;
    }

    private static String blankToNull(String value) {
        String normalized = value.trim();
        return normalized.isEmpty() ? null : normalized;
    }

    @Transactional
    public UserDto changeCurrentUserRoleForDev(UserRole role) {
        if (!devRoleSwitchEnabled) {
            throw new AccessDeniedException("Dev role switching is disabled");
        }

        UUID currentUserId = currentUserService.getCurrentUserId();
        User user = userRepository.findById(currentUserId)
                .orElseThrow(() -> new UserNotFoundException("User not found: " + currentUserId));

        Role nextRole = roleRepository.findByRoleName(role.name());
        if (nextRole == null) {
            throw new IllegalStateException("Role " + role.name() + " is missing from the database");
        }

        user.setRoles(new HashSet<>(Set.of(nextRole)));
        User saved = userRepository.save(user);

        return getUserDto(saved);
    }
}

