package com.myproject.video.video_platform.controller.product;

import com.myproject.video.video_platform.controller.docs.product.ProductsApiDoc;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.dto.products.AbstractProductResponseDto;
import com.myproject.video.video_platform.dto.products.ProductMinimised;
import com.myproject.video.video_platform.service.product.ProductService;
import com.myproject.video.video_platform.service.entitlement.ProductContentAccessService;
import io.swagger.v3.oas.annotations.tags.Tag;
import lombok.extern.slf4j.Slf4j;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Sort;
import org.springframework.data.web.PageableDefault;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.List;

@Slf4j
@RestController
@RequestMapping("/api/products")
@Tag(name = "Products", description = "Create and manage course, download, consultation, and Membership products.")
public class ProductsController implements ProductsApiDoc {

    private final ProductService productService;
    private final ProductContentAccessService contentAccessService;

    public ProductsController(
            ProductService productService,
            ProductContentAccessService contentAccessService
    ) {
        this.productService = productService;
        this.contentAccessService = contentAccessService;
    }

    @PostMapping
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    @Override
    public ResponseEntity<AbstractProductResponseDto> createProduct(@RequestBody AbstractProductRequestDto request) {
        log.info("Received create product request: {}", request);
        AbstractProductResponseDto response = productService.createProduct(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(response);
    }

    @GetMapping(params = "userId")
    @Override
    public ResponseEntity<List<AbstractProductResponseDto>> getProducts(@RequestParam(name = "userId") String userId) {
        List<AbstractProductResponseDto> response = contentAccessService.protectProductResponses(
                productService.getAllProductsForUser(userId)
        );
        return ResponseEntity.status(HttpStatus.OK).body(response);
    }

    @GetMapping(params = "ownerId")
    public ResponseEntity<List<ProductMinimised>> getProductsSummary(
            @RequestParam(name = "ownerId") String ownerId
    ) {
        List<ProductMinimised> response = productService.getProductSummariesForOwner(ownerId);
        return ResponseEntity.ok(response);
    }

    @GetMapping("/get-all-products-min")
    @Override
    public ResponseEntity<List<ProductMinimised>> getAllProductsMin(
            @RequestParam(name = "userId", required = false) String userId
    ) {
        List<ProductMinimised> response;
        if (userId != null) {
            response = productService.getAllProductsMinimisedForUser(userId);
        } else {
            response = productService.getAllProductsMinimised();
        }
        return ResponseEntity.ok(response);
    }

    @GetMapping(value = "/getProduct")
    @Override
    public ResponseEntity<AbstractProductResponseDto> getProductById(
            @RequestParam(name = "productId") String productId,
            @RequestParam(name = "type") String type) {

        AbstractProductResponseDto response = contentAccessService.protectProductResponse(
                productService.getProductByIdAndType(productId, type)
        );
        return ResponseEntity.status(HttpStatus.OK).body(response);
    }

    @GetMapping("/{productId}")
    public ResponseEntity<AbstractProductResponseDto> getProductById(
            @PathVariable("productId") String productId
    ) {
        AbstractProductResponseDto response = contentAccessService.protectProductResponse(
                productService.getProductById(productId)
        );
        return ResponseEntity.ok(response);
    }

    @PutMapping
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    @Override
    public ResponseEntity<AbstractProductResponseDto> updateProduct(@RequestBody AbstractProductRequestDto request) {
        log.info("Received update product request: {}", request.toString());
        AbstractProductResponseDto response = productService.updateProduct(request);
        return ResponseEntity.status(HttpStatus.ACCEPTED).body(response);
    }

    @PatchMapping("/{productId}")
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    public ResponseEntity<AbstractProductResponseDto> patchProduct(
            @PathVariable("productId") String productId,
            @RequestBody(required = false) com.fasterxml.jackson.databind.JsonNode request
    ) {
        AbstractProductResponseDto response = productService.patchProduct(productId, request);
        return ResponseEntity.ok(response);
    }

    @DeleteMapping()
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    @Override
    public ResponseEntity<String> deleteProduct(
            @RequestParam(name = "userId") String userId,
            @RequestParam(name = "productType") String productType,
            @RequestParam(name = "id") String id) {
        log.info("Received delete product request: {}", id);
        productService.deleteProduct(userId, id, productType);
        return ResponseEntity.status(HttpStatus.ACCEPTED).body("Product deleted succesfully: " + id);
    }

    @DeleteMapping("/{productId}")
    @PreAuthorize("hasAnyRole('CREATOR','ADMIN')")
    public ResponseEntity<Void> deleteProduct(@PathVariable("productId") String productId) {
        productService.deleteProductById(productId);
        return ResponseEntity.noContent().build();
    }

    /**
     * EXPLORE endpoint
     * GET /api/products/search?term=foo&page=0&size=20
     */
    @GetMapping("/search")
    @Override
    public Page<ProductMinimised> exploreSearch(
            @RequestParam String term,
            @PageableDefault(size = 20, sort = "createdAt", direction = Sort.Direction.DESC) Pageable pageable
    ) {
        return productService.searchAllProducts(term, pageable);
    }

    /**
     * LIBRARY / TEACHER endpoint
     * GET /api/users/{userId}/products?term=foo&page=0&size=20
     */
    @GetMapping("/search/{userId}/products")
    @Override
    public Page<ProductMinimised> librarySearch(
            @PathVariable String userId,
            @RequestParam String term,
            @PageableDefault(size = 20, sort = "createdAt", direction = Sort.Direction.DESC)
            Pageable pageable
    ) {
        return productService.searchUserProducts(userId, term, pageable);
    }

}

import { configureStore, createListenerMiddleware } from '@reduxjs/toolkit';
import authReducer from './auth-store/auth.slice';
import adminReducer from './admin-store/admin.slice';
import analyticsReducer from './analytics-store/analytics.slice';
import productsReducer from './product-store/product.slice';
import customersReducer from './customers-store/customers.slice';
import dashboardReducer from './dashboard-store/dashboard.slice';
import membershipReducer from './membership-store/membership.slice';
import notificationsReducer from './notifications/notifications.slice';
import productLandingPageReducer from './product-landing-page-store/product-landing-page.slice';
import salesReducer from './sales-store/sales.slice';
import storefrontReducer from './storefront-store/storefront.slice';
import shopCartReducer, {
  loadCartFromStorage,
  saveCartToStorage,
  ShopCartState,
} from './shop-cart/shop-cart.slice';
import wishlistReducer from './wishlist/wishlist.slice';
import { setupProductListeners } from './listeners/product-listeners';
import { reviewsSlice } from './reviews-store';

const listenerMiddleware = createListenerMiddleware();

setupProductListeners(listenerMiddleware);

const preloadedCart = loadCartFromStorage();

export const store = configureStore({
  reducer: {
    auth: authReducer,
    admin: adminReducer,
    analytics: analyticsReducer,
    products: productsReducer,
    customers: customersReducer,
    dashboard: dashboardReducer,
    membership: membershipReducer,
    notifications: notificationsReducer,
    productLandingPage: productLandingPageReducer,
    sales: salesReducer,
    storefront: storefrontReducer,
    shopCart: shopCartReducer,
    wishlist: wishlistReducer,
    reviews: reviewsSlice,
  },
  preloadedState: preloadedCart
    ? ({ shopCart: preloadedCart } as { shopCart: ShopCartState })
    : undefined,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware().prepend(listenerMiddleware.middleware),
});

let lastSaved: string | null = null;
store.subscribe(() => {
  const state = store.getState().shopCart as ShopCartState;
  const snapshot = JSON.stringify(state);
  if (snapshot !== lastSaved) {
    saveCartToStorage(state);
    lastSaved = snapshot;
  }
});

import { createAsyncThunk, createSlice, PayloadAction } from '@reduxjs/toolkit';

import {
  GoogleLoginRequest,
  LoginRequest,
  RegisterRequest,
  UpdateUserRequest,
  User,
  UserRole,
} from 'core/api/models';
import {
  registerUser,
  verifyEmailApi,
  signInUser,
  googleAPI,
  getUserProfileAPI,
  logoutAPI,
  updateUserDetailsAPI,
  changeDevUserRoleAPI,
} from 'core/api/services';
import { extractErrorMessage } from '@shared/utils';

interface AuthState {
  user: null | User;
  loading: boolean;
  error: string | null;
  isUserLoggedIn: boolean | null;
}

const initialState: AuthState = {
  user: null,
  loading: false,
  error: null,
  isUserLoggedIn: null,
};

// Registration thunk: returns a success message from the backend.
export const signupUser = createAsyncThunk<
  { response: string }, // Return type: success message
  RegisterRequest, // Argument type (user data)
  { rejectValue: string } // Error type
>('auth/signupUser', async (userData, { rejectWithValue }) => {
  try {
    const response = await registerUser(userData);
    return { response }; // API returns a success message
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

// Verify email thunk: calls the verify endpoint with the token.
export const verifyEmail = createAsyncThunk<
  string,
  string,
  { rejectValue: string } // Error type
>('auth/verifyEmail', async (token: string, { rejectWithValue }) => {
  try {
    const response = await verifyEmailApi(token);
    return response.data; // API returns a success message
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

// Sign in thunk: returns the user info along with a token.
export const signinUser = createAsyncThunk<
  string, // Return type: user login response
  LoginRequest, // Argument type (user data)
  { rejectValue: string } // Error type
>('auth/signinUser', async (userData, { dispatch, rejectWithValue }) => {
  try {
    const response = await signInUser(userData);
    if (response === 'Login successful') {
      dispatch(getUserProfile());
    }
    return response; // API returns user info with token
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const googleSignInUser = createAsyncThunk<
  string, // Return type: google login response
  GoogleLoginRequest, // Argument type (token)
  { rejectValue: string } // Error type
>('auth/googleSignInUser', async (idToken, { dispatch, rejectWithValue }) => {
  try {
    const response = await googleAPI(idToken);
    if (!response) {
      // If response is null or falsy, reject with an error message.
      return rejectWithValue('Signin failed');
    }
    dispatch(getUserProfile());
    return response; // API returns user info with token
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const getUserProfile = createAsyncThunk<
  User, // Return type: user login response
  void, // Argument type (user data)
  { rejectValue: string } // Error type
>('auth/getUserProfile', async (_, { rejectWithValue }) => {
  try {
    const response = await getUserProfileAPI();
    return response; // API returns user info with token
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const logoutUser = createAsyncThunk<
  void, // Return type
  void, // Argument type
  { rejectValue: string } // Error type
>('auth/logoutUser', async (_, { rejectWithValue }) => {
  try {
    // Assuming httpClient is your axios instance configured to include credentials.
    await logoutAPI();
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const updateUserDetails = createAsyncThunk<
  User, // Return type: user login response
  UpdateUserRequest, // Argument type (user data)
  { rejectValue: string } // Error type
>('auth/updateUserDetails', async (userData, { rejectWithValue }) => {
  try {
    const response = await updateUserDetailsAPI(userData);
    return response; // API returns user info with token
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const changeDevUserRole = createAsyncThunk<
  User,
  UserRole,
  { rejectValue: string }
>('auth/changeDevUserRole', async (role, { rejectWithValue }) => {
  try {
    return await changeDevUserRoleAPI(role);
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    // This action can be used to rehydrate the token on app load
    // setToken: (state, action: PayloadAction<string>) => {
    //   state.token = action.payload;
    // },
    setUserProfile: (state, action: PayloadAction<User>) => {
      state.user = action.payload;
    },
    logout: (state) => {
      state.user = null;
      state.isUserLoggedIn = null;
    },
    resetOnboarding: (state) => {
      // Reset any onboarding state if needed
      // This can be expanded based on your onboarding logic
      if (state.user) {
        state.user.onboardingCompleted = false;
      }

      state.isUserLoggedIn = true;
    },
  },
  extraReducers: (builder) => {
    builder
      // Registration cases:
      .addCase(signupUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(signupUser.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(signupUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Signup failed';
      })
      // Verification cases:
      .addCase(verifyEmail.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(verifyEmail.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(verifyEmail.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Verification failed';
      })
      // Sign in cases:
      .addCase(signinUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(signinUser.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(signinUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Signin failed';
      })
      // Google Sign In
      .addCase(googleSignInUser.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(googleSignInUser.fulfilled, (state) => {
        state.loading = false;
      })
      .addCase(googleSignInUser.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Google Signin failed';
      })
      // Get User Profile
      .addCase(getUserProfile.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(
        getUserProfile.fulfilled,
        (state, action: PayloadAction<User>) => {
          state.loading = false;
          state.user = action.payload;
          state.isUserLoggedIn = true;
        },
      )
      .addCase(getUserProfile.rejected, (state) => {
        state.loading = false;
        state.isUserLoggedIn = false;
        state.error = 'Get User Profile failed';
      })
      .addCase(logoutUser.fulfilled, (state) => {
        state.user = null;
        state.isUserLoggedIn = null;
      })
      .addCase(logoutUser.rejected, (state, action) => {
        // Optionally handle logout errors here.
        state.error = action.payload || 'Logout failed';
      })

      .addCase(updateUserDetails.pending, (state) => {
        state.loading = true;
      })
      .addCase(
        updateUserDetails.fulfilled,
        (state, action: PayloadAction<User>) => {
          state.loading = false;
          state.user = action.payload;
        },
      )
      .addCase(updateUserDetails.rejected, (state) => {
        state.loading = false;
        state.error = 'Update user details failed';
      })
      .addCase(changeDevUserRole.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(
        changeDevUserRole.fulfilled,
        (state, action: PayloadAction<User>) => {
          state.loading = false;
          state.user = action.payload;
          state.isUserLoggedIn = true;
        },
      )
      .addCase(changeDevUserRole.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload || 'Change dev user role failed';
      });
  },
});

export const { logout, setUserProfile, resetOnboarding } = authSlice.actions;
export default authSlice.reducer;

