export const selectCreatorCustomers = (state: RootState) =>
  state.customers.customersPage?.content ?? EMPTY_CUSTOMERS;
export const selectCreatorCustomerProductOptions = (state: RootState) =>
  state.customers.customersPage?.productOptions ?? EMPTY_CUSTOMER_PRODUCT_OPTIONS;
export const selectCreatorCustomersListLoading = (state: RootState) =>
  state.customers.listLoading;
export const selectCreatorCustomersListError = (state: RootState) =>
  state.customers.listError;
export const selectCurrentCreatorCustomer = (state: RootState) =>
  state.customers.currentCustomer;
export const selectCreatorCustomerDetailLoading = (state: RootState) =>
  state.customers.detailLoading;
export const selectCreatorCustomerDetailError = (state: RootState) =>
  state.customers.detailError;

export default customersSlice.reducer;

import { createAsyncThunk, createSlice, PayloadAction } from '@reduxjs/toolkit';

import {
  CreatorOrdersPage,
  CreatorOrdersQuery,
  CreatorSalesSummary,
  CreatorSalesSummaryQuery,
  RootState,
  SalesOrderDetail,
} from 'core/api/models';
import {
  getCreatorOrderDetailAPI,
  getCreatorOrdersPageAPI,
  getCreatorSalesSummaryAPI,
} from 'core/api/services';
import { extractErrorMessage } from '@shared/utils';

interface SalesState {
  summary: CreatorSalesSummary | null;
  summaryLoading: boolean;
  summaryError: string | null;
  ordersPage: CreatorOrdersPage | null;
  ordersLoading: boolean;
  ordersError: string | null;
  currentOrder: SalesOrderDetail | null;
  detailLoading: boolean;
  detailError: string | null;
}

const initialState: SalesState = {
  summary: null,
  summaryLoading: false,
  summaryError: null,
  ordersPage: null,
  ordersLoading: false,
  ordersError: null,
  currentOrder: null,
  detailLoading: false,
  detailError: null,
};

const EMPTY_ORDERS: CreatorOrdersPage['content'] = [];
const EMPTY_ORDER_PRODUCT_OPTIONS: CreatorOrdersPage['productOptions'] = [];

export const fetchCreatorSalesSummary = createAsyncThunk<
  CreatorSalesSummary,
  CreatorSalesSummaryQuery | undefined,
  { rejectValue: string }
>('sales/fetchCreatorSalesSummary', async (query, { rejectWithValue }) => {
  try {
    return await getCreatorSalesSummaryAPI(query);
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const fetchCreatorOrdersPage = createAsyncThunk<
  CreatorOrdersPage,
  CreatorOrdersQuery | undefined,
  { rejectValue: string }
>('sales/fetchCreatorOrdersPage', async (query, { rejectWithValue }) => {
  try {
    return await getCreatorOrdersPageAPI(query);
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

export const fetchCreatorOrderDetail = createAsyncThunk<
  SalesOrderDetail,
  string,
  { rejectValue: string }
>('sales/fetchCreatorOrderDetail', async (orderId, { rejectWithValue }) => {
  try {
    return await getCreatorOrderDetailAPI(orderId);
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

const salesSlice = createSlice({
  name: 'sales',
  initialState,
  reducers: {
    clearCurrentOrder(state) {
      state.currentOrder = null;
      state.detailError = null;
    },
  },
  extraReducers: (builder) => {
    builder
      .addCase(fetchCreatorSalesSummary.pending, (state) => {
        state.summaryLoading = true;
        state.summaryError = null;
      })
      .addCase(
        fetchCreatorSalesSummary.fulfilled,
        (state, action: PayloadAction<CreatorSalesSummary>) => {
          state.summaryLoading = false;
          state.summary = action.payload;
        },
      )
      .addCase(fetchCreatorSalesSummary.rejected, (state, action) => {
        state.summaryLoading = false;
        state.summaryError = action.payload ?? 'Failed to load sales summary';
        state.summary = null;
      })
      .addCase(fetchCreatorOrdersPage.pending, (state) => {
        state.ordersLoading = true;
        state.ordersError = null;
      })
      .addCase(
        fetchCreatorOrdersPage.fulfilled,
        (state, action: PayloadAction<CreatorOrdersPage>) => {
          state.ordersLoading = false;
          state.ordersPage = action.payload;
        },
      )
      .addCase(fetchCreatorOrdersPage.rejected, (state, action) => {
        state.ordersLoading = false;
        state.ordersError = action.payload ?? 'Failed to load orders';
        state.ordersPage = null;
      })
      .addCase(fetchCreatorOrderDetail.pending, (state) => {
        state.detailLoading = true;
        state.detailError = null;
      })
      .addCase(
        fetchCreatorOrderDetail.fulfilled,
        (state, action: PayloadAction<SalesOrderDetail>) => {
          state.detailLoading = false;
          state.currentOrder = action.payload;
        },
      )
      .addCase(fetchCreatorOrderDetail.rejected, (state, action) => {
        state.detailLoading = false;
        state.detailError = action.payload ?? 'Failed to load order';
        state.currentOrder = null;
      });
  },
});

export const { clearCurrentOrder } = salesSlice.actions;

export const selectCreatorSalesSummary = (state: RootState) =>
  state.sales.summary;
export const selectCreatorSalesSummaryLoading = (state: RootState) =>
  state.sales.summaryLoading;
export const selectCreatorSalesSummaryError = (state: RootState) =>
  state.sales.summaryError;
export const selectCreatorOrdersPage = (state: RootState) =>
  state.sales.ordersPage;
export const selectCreatorOrders = (state: RootState) =>
  state.sales.ordersPage?.content ?? EMPTY_ORDERS;
export const selectCreatorOrderProductOptions = (state: RootState) =>
  state.sales.ordersPage?.productOptions ?? EMPTY_ORDER_PRODUCT_OPTIONS;
export const selectCreatorOrdersLoading = (state: RootState) =>
  state.sales.ordersLoading;
export const selectCreatorOrdersError = (state: RootState) =>
  state.sales.ordersError;
export const selectCurrentCreatorOrder = (state: RootState) =>
  state.sales.currentOrder;
export const selectCreatorOrderDetailLoading = (state: RootState) =>
  state.sales.detailLoading;
export const selectCreatorOrderDetailError = (state: RootState) =>
  state.sales.detailError;

export default salesSlice.reducer;

import { createAsyncThunk, createSlice, PayloadAction } from '@reduxjs/toolkit';

import {
  CreatorAnalyticsOverview,
  CreatorAnalyticsOverviewQuery,
  RootState,
} from 'core/api/models';
import { getCreatorAnalyticsOverviewAPI } from 'core/api/services';
import { extractErrorMessage } from '@shared/utils';

interface AnalyticsState {
  overview: CreatorAnalyticsOverview | null;
  loading: boolean;
  error: string | null;
}

const initialState: AnalyticsState = {
  overview: null,
  loading: false,
  error: null,
};

export const fetchCreatorAnalyticsOverview = createAsyncThunk<
  CreatorAnalyticsOverview,
  CreatorAnalyticsOverviewQuery | undefined,
  { rejectValue: string }
>('analytics/fetchCreatorAnalyticsOverview', async (query, { rejectWithValue }) => {
  try {
    return await getCreatorAnalyticsOverviewAPI(query);
  } catch (error: unknown) {
    return rejectWithValue(extractErrorMessage(error));
  }
});

const analyticsSlice = createSlice({
  name: 'analytics',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      .addCase(fetchCreatorAnalyticsOverview.pending, (state) => {
        state.loading = true;
        state.error = null;
      })
      .addCase(
        fetchCreatorAnalyticsOverview.fulfilled,
        (state, action: PayloadAction<CreatorAnalyticsOverview>) => {
          state.loading = false;
          state.overview = action.payload;
        },
      )
      .addCase(fetchCreatorAnalyticsOverview.rejected, (state, action) => {
        state.loading = false;
        state.error = action.payload ?? 'Failed to load analytics';
        state.overview = null;
      });
  },
});

export const selectAnalyticsOverview = (state: RootState) =>
  state.analytics.overview;
export const selectAnalyticsLoading = (state: RootState) =>
  state.analytics.loading;
export const selectAnalyticsError = (state: RootState) =>
  state.analytics.error;

export default analyticsSlice.reducer;

import React from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Link, useNavigate } from 'react-router-dom';
import clsx from 'clsx';
import { HiChevronUpDown } from 'react-icons/hi2';

import {
  AppDispatch,
  getPrimaryRole,
  rolePrecedence,
  UserRole,
} from 'core/api/models';
import { Dropdown, Icon, UserAvatar } from '@shared/ui';
import {
  selectAuthUser,
  changeDevUserRole,
  logout,
  logoutUser,
} from 'core/store/auth-store';
import { getProfileNameInitials } from '@shared/utils';

import './user-dropdown.styles.scss';

interface UserDropdownProps {
  variant?: 'default' | 'sidebar';
  collapsed?: boolean;
}

const UserDropdown: React.FC<UserDropdownProps> = ({
  variant = 'default',
  collapsed = false,
}) => {
  const user = useSelector(selectAuthUser);
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const primaryRole = getPrimaryRole(user?.roles);
  const roleOptions = rolePrecedence.filter((role) => role !== primaryRole);
  const displayName = `${user?.firstName ?? ''} ${user?.lastName ?? ''}`.trim();
  const isSidebarTrigger = variant === 'sidebar';

  const handleRoleChange = (role: UserRole) => {
    dispatch(changeDevUserRole(role));
  };

  // Log the user out
  const handleLogout = () => {
    dispatch(logout());

    dispatch(logoutUser())
      .unwrap()
      .then(() => {
        // Redirect to login or homepage
        navigate('/');
      })
      .catch((error) => {
        console.error('Logout error:', error);
      });
  };

  if (!user) {
    return null;
  }

  return (
    <div
      className={clsx('user-dropdown', {
        'user-dropdown--sidebar': variant === 'sidebar',
        'user-dropdown--collapsed': collapsed,
      })}
    >
      <Dropdown
        customClassName="account-dropdown-panel"
        trigger={({ toggle }) => (
          <button
            type="button"
            onClick={toggle}
            className="user-profile-button inline"
            aria-label={
              isSidebarTrigger
                ? `Open account menu for ${displayName}`
                : getProfileNameInitials(user.firstName, user.lastName)
            }
            title={
              isSidebarTrigger && collapsed
                ? `Open account menu for ${displayName}`
                : undefined
            }
          >
            {isSidebarTrigger ? (
              <>
                <UserAvatar imageUrl={user.imageUrl ?? ''} alt={displayName} />
                {!collapsed && (
                  <>
                    <span className="user-profile-button__identity">
                      <span className="user-name">{displayName}</span>
                      <span className="user-role">{primaryRole}</span>
                    </span>
                    <Icon
                      icon={HiChevronUpDown}
                      color="currentColor"
                      size={16}
                      className="user-profile-button__chevron"
                    />
                  </>
                )}
              </>
            ) : (
              <>
                <span className="user-name">{displayName}</span>
                <UserAvatar imageUrl={user.imageUrl ?? ''} alt={displayName} />
              </>
            )}
          </button>
        )}
        menu={() => (
          <>
            <div className="dropdown-item">
              <h3>
                {user.firstName} {user.lastName}
              </h3>
            </div>
            <div className="dropdown-item">
              <span>{user.email}</span>
            </div>
            <div className="dropdown-item">
              <span>Role: {primaryRole}</span>
            </div>
            <div className="dropdown-item dev-role-switch">
              <span>Change Role (for dev):</span>
              <div className="role-selector">
                {roleOptions.map((role) => (
                  <button
                    key={role}
                    type="button"
                    className="role-button"
                    onClick={() => handleRoleChange(role)}
                  >
                    {role}
                  </button>
                ))}
              </div>
            </div>
            <div className="dropdown-item dev-items">
              <Link to="/dev-dashboard">Dev Dashboard</Link>
              <Link
                target="_blank"
                to="https://luxury-klepon-a62307.netlify.app/"
              >
                Docusaurus
              </Link>
            </div>
            <hr />
            <div className="dropdown-item logout-btn" onClick={handleLogout}>
              Logout
            </div>
          </>
        )}
      />
    </div>
  );
};

export default UserDropdown;

import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';

import { selectAuthUser } from 'core/store/auth-store';
import {
  fetchCreatorDashboardSummary,
  selectCreatorDashboardError,
  selectCreatorDashboardLoading,
  selectCreatorDashboardSummary,
} from 'core/store/dashboard-store';
import {
  AppDispatch,
  CreatorDashboardSummary,
  hasRole,
  UserRole,
} from 'core/api/models';
import {
  ActivityList,
  AttentionList,
  MetricCard,
  ProductPerformanceList,
} from './components';

import './creator-dashboard.styles.scss';

const getGreeting = (firstName?: string) => {
  const hour = new Date().getHours();
  const dayPart =
    hour < 12 ? 'morning' : hour < 18 ? 'afternoon' : 'evening';

  return `Good ${dayPart}, ${firstName || 'creator'}.`;
};

const unavailableDashboard: CreatorDashboardSummary = {
  metrics: [
    {
      id: 'revenue',
      label: 'Revenue',
      value: '',
      state: 'unavailable',
    },
    {
      id: 'sales',
      label: 'Sales',
      value: '',
      state: 'unavailable',
    },
    {
      id: 'customers',
      label: 'Customers',
      value: '',
      state: 'unavailable',
    },
    {
      id: 'active-memberships',
      label: 'Active memberships',
      value: '',
      state: 'unavailable',
    },
  ],
  activities: [],
  topProducts: [],
  attentionItems: [],
};

const CreatorDashboard: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const user = useSelector(selectAuthUser);
  const isCreator = hasRole(user?.roles, UserRole.CREATOR);
  const dashboard = useSelector(selectCreatorDashboardSummary);
  const isLoading = useSelector(selectCreatorDashboardLoading);
  const error = useSelector(selectCreatorDashboardError);

  useEffect(() => {
    if (isCreator) {
      dispatch(fetchCreatorDashboardSummary());
    }
  }, [dispatch, isCreator]);

  if (!isCreator) {
    return (
      <section className="creator-dashboard creator-dashboard__empty">
        <h1>Dashboard</h1>
        <p>Creator business tools are available when your active role is Creator.</p>
      </section>
    );
  }

  const dashboardSummary = error || !dashboard ? unavailableDashboard : dashboard;

  return (
    <div className="creator-dashboard">
      <header className="creator-dashboard__intro">
        <div>
          <h1>Dashboard</h1>
          <p>{getGreeting(user?.firstName)}</p>
        </div>
      </header>

      <section className="creator-dashboard__metrics" aria-label="Business metrics">
        {dashboardSummary.metrics.map((metric) => (
          <MetricCard
            key={metric.id}
            metric={isLoading && !dashboard ? { ...metric, state: 'loading' } : metric}
          />
        ))}
      </section>

      <div className="creator-dashboard__grid">
        <section className="dashboard-panel dashboard-panel__activity">
          <div className="dashboard-panel__header">
            <h2>Recent activity</h2>
          </div>
          {dashboardSummary.activities.length > 0 ? (
            <ActivityList items={dashboardSummary.activities} />
          ) : (
            <p className="dashboard-panel__empty">
              Activity will appear here once business events are available.
            </p>
          )}
        </section>

        <section className="dashboard-panel dashboard-panel__products">
          <div className="dashboard-panel__header">
            <h2>Top products</h2>
            <span>Revenue</span>
          </div>
          {dashboardSummary.topProducts.length > 0 ? (
            <ProductPerformanceList items={dashboardSummary.topProducts} />
          ) : (
            <p className="dashboard-panel__empty">
              Product performance is unavailable until revenue data exists.
            </p>
          )}
        </section>

        <section className="dashboard-panel dashboard-panel__attention">
          <div className="dashboard-panel__header">
            <h2>Needs attention</h2>
          </div>
          {dashboardSummary.attentionItems.length > 0 ? (
            <AttentionList items={dashboardSummary.attentionItems} />
          ) : (
            <p className="dashboard-panel__empty">
              No deterministic attention states are available yet.
            </p>
          )}
        </section>
      </div>
    </div>
  );
};

export default CreatorDashboard;

import React, { useEffect, useMemo, useState } from 'react';
import { FaSearch } from 'react-icons/fa';
import { BiSort } from 'react-icons/bi';
import { MdGroups, MdOutlineInventory2, MdOutlinePayments } from 'react-icons/md';
import { useDispatch, useSelector } from 'react-redux';

import { Input, Select, SelectOption, Button } from '@shared/ui';
import { AppDispatch } from 'core/api/models';
import {
  fetchCreatorCustomersPage,
  selectCreatorCustomerProductOptions,
  selectCreatorCustomers,
  selectCreatorCustomersListError,
  selectCreatorCustomersListLoading,
  selectCreatorCustomersPage,
} from 'core/store/customers-store';

import CustomerManagementRow from './customer-management-row.component';
import {
  CustomerFilterForm,
  defaultCustomerFilterForm,
} from './creator-customers.utils';

import './customers.styles.scss';

const PAGE_SIZE = 6;

const statusOptions: SelectOption[] = [
  { label: 'All statuses', value: 'all' },
  { label: 'Active member', value: 'active-member' },
  { label: 'Past due', value: 'past-due' },
  { label: 'Buyer', value: 'buyer' },
  { label: 'Waitlist', value: 'waitlist' },
];

const membershipOptions: SelectOption[] = [
  { label: 'All membership', value: 'all' },
  { label: 'Active', value: 'active' },
  { label: 'Past due', value: 'past_due' },
  { label: 'Cancelled', value: 'cancelled' },
  { label: 'No membership', value: 'none' },
];

const sortOptions: SelectOption[] = [
  { label: 'Recent activity', value: 'last-activity-desc' },
  { label: 'Highest spend', value: 'spend-desc' },
  { label: 'Lowest spend', value: 'spend-asc' },
  { label: 'Name A-Z', value: 'name-asc' },
  { label: 'Name Z-A', value: 'name-desc' },
];

const CustomersList: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const customersPage = useSelector(selectCreatorCustomersPage);
  const customers = useSelector(selectCreatorCustomers);
  const productFilterOptions = useSelector(selectCreatorCustomerProductOptions);
  const loading = useSelector(selectCreatorCustomersListLoading);
  const error = useSelector(selectCreatorCustomersListError);
  const [filterForm, setFilterForm] = useState<CustomerFilterForm>(
    defaultCustomerFilterForm,
  );
  const [page, setPage] = useState(0);

  useEffect(() => {
    dispatch(
      fetchCreatorCustomersPage({
        page,
        pageSize: PAGE_SIZE,
        search: filterForm.search,
        status: filterForm.status,
        product: filterForm.product,
        membership: filterForm.membership,
        sort: filterForm.sort,
      }),
    );
  }, [dispatch, filterForm, page]);

  const productOptions = useMemo(
    () => [
      { label: 'All products', value: 'all' },
      ...productFilterOptions.map((product) => ({
        label: product.name,
        value: product.id,
      })),
    ],
    [productFilterOptions],
  );
  const hasSearch = filterForm.search.trim().length > 0;
  const hasFilters =
    filterForm.status !== 'all' ||
    filterForm.product !== 'all' ||
    filterForm.membership !== 'all';
  const hasActiveRefinement = hasSearch || hasFilters;
  const totalPages = customersPage?.totalPages ?? 1;
  const currentPage = customersPage?.number ?? page;
  const totalElements = customersPage?.totalElements ?? 0;
  const hasCustomers = totalElements > 0;
  const hasControls =
    productFilterOptions.length > 0 || customers.length > 0 || hasActiveRefinement;
  const clearRefinementLabel = hasSearch && !hasFilters ? 'Clear search' : 'Clear filters';
  const resultCountLabel = `${totalElements} ${
    totalElements === 1 ? 'customer' : 'customers'
  }`;

  const handleControlChange = (
    event: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) => {
    const { name, value } = event.target;
    setPage(0);
    setFilterForm((current) => ({ ...current, [name]: value }));
  };

  const clearSearch = () => {
    setPage(0);
    setFilterForm((current) => ({ ...current, search: '' }));
  };

  const clearFilters = () => {
    setPage(0);
    setFilterForm(defaultCustomerFilterForm);
  };

  const clearActiveRefinement = () => {
    if (hasSearch && !hasFilters) {
      clearSearch();
      return;
    }

    clearFilters();
  };

  const renderState = (): React.ReactNode => {
    if (loading && !customersPage) {
      return (
        <div className="customers-state" role="status">
          <h2>Loading customers</h2>
        </div>
      );
    }

    if (error) {
      return (
        <div className="customers-state" role="status">
          <h2>Customer data is not available yet</h2>
          <p>
            Customers will appear here once customer, purchase, membership, and
            waitlist APIs are connected.
          </p>
        </div>
      );
    }

    if (!hasCustomers && !hasActiveRefinement) {
      return (
        <div className="customers-state">
          <h2>No customers yet</h2>
          <p>
            Customers will appear here after purchases, memberships, or waitlist
            sign-ups.
          </p>
        </div>
      );
    }

    if (totalElements === 0 && hasSearch) {
      return (
        <div className="customers-state">
          <h2>{`No customers match "${filterForm.search.trim()}".`}</h2>
          <p>Try another name or email.</p>
          <Button type="button" variant="secondary" onClick={clearSearch}>
            Clear search
          </Button>
        </div>
      );
    }

    if (totalElements === 0 && hasFilters) {
      return (
        <div className="customers-state">
          <h2>No customers match these filters.</h2>
          <p>Try a different status, product, or membership state.</p>
          <Button type="button" variant="secondary" onClick={clearFilters}>
            Clear filters
          </Button>
        </div>
      );
    }

    return null;
  };

  return (
    <div className="customers-page">
      <header className="customers-header">
        <div>
          <h1>Customers</h1>
          <p>Understand your customers and their relationships.</p>
        </div>
      </header>

      {hasControls && (
        <section className="customers-toolbar" aria-label="Customer controls">
          <Input
            value={filterForm.search}
            prefixIcon={FaSearch}
            onChange={handleControlChange}
            placeholder="Search by name or email..."
            name="search"
            aria-label="Search by name or email"
            className="customers-toolbar__search"
          />
          <div className="customers-toolbar__filters">
            <Select
              name="status"
              value={filterForm.status}
              options={statusOptions}
              onChange={handleControlChange}
              customClassName="customers-toolbar__select"
              prefixIcon={MdGroups}
              aria-label="Filter by relationship status"
            />
            <Select
              name="product"
              value={filterForm.product}
              options={productOptions}
              onChange={handleControlChange}
              customClassName="customers-toolbar__select"
              prefixIcon={MdOutlineInventory2}
              aria-label="Filter by product"
            />
            <Select
              name="membership"
              value={filterForm.membership}
              options={membershipOptions}
              onChange={handleControlChange}
              customClassName="customers-toolbar__select"
              prefixIcon={MdOutlinePayments}
              aria-label="Filter by membership state"
            />
            <Select
              name="sort"
              value={filterForm.sort}
              options={sortOptions}
              onChange={handleControlChange}
              customClassName="customers-toolbar__select customers-toolbar__sort"
              prefixIcon={BiSort}
              aria-label="Sort customers"
            />
          </div>
        </section>
      )}

      {hasControls && (
        <div className="customers-collection-meta">
          <span>{resultCountLabel}</span>
          {hasActiveRefinement && (
            <Button
              type="button"
              variant="tertiary"
              size="sm"
              onClick={clearActiveRefinement}
            >
              {clearRefinementLabel}
            </Button>
          )}
        </div>
      )}

      {renderState() || (
        <>
          <section className="customers-management-list" aria-label="Customers">
            <div className="customers-management-list__header" aria-hidden="true">
              <span>Customer</span>
              <span>Status</span>
              <span>Products</span>
              <span>Total spend</span>
              <span>Last activity</span>
            </div>
            <div className="customers-management-list__rows">
              {customers.map((customer) => (
                <CustomerManagementRow customer={customer} key={customer.id} />
              ))}
            </div>
          </section>

          {totalPages > 1 && (
            <nav className="customers-pagination" aria-label="Customer pages">
              <Button
                type="button"
                variant="secondary"
                size="sm"
                disabled={currentPage === 0}
                onClick={() => setPage((value) => Math.max(0, value - 1))}
              >
                Previous
              </Button>
              <span>
                Page {currentPage + 1} of {totalPages}
              </span>
              <Button
                type="button"
                variant="secondary"
                size="sm"
                disabled={currentPage >= totalPages - 1}
                onClick={() =>
                  setPage((value) => Math.min(totalPages - 1, value + 1))
                }
              >
                Next
              </Button>
            </nav>
          )}
        </>
      )}
    </div>
  );
};

export default CustomersList;

import React, { useEffect, useMemo, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { BiSort } from 'react-icons/bi';
import { FaSearch } from 'react-icons/fa';
import { MdOutlineCalendarToday, MdOutlineFilterList } from 'react-icons/md';
import { SiStatuspal } from 'react-icons/si';
import { useDispatch, useSelector } from 'react-redux';

import { Button, Drawer, Input, Select, SelectOption, StatusBadge } from '@shared/ui';
import {
  AppDispatch,
  CreatorSalesOrderItem,
  SalesOrderDetail,
  SalesOrderListItem,
} from 'core/api/models';
import {
  clearCurrentOrder,
  fetchCreatorOrderDetail,
  fetchCreatorOrdersPage,
  fetchCreatorSalesSummary,
  selectCreatorOrderProductOptions,
  selectCreatorOrders,
  selectCreatorOrdersError,
  selectCreatorOrdersLoading,
  selectCreatorOrdersPage,
  selectCreatorSalesSummary,
  selectCreatorSalesSummaryError,
  selectCurrentCreatorOrder,
} from 'core/store/sales-store';

import {
  defaultSalesFilterForm,
  formatSalesDateTime,
  formatSalesMoney,
  formatSalesShortDate,
  getSalesOrderItems,
  orderStatusLabel,
  orderStatusTone,
  orderTypeLabel,
  salesPeriodOptions,
  salesSortOptions,
  salesStatusOptions,
  subscriptionStateLabel,
} from './creator-sales.utils';
import { appRoutes } from 'domains/app/routes/routes';

import './sales-page.styles.scss';

const PAGE_SIZE = 6;

const trendSymbol: Record<string, string> = {
  up: '↑',
  down: '↓',
  flat: '—',
};

const accessStateTone = {
  granted: 'success',
  revoked: 'warning',
  none: 'neutral',
} as const;

const SalesPage: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const [searchParams, setSearchParams] = useSearchParams();
  const selectedOrderId = searchParams.get('order');
  const summary = useSelector(selectCreatorSalesSummary);
  const summaryError = useSelector(selectCreatorSalesSummaryError);
  const ordersPage = useSelector(selectCreatorOrdersPage);
  const orders = useSelector(selectCreatorOrders);
  const productFilterOptions = useSelector(selectCreatorOrderProductOptions);
  const ordersLoading = useSelector(selectCreatorOrdersLoading);
  const ordersError = useSelector(selectCreatorOrdersError);
  const currentOrder = useSelector(selectCurrentCreatorOrder);
  const [filterForm, setFilterForm] = useState(defaultSalesFilterForm);
  const [page, setPage] = useState(0);
  const [filtersOpen, setFiltersOpen] = useState(false);

  useEffect(() => {
    dispatch(fetchCreatorSalesSummary({ period: filterForm.period }));
  }, [dispatch, filterForm.period]);

  useEffect(() => {
    dispatch(
      fetchCreatorOrdersPage({
        page,
        pageSize: PAGE_SIZE,
        search: filterForm.search,
        status: filterForm.status,
        product: filterForm.product,
        period: filterForm.period,
        sort: filterForm.sort,
      }),
    );
  }, [dispatch, filterForm, page]);

  useEffect(() => {
    if (selectedOrderId) {
      dispatch(fetchCreatorOrderDetail(selectedOrderId));
      return;
    }

    dispatch(clearCurrentOrder());
  }, [dispatch, selectedOrderId]);

  const productOptions = useMemo<SelectOption[]>(
    () => [
      { label: 'All products', value: 'all' },
      ...productFilterOptions
        .filter((product) => Boolean(product.id))
        .map((product) => ({
          label: product.name,
          value: product.id ?? '',
        })),
    ],
    [productFilterOptions],
  );
  const selectedOrder =
    currentOrder?.id === selectedOrderId ? currentOrder : undefined;

  const hasSearch = filterForm.search.trim().length > 0;
  const hasFilters = filterForm.status !== 'all' || filterForm.product !== 'all';
  const activeFilterCount =
    Number(filterForm.status !== 'all') + Number(filterForm.product !== 'all');
  const hasActiveRefinement = hasSearch || hasFilters;
  const totalPages = ordersPage?.totalPages ?? 1;
  const currentPage = ordersPage?.number ?? page;
  const totalElements = ordersPage?.totalElements ?? 0;
  const hasOrders = totalElements > 0;
  const hasControls =
    productFilterOptions.length > 0 || orders.length > 0 || hasActiveRefinement;
  const resultCountLabel = `${totalElements} ${
    totalElements === 1 ? 'order' : 'orders'
  }`;

  const handleControlChange = (
    event: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>,
  ) => {
    const { name, value } = event.target;
    setPage(0);
    setFilterForm((current) => ({ ...current, [name]: value }));
  };

  const clearSearch = () => {
    setPage(0);
    setFilterForm((current) => ({ ...current, search: '' }));
  };

  const clearFilters = () => {
    setPage(0);
    setFilterForm(defaultSalesFilterForm);
  };

  const openOrder = (orderId: string) => {
    const nextParams = new URLSearchParams(searchParams);
    nextParams.set('order', orderId);
    setSearchParams(nextParams);
  };

  const closeOrder = () => {
    const nextParams = new URLSearchParams(searchParams);
    nextParams.delete('order');
    setSearchParams(nextParams);
  };

  const renderFilters = (compact = false) => (
    <div className={compact ? 'sales-filter-stack' : 'sales-toolbar__filters'}>
      <Select
        name="period"
        value={filterForm.period}
        options={salesPeriodOptions}
        onChange={handleControlChange}
        customClassName="sales-toolbar__select"
        prefixIcon={MdOutlineCalendarToday}
        aria-label="Select sales date range"
      />
      <Select
        name="status"
        value={filterForm.status}
        options={salesStatusOptions}
        onChange={handleControlChange}
        customClassName="sales-toolbar__select"
        prefixIcon={SiStatuspal}
        aria-label="Filter orders by status"
      />
      <Select
        name="product"
        value={filterForm.product}
        options={productOptions}
        onChange={handleControlChange}
        customClassName="sales-toolbar__select"
        prefixIcon={MdOutlineFilterList}
        aria-label="Filter orders by product"
      />
      <Select
        name="sort"
        value={filterForm.sort}
        options={salesSortOptions}
        onChange={handleControlChange}
        customClassName="sales-toolbar__select sales-toolbar__sort"
        prefixIcon={BiSort}
        aria-label="Sort orders"
      />
    </div>
  );

  const renderState = (): React.ReactNode => {
    if (ordersLoading && !ordersPage) {
      return (
        <div className="sales-state" role="status">
          <h2>Loading sales</h2>
        </div>
      );
    }

    if (ordersError || summaryError) {
      return (
        <div className="sales-state" role="status">
          <h2>Sales data is not available yet</h2>
          <p>
            Orders will appear here once order, payment, refund, and entitlement
            APIs are connected.
          </p>
        </div>
      );
    }

    if (!hasOrders && !hasActiveRefinement) {
      return (
        <div className="sales-state">
          <h2>No sales yet</h2>
          <p>Orders will appear here when customers purchase your products.</p>
          <Link className="sales-state__link" to="/app/products">
            View products
          </Link>
        </div>
      );
    }

    if (totalElements === 0 && hasSearch) {
      return (
        <div className="sales-state">
          <h2>{`No orders match "${filterForm.search.trim()}".`}</h2>
          <Button type="button" variant="secondary" onClick={clearSearch}>
            Clear search
          </Button>
        </div>
      );
    }

    if (totalElements === 0 && hasFilters) {
      return (
        <div className="sales-state">
          <h2>No orders match these filters.</h2>
          <Button type="button" variant="secondary" onClick={clearFilters}>
            Clear filters
          </Button>
        </div>
      );
    }

    return null;
  };

  return (
    <div className="sales-page">
      <header className="sales-header">
        <div>
          <h1>Sales</h1>
          <p>Track orders, payments, refunds, and failed charges.</p>
        </div>
      </header>

      {summary?.metrics && (
        <section className="sales-metrics" aria-label="Financial summary">
          {summary.metrics.map((metric) => (
            <article
              className={`sales-metric sales-metric--${metric.sentiment}`}
              key={metric.label}
            >
              <span className="sales-metric__label">{metric.label}</span>
              <strong>{metric.value}</strong>
              <span className="sales-metric__trend">
                {trendSymbol[metric.direction]} {metric.comparison}
              </span>
            </article>
          ))}
        </section>
      )}

      {hasControls && (
        <section className="sales-toolbar" aria-label="Sales controls">
          <Input
            value={filterForm.search}
            prefixIcon={FaSearch}
            onChange={handleControlChange}
            placeholder="Search customer, email, or order ID..."
            name="search"
            aria-label="Search customer, email, or order ID"
            className="sales-toolbar__search"
          />
          <div className="sales-toolbar__desktop-filters">{renderFilters()}</div>
          <Button
            type="button"
            variant="secondary"
            className="sales-toolbar__mobile-filter"
            onClick={() => setFiltersOpen(true)}
          >
            Filters{activeFilterCount > 0 ? ` (${activeFilterCount})` : ''}
          </Button>
        </section>
      )}

      {hasControls && (
        <div className="sales-collection-meta">
          <span>{resultCountLabel}</span>
          {hasActiveRefinement && (
            <Button type="button" variant="tertiary" size="sm" onClick={clearFilters}>
              Clear filters
            </Button>
          )}
        </div>
      )}

      {renderState() || (
        <>
          <section className="sales-ledger" aria-label="Orders ledger">
            <div className="sales-ledger__header" aria-hidden="true">
              <span>Date</span>
              <span>Customer</span>
              <span>Product</span>
              <span>Status</span>
              <span>Type</span>
              <span>Amount</span>
            </div>
            <div className="sales-ledger__rows">
              {orders.map((order) => (
                <OrderLedgerRow
                  key={order.id}
                  order={order}
                  onOpen={() => openOrder(order.id)}
                />
              ))}
            </div>
          </section>

          {totalPages > 1 && (
            <nav className="sales-pagination" aria-label="Order pages">
              <Button
                type="button"
                variant="secondary"
                size="sm"
                disabled={currentPage === 0}
                onClick={() => setPage((value) => Math.max(0, value - 1))}
              >
                Previous
              </Button>
              <span>
                Page {currentPage + 1} of {totalPages}
              </span>
              <Button
                type="button"
                variant="secondary"
                size="sm"
                disabled={currentPage >= totalPages - 1}
                onClick={() =>
                  setPage((value) => Math.min(totalPages - 1, value + 1))
                }
              >
                Next
              </Button>
            </nav>
          )}
        </>
      )}

      <OrderDetailDrawer order={selectedOrder} open={Boolean(selectedOrder)} onClose={closeOrder} />

      <Drawer
        open={filtersOpen}
        title={<h2 className="sales-filter-title">Filters</h2>}
        onClose={() => setFiltersOpen(false)}
        className="sales-filters-drawer"
      >
        {renderFilters(true)}
      </Drawer>
    </div>
  );
};

interface OrderLedgerRowProps {
  order: SalesOrderListItem;
  onOpen: () => void;
}

const OrderLedgerRow: React.FC<OrderLedgerRowProps> = ({ order, onOpen }) => {
  const items = getSalesOrderItems(order);
  const customerContent = (
    <>
      <span className="sales-ledger-row__primary">{order.customer.name}</span>
      <span>{order.customer.email}</span>
    </>
  );

  return (
    <article className="sales-ledger-row">
      <button
        type="button"
        className="sales-ledger-row__date"
        onClick={onOpen}
        aria-label={`Open ${order.id} order detail`}
      >
        <span>{formatSalesShortDate(order.orderedAt)}</span>
        <span>{order.id}</span>
      </button>

      <div className="sales-ledger-row__customer">
        {order.customer.id ? (
          <Link
            to={`/app/customers/${order.customer.id}`}
            aria-label={`Open ${order.customer.name} customer profile`}
          >
            {customerContent}
          </Link>
        ) : (
          <span className="sales-ledger-row__stack">{customerContent}</span>
        )}
      </div>

      <div className="sales-ledger-row__product sales-order-items">
        {items.length > 0 ? (
          items.map((item, index) => (
            <SalesOrderItemSummary
              key={`${item.product.id}-${index}`}
              item={item}
              currency={order.currency}
            />
          ))
        ) : (
          <span className="sales-ledger-row__stack">No product data</span>
        )}
      </div>

      <div className="sales-ledger-row__status">
        <StatusBadge
          label={orderStatusLabel[order.status]}
          tone={orderStatusTone[order.status]}
        />
      </div>
      <div className="sales-ledger-row__type">{orderTypeLabel[order.type]}</div>
      <div className="sales-ledger-row__amount">
        {formatSalesMoney(order.amountCents, order.currency)}
      </div>
    </article>
  );
};

interface OrderDetailDrawerProps {
  order?: SalesOrderDetail;
  open: boolean;
  onClose: () => void;
}

const OrderDetailDrawer: React.FC<OrderDetailDrawerProps> = ({
  order,
  open,
  onClose,
}) => {
  if (!order) {
    return null;
  }

  const items = getSalesOrderItems(order);
  const membershipItem = items.find(
    (item) => item.product.type === 'Membership',
  );

  return (
    <Drawer
      open={open}
      title={
        <div className="order-detail-title">
          <span>Order #{order.id}</span>
          <StatusBadge
            label={orderStatusLabel[order.status]}
            tone={orderStatusTone[order.status]}
          />
        </div>
      }
      onClose={onClose}
      className="order-detail-drawer"
    >
      <div className="order-detail">
        <section className="order-detail-hero" aria-label="Order summary">
          <strong>{formatSalesMoney(order.amountCents, order.currency)}</strong>
          <span>{orderTypeLabel[order.type]}</span>
          <time dateTime={order.orderedAt}>{formatSalesDateTime(order.orderedAt)}</time>
        </section>

        <DetailSection title="Customer">
          <p className="order-detail__primary">{order.customer.name}</p>
          <p>{order.customer.email}</p>
          {order.customer.id && (
            <Link to={`/app/customers/${order.customer.id}`}>View customer</Link>
          )}
        </DetailSection>

        <DetailSection title="Items">
          {items.length > 0 ? (
            <div className="order-detail-items">
              {items.map((item, index) => (
                <SalesOrderItemDetail
                  key={`${item.product.id}-${index}`}
                  item={item}
                  currency={order.currency}
                />
              ))}
            </div>
          ) : (
            <p>No order items are available.</p>
          )}
        </DetailSection>

        <DetailSection title="Payment">
          <DefinitionList
            rows={[
              ['Provider', order.provider],
              ['Payment method', order.paymentMethod],
              ['Transaction ID', order.transactionId],
              ['Payment date', formatSalesDateTime(order.paymentDate)],
              ['Currency', order.currency],
            ]}
          />
        </DetailSection>

        <DetailSection title="Order Summary">
          <DefinitionList
            rows={order.summaryRows.map((row) => [
              row.label,
              formatSalesMoney(row.amountCents, order.currency),
            ])}
          />
        </DetailSection>

        {order.subscription && (
          <DetailSection title="Subscription">
            <DefinitionList
              rows={[
                ['Membership', membershipItem?.product.name],
                [
                  'Billing price',
                  `${formatSalesMoney(
                    order.subscription.priceCents,
                    order.subscription.currency,
                  )} / ${order.subscription.interval}`,
                ],
                ['State', subscriptionStateLabel[order.subscription.state]],
                ['Next billing', formatSalesDateTime(order.subscription.nextBillingAt)],
              ]}
            />
          </DetailSection>
        )}

        {order.refund && (
          <DetailSection title="Refund">
            <DefinitionList
              rows={[
                [
                  'Amount refunded',
                  formatSalesMoney(order.refund.amountCents, order.currency),
                ],
                ['Refund date', formatSalesDateTime(order.refund.refundedAt)],
                ['Reason', order.refund.reason],
              ]}
            />
          </DetailSection>
        )}

        {order.failure && (
          <DetailSection title="Failed payment">
            <p className="order-detail__primary">Payment failed</p>
            <p>{order.failure.message}</p>
            {order.failure.retryAt && (
              <p>Retry scheduled {formatSalesDateTime(order.failure.retryAt)}</p>
            )}
          </DetailSection>
        )}
      </div>
    </Drawer>
  );
};

const SalesOrderItemSummary: React.FC<{
  item: CreatorSalesOrderItem;
  currency: string;
}> = ({ item, currency }) => {
  const productLabel = (
    <>
      <span className="sales-ledger-row__primary">{item.product.name}</span>
      <span>
        {item.product.type} · {formatSalesMoney(item.amountCents, currency)}
