import React, { useEffect, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';

import {
  AdminUser,
  AppDispatch,
  ProductStatus,
  ProductType,
  UserRole,
} from 'core/api/models';
import { getAdminUsersAPI } from 'core/api/services';
import {
  fetchAdminProducts,
  selectAdminError,
  selectAdminLoading,
  selectAdminProductsPage,
} from 'core/store/admin-store';
import { deleteProduct } from 'core/store/product-store';
import { PRODUCT_FILTER_OPTIONS } from 'core/constants';

import './admin-page.styles.scss';

const productTypes: ProductType[] = PRODUCT_FILTER_OPTIONS.map(
  (option) => option.type,
);
const productStatuses: ProductStatus[] = ['DRAFT', 'PUBLISHED', 'HIDDEN'];

const AdminProductsPage: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const productsPage = useSelector(selectAdminProductsPage);
  const loading = useSelector(selectAdminLoading);
  const error = useSelector(selectAdminError);
  const [search, setSearch] = useState('');
  const [ownerId, setOwnerId] = useState('');
  const [type, setType] = useState<ProductType | ''>('');
  const [status, setStatus] = useState<ProductStatus | ''>('');
  const [page, setPage] = useState(0);
  const [creators, setCreators] = useState<AdminUser[]>([]);
  const [selectedCreatorId, setSelectedCreatorId] = useState('');

  useEffect(() => {
    dispatch(
      fetchAdminProducts({ search, ownerId, type, status, page, size: 20 }),
    );
  }, [dispatch, search, ownerId, type, status, page]);

  useEffect(() => {
    getAdminUsersAPI({ role: UserRole.CREATOR, page: 0, size: 100 })
      .then((response) => setCreators(response.content))
      .catch(() => setCreators([]));
  }, []);

  const refreshCurrentPage = () => {
    dispatch(
      fetchAdminProducts({ search, ownerId, type, status, page, size: 20 }),
    );
  };

  const handleDelete = (productId?: string) => {
    if (!productId || !window.confirm('Delete this product?')) {
      return;
    }
    dispatch(deleteProduct({ productId }))
      .unwrap()
      .then(refreshCurrentPage);
  };

  return (
    <section className="admin-page">
      <header className="admin-page__header">
        <h1>Products</h1>
        <p>Admins can manage every product and create products for creators.</p>
      </header>

      <div className="admin-toolbar">
        <input
          aria-label="Search products"
          placeholder="Search products"
          value={search}
          onChange={(event) => {
            setPage(0);
            setSearch(event.target.value);
          }}
        />
        <input
          aria-label="Owner id"
          placeholder="Owner id"
          value={ownerId}
          onChange={(event) => {
            setPage(0);
            setOwnerId(event.target.value);
          }}
        />
        <select
          aria-label="Filter by type"
          value={type}
          onChange={(event) => {
            setPage(0);
            setType(event.target.value as ProductType | '');
          }}
        >
          <option value="">All types</option>
          {productTypes.map((item) => (
            <option key={item} value={item}>
              {item}
            </option>
          ))}
        </select>
        <select
          aria-label="Filter by status"
          value={status}
          onChange={(event) => {
            setPage(0);
            setStatus(event.target.value as ProductStatus | '');
          }}
        >
          <option value="">All statuses</option>
          {productStatuses.map((item) => (
            <option key={item} value={item}>
              {item}
            </option>
          ))}
        </select>
      </div>

      <div className="admin-create-row">
        <select
          aria-label="Creator owner"
          value={selectedCreatorId}
          onChange={(event) => setSelectedCreatorId(event.target.value)}
        >
          <option value="">Select creator owner</option>
          {creators.map((creator) => (
            <option key={creator.id} value={creator.id}>
              {`${creator.firstName ?? ''} ${creator.lastName ?? ''}`.trim() ||
                creator.email}
            </option>
          ))}
        </select>
        <button
          disabled={!selectedCreatorId}
          onClick={() =>
            navigate(`/app/admin/products/create?ownerId=${selectedCreatorId}`)
          }
        >
          Create product
        </button>
      </div>

      {error && <p className="admin-error">{error}</p>}
      {loading && <p>Loading...</p>}

      <div className="admin-table-wrap">
        <table className="admin-table">
          <thead>
            <tr>
              <th>Product</th>
              <th>Owner</th>
              <th>Type</th>
              <th>Status</th>
              <th>Price</th>
              <th>Updated</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {productsPage?.content.map((product) => (
              <tr key={product.id}>
                <td>{product.title}</td>
                <td>
                  <span>{product.createdByName ?? '-'}</span>
                  <small>{product.createdById}</small>
                </td>
                <td>{product.type}</td>
                <td>{product.status}</td>
                <td>{product.price ?? 'free'}</td>
                <td>
                  {product.updatedAt
                    ? new Date(product.updatedAt).toLocaleString()
                    : '-'}
                </td>
                <td className="admin-table__actions">
                  <button onClick={() => navigate(`/app/product/${product.id}`)}>
                    View
                  </button>
                  <button onClick={() => navigate(`/app/products/edit/${product.id}`)}>
                    Edit
                  </button>
                  <button onClick={() => handleDelete(product.id)}>Delete</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="admin-pagination">
        <button disabled={page === 0} onClick={() => setPage((value) => value - 1)}>
          Previous
        </button>
        <span>
          Page {productsPage ? productsPage.number + 1 : page + 1} of{' '}
          {productsPage?.totalPages || 1}
        </span>
        <button
          disabled={Boolean(productsPage?.last)}
          onClick={() => setPage((value) => value + 1)}
        >
          Next
        </button>
      </div>
    </section>
  );
};

export default AdminProductsPage;

import { useDispatch, useSelector } from 'react-redux';
import { useCallback } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';

import {
  AbstractProduct,
  AppDispatch,
  hasRole,
  UserRole,
} from 'core/api/models';
import { selectAuthUser } from 'core/store/auth-store';
import { UseProductFormFacadeResult } from '../models/product-form';
import { useProductAutosave } from './use-product-autosave.hook';
import { useProductFormState } from './use-product-form-state.hook';
import { useProductLoader } from './use-product-loader.hooks';
import { useProductActions } from './use-product.actions.hook';
import {
  useSidebarSections,
  useSidebarScroll,
} from './use-sidebar-scroll.hook';

export const useProductFormFacade = (): UseProductFormFacadeResult => {
  const { type, id } = useParams();
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const dispatch = useDispatch<AppDispatch>();
  const user = useSelector(selectAuthUser);
  const isEditMode = Boolean(id);
  const selectedAdminOwnerId = searchParams.get('ownerId') ?? undefined;
  const isAdmin = hasRole(user?.roles, UserRole.ADMIN);

  // 1) core form state
  const {
    formData,
    setFormData,
    setField,
    errors,
    setErrors,
    validateForm,
    handleSetPrice,
    productImage,
    handleImageChange,
    showRestOfForm,
    setShowRestOfForm,
    showLoadingRestOfForm,
    setShowLoadingRestOfForm,
  } = useProductFormState();

  const handleProductLoaded = useCallback(
    (product: AbstractProduct) => {
      if (type && product.type !== type) {
        navigate(`/app/products/edit/${product.id}`, { replace: true });
      }
    },
    [navigate, type],
  );

  // 2) load existing product
  useProductLoader({
    isEditMode,
    id,
    dispatch,
    setFormData,
    setErrors,
    setShowRestOfForm,
    onProductLoaded: handleProductLoaded,
  });

  // 3) autosave
  const {
    isAutosaving,
    hasPendingAutosave,
    lastSavedAt,
    flushAutosave,
  } = useProductAutosave({
    formData,
    user,
    showRestOfForm,
    dispatch,
  });

  // 4) actions: submit / update / remove
  const { handleSubmit, handleProductRemove } = useProductActions({
    formData,
    user,
    dispatch,
    validateForm,
    setErrors,
    setShowLoadingRestOfForm,
  });

  // 5) sidebar
  const sidebarSections = useSidebarSections(formData);
  const { handleSidebarSectionClick, handleSidebarLessonClick } =
    useSidebarScroll();

  return {
    user,
    isEditMode,
    productOwnerId:
      !isEditMode && isAdmin && selectedAdminOwnerId
        ? selectedAdminOwnerId
        : formData.userId ?? user?.id,
    formData,
    setFormData,
    setField,
    productImage,
    handleImageChange,
    handleSetPrice,
    showRestOfForm,
    setShowRestOfForm,
    showLoadingRestOfForm,
    setShowLoadingRestOfForm,
    errors,
    handleSubmit,
    handleProductRemove,
    handleSidebarSectionClick,
    handleSidebarLessonClick,
    sidebarSections,
    isAutosaving,
    hasPendingAutosave,
    flushAutosave,
    lastSavedAt,
  };
};

