package com.myproject.video.video_platform.service.product;

import com.myproject.video.video_platform.common.enums.user.UserRole;
import com.myproject.video.video_platform.dto.products.AbstractProductRequestDto;
import com.myproject.video.video_platform.entity.products.Product;
import com.myproject.video.video_platform.entity.user.Role;
import com.myproject.video.video_platform.entity.user.User;
import com.myproject.video.video_platform.exception.user.UserNotFoundException;
import com.myproject.video.video_platform.repository.auth.UserRepository;
import com.myproject.video.video_platform.service.user.CurrentUserService;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Service;

import java.util.UUID;

@Service
public class ProductAuthorizationService {

    private final CurrentUserService currentUserService;
    private final UserRepository userRepository;

    public ProductAuthorizationService(CurrentUserService currentUserService,
                                       UserRepository userRepository) {
        this.currentUserService = currentUserService;
        this.userRepository = userRepository;
    }

    public boolean isCurrentUserAdmin() {
        Authentication auth = SecurityContextHolder.getContext().getAuthentication();
        return auth != null && auth.getAuthorities().stream()
                .anyMatch(authority -> UserRole.ADMIN.authority().equals(authority.getAuthority()));
    }

    public UUID getCurrentUserId() {
        return currentUserService.getCurrentUserId();
    }

    public void requireOwnerOrAdmin(Product product) {
        requireOwnerOrAdmin(product.getUser().getUserId());
    }

    public void requireOwnerOrAdmin(UUID ownerId) {
        if (isCurrentUserAdmin()) {
            return;
        }

        UUID currentUserId = currentUserService.getCurrentUserId();
        if (!ownerId.equals(currentUserId)) {
            throw new AccessDeniedException("You don’t own this product.");
        }
    }

    public User resolveOwnerForCreate(AbstractProductRequestDto dto) {
        if (isCurrentUserAdmin()) {
            if (dto.getUserId() == null || dto.getUserId().isBlank()) {
                throw new AccessDeniedException("Admin product creation requires a creator owner");
            }

            User owner = getUser(UUID.fromString(dto.getUserId()));
            if (!hasSingleRole(owner, UserRole.CREATOR)) {
                throw new AccessDeniedException("Product owner must have CREATOR role");
            }
            return owner;
        }

        UUID currentUserId = currentUserService.getCurrentUserId();
        User owner = getUser(currentUserId);
        dto.setUserId(currentUserId.toString());
        return owner;
    }

    private User getUser(UUID userId) {
        return userRepository.findById(userId)
                .orElseThrow(() -> new UserNotFoundException("User not found: " + userId));
    }

    private boolean hasSingleRole(User user, UserRole role) {
        return user.getRoles().size() == 1
                && user.getRoles().stream()
                .map(Role::getRoleName)
                .anyMatch(role.name()::equals);
    }
}

import React, { useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { IoAddOutline } from 'react-icons/io5';

import { Button, Icon, Input, Textarea } from '@shared/ui';
import {
  AppDispatch,
  ProductSectionCreateRequest,
  ProductType,
} from 'core/api/models';
import { selectAuthUser } from 'core/store/auth-store';
import {
  createProductSection,
  deleteProductSection,
  updateProductSection,
} from 'core/store/product-store';
import { getCssVar } from '@shared/utils';
import SectionEditor from '../editors/section-editor/section-editor.component';
import { SectionDraft } from '../models';

import './create-product-sections.styles.scss';

interface CreateProductSectionsProps {
  sections: SectionDraft[];
  productType: ProductType;
  productId: string;
  // eslint-disable-next-line no-unused-vars
  onSectionsChange: (sections: SectionDraft[]) => void;
}

const getContentCopy = (productType: ProductType) =>
  productType === 'DOWNLOAD'
    ? {
      title: 'Files',
      description: 'Organize the files customers receive with this Download.',
      emptyTitle: 'Create a file group to start adding customer downloads.',
      emptyDescription:
          'File groups keep related deliverables together and make larger Downloads easier to scan.',
      addLabel: 'Add file group',
      firstAddLabel: 'Add your first file group',
      titleLabel: 'File group title',
      titlePlaceholder: 'Launch assets',
      descriptionLabel: 'File group description',
      descriptionPlaceholder: 'Describe the files in this group.',
      entityName: 'file group',
      deleteCopy:
          'This removes the file group and any files it contains from this Download.',
    }
    : {
      title: 'Curriculum',
      description: 'Build and organize the lessons included in this Course.',
      emptyTitle: 'Add your first section to start building this Course.',
      emptyDescription:
          'Sections group related lessons so customers can understand the learning path.',
      addLabel: 'Add section',
      firstAddLabel: 'Add your first section',
      titleLabel: 'Section title',
      titlePlaceholder: 'Getting started',
      descriptionLabel: 'Section description',
      descriptionPlaceholder: 'Describe what this section covers.',
      entityName: 'section',
      deleteCopy:
          'This removes the section and any lessons it contains from this Course.',
    };

const normalizePositions = (sections: SectionDraft[]) =>
  sections.map((section, index) => ({
    ...section,
    position: index + 1,
  }));

const CreateProductSections: React.FC<CreateProductSectionsProps> = ({
  sections,
  productType,
  productId,
  onSectionsChange,
}) => {
  const dispatch = useDispatch<AppDispatch>();
  const user = useSelector(selectAuthUser);
  const copy = getContentCopy(productType);
  const [isCreating, setIsCreating] = useState(false);
  const [draftTitle, setDraftTitle] = useState('');
  const [draftDescription, setDraftDescription] = useState('');
  const [createError, setCreateError] = useState<string | null>(null);
  const [isSavingCreate, setIsSavingCreate] = useState(false);
  const [deleteTargetId, setDeleteTargetId] = useState<string | null>(null);
  const [operationError, setOperationError] = useState<string | null>(null);

  const handleSectionChange = (index: number, nextSection: SectionDraft) => {
    const updated = sections.map((section: SectionDraft, i: number) =>
      i === index ? nextSection : section,
    );
    onSectionsChange(updated);
  };

  const resetCreate = () => {
    setDraftTitle('');
    setDraftDescription('');
    setCreateError(null);
    setIsCreating(false);
  };

  const handleCreateSection = async () => {
    const title = draftTitle.trim();

    if (!title) {
      setCreateError(`${copy.titleLabel} is required.`);
      return;
    }

    if (!user?.id) {
      setCreateError('Creator session is required before content can be created.');
      return;
    }

    const payload: ProductSectionCreateRequest = {
      productId,
      title,
      description: draftDescription.trim(),
      position: sections.length + 1,
    };

    setIsSavingCreate(true);
    setCreateError(null);

    try {
      const createdSection = await dispatch(createProductSection(payload)).unwrap();
      const nextSection: SectionDraft = {
        id: createdSection.id ?? '',
        title: createdSection.title,
        description: createdSection.description ?? '',
        position: createdSection.position,
        lessons: createdSection.lessons ?? [],
        files: createdSection.files ?? [],
      };

      onSectionsChange(normalizePositions([...sections, nextSection]));
      resetCreate();
    } catch (error) {
      setCreateError(
        typeof error === 'string'
          ? error
          : `Could not create this ${copy.entityName}.`,
      );
    } finally {
      setIsSavingCreate(false);
    }
  };

  const persistSectionPosition = (section: SectionDraft, position: number) => {
    if (!section.id) {
      return;
    }

    dispatch(
      updateProductSection({
        productId,
        sectionId: section.id,
        title: section.title,
        description: section.description,
        position,
      }),
    )
      .unwrap()
      .catch(() => {
        setOperationError(`Could not save ${copy.entityName} order.`);
      });
  };

  const handleMoveSection = (index: number, direction: -1 | 1) => {
    const nextIndex = index + direction;
    if (nextIndex < 0 || nextIndex >= sections.length) {
      return;
    }

    const next = [...sections];
    const [moved] = next.splice(index, 1);
    next.splice(nextIndex, 0, moved);
    const normalized = normalizePositions(next);

    onSectionsChange(normalized);
    persistSectionPosition(normalized[index], normalized[index].position);
    persistSectionPosition(
      normalized[nextIndex],
      normalized[nextIndex].position,
    );
  };

  const handleDeleteSection = async (section: SectionDraft, index: number) => {
    if (!section.id) {
      onSectionsChange(normalizePositions(sections.filter((_, i) => i !== index)));
      return;
    }

    try {
      await dispatch(
        deleteProductSection({
          productId,
          sectionId: section.id,
        }),
      ).unwrap();
      onSectionsChange(normalizePositions(sections.filter((_, i) => i !== index)));
      setDeleteTargetId(null);
    } catch (error) {
      setOperationError(
        typeof error === 'string'
          ? error
          : `Could not delete this ${copy.entityName}.`,
      );
    }
  };

  return (
    <div className="sections-wrapper">
      <div className="content-manager__intro">
        <div>
          <h3>{copy.title}</h3>
          <p>{copy.description}</p>
        </div>
        {!isCreating && sections.length > 0 && (
          <Button
            type="button"
            variant="secondary"
            onClick={() => setIsCreating(true)}
          >
            <Icon
              icon={IoAddOutline}
              color={getCssVar('--text-primary')}
              size={18}
            />
            <span>{copy.addLabel}</span>
          </Button>
        )}
      </div>

      {operationError && (
        <p className="content-manager__error" role="alert">
          {operationError}
        </p>
      )}

      {sections.length === 0 && !isCreating && (
        <div className="content-manager__empty">
          <h4>{copy.emptyTitle}</h4>
          <p>{copy.emptyDescription}</p>
          <Button type="button" onClick={() => setIsCreating(true)}>
            <Icon
              icon={IoAddOutline}
              color={getCssVar('--surface-canvas')}
              size={18}
            />
            <span>{copy.firstAddLabel}</span>
          </Button>
        </div>
      )}

      {isCreating && (
        <section
          className="content-manager__create"
          aria-labelledby="create-content-group-title"
        >
          <div>
            <h4 id="create-content-group-title">{copy.addLabel}</h4>
            <p>Create the group first, then add lessons or files.</p>
          </div>
          <Input
            name="content-group-title"
            label={copy.titleLabel}
            value={draftTitle}
            placeholder={copy.titlePlaceholder}
            error={createError ?? undefined}
            onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
              setDraftTitle(event.target.value)
            }
          />
          <Textarea
            name="content-group-description"
            label={copy.descriptionLabel}
            value={draftDescription}
            placeholder={copy.descriptionPlaceholder}
            onChange={(event: React.ChangeEvent<HTMLTextAreaElement>) =>
              setDraftDescription(event.target.value)
            }
          />
          <div className="content-manager__create-actions">
            <Button type="button" variant="tertiary" onClick={resetCreate}>
              Cancel
            </Button>
            <Button
              type="button"
              onClick={handleCreateSection}
              loading={isSavingCreate}
            >
              Create {copy.entityName}
            </Button>
          </div>
        </section>
      )}

      <div className="content-manager__groups">
        {sections.map((sectionData: SectionDraft, index: number) => (
          <SectionEditor
            key={sectionData.id || index}
            index={index}
            section={sectionData}
            productType={productType}
            productId={productId}
            onChange={handleSectionChange}
            onMoveUp={() => handleMoveSection(index, -1)}
            onMoveDown={() => handleMoveSection(index, 1)}
            canMoveUp={index > 0}
            canMoveDown={index < sections.length - 1}
            deleteCopy={copy.deleteCopy}
            deleteTargetId={deleteTargetId}
            showRemoveButton={sections.length > 1}
            onRequestDelete={() => setDeleteTargetId(sectionData.id ?? `${index}`)}
            onCancelDelete={() => setDeleteTargetId(null)}
            onConfirmDelete={() => handleDeleteSection(sectionData, index)}
          />
        ))}
      </div>
    </div>
  );
};

export default CreateProductSections;

/* eslint-disable indent */
import React, { useEffect, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { HiArrowDown, HiArrowUp, HiOutlineTrash } from 'react-icons/hi';
import { PiRectangleDashed } from 'react-icons/pi';

import CourseLessons from '../../course-lessons/course-lessons.component';
import {
  AppDispatch,
  FileDownloadProductResponse,
  ProductSection,
  ProductType,
} from 'core/api/models';
import {
  Button,
  Icon,
  StatusBadge,
  Textarea,
  UppyFileUploader,
} from '@shared/ui';
import { selectAuthUser } from 'core/store/auth-store';
import {
  deleteDownloadSectionFile,
  uploadDownloadSectionFile,
} from 'core/store/product-store';
import { EditableTitle } from '../editable-title';
import { getCssVar } from '@shared/utils';
import { SectionDraft } from 'domains/app/features/product-form/models';
import { useSectionAutosave } from 'domains/app/features/product-form/hooks';

import './section-editor.styles.scss';

interface SectionEditorProps {
  index: number;
  section: SectionDraft;
  productType: ProductType;
  productId: string;
  // eslint-disable-next-line no-unused-vars
  onChange: (index: number, section: SectionDraft) => void;
  onMoveUp?: () => void;
  onMoveDown?: () => void;
  canMoveUp?: boolean;
  canMoveDown?: boolean;
  deleteCopy?: string;
  deleteTargetId?: string | null;
  onRequestDelete?: () => void;
  onCancelDelete?: () => void;
  onConfirmDelete?: () => void;
  showRemoveButton?: boolean;
  // eslint-disable-next-line no-unused-vars
  onRemove?: (index: number) => void;
}

type UploadStatus = 'uploading' | 'uploaded' | 'failed';

const formatFileSize = (size?: number) => {
  if (!size) {
    return 'Size unavailable';
  }

  if (size < 1024 * 1024) {
    return `${(size / 1024).toFixed(1)} KB`;
  }

  return `${(size / (1024 * 1024)).toFixed(1)} MB`;
};

const getFileTypeLabel = (fileType?: string, fileName?: string) => {
  const extension = fileName?.split('.').pop()?.toUpperCase();
  if (extension && extension.length <= 5) {
    return extension;
  }

  if (!fileType) {
    return 'File';
  }

  return fileType.split('/').pop()?.toUpperCase() ?? 'File';
};

const SectionEditor: React.FC<SectionEditorProps> = ({
  index,
  section,
  productType,
  productId,
  onChange,
  onMoveUp = () => undefined,
  onMoveDown = () => undefined,
  canMoveUp = false,
  canMoveDown = false,
  deleteCopy = 'This removes this content group.',
  deleteTargetId,
  onRequestDelete = () => undefined,
  onCancelDelete = () => undefined,
  onConfirmDelete = () => undefined,
  onRemove,
}) => {
  const dispatch = useDispatch<AppDispatch>();
  const user = useSelector(selectAuthUser);
  const latestSectionRef = useRef(section);
  const uploadedFileSignaturesRef = useRef(new Set<string>());
  const uploadedFileSignatureByIdRef = useRef(new Map<string, string>());
  const [uploadStatusBySignature, setUploadStatusBySignature] = useState<
    Record<string, UploadStatus>
  >({});
  const [fileDeleteTargetId, setFileDeleteTargetId] = useState<string | null>(
    null,
  );
  const [operationError, setOperationError] = useState<string | null>(null);
  const [isLocalDeleteOpen, setIsLocalDeleteOpen] = useState(false);

  const { isAutosaving, lastSavedAt } = useSectionAutosave({
    section,
    user,
    productId,
    dispatch,
  });

  useEffect(() => {
    latestSectionRef.current = section;
  }, [section]);

  const applySectionUpdate = (updater: (current: SectionDraft) => SectionDraft) => {
    const next = updater(latestSectionRef.current);
    latestSectionRef.current = next;
    onChange(index, next);
  };

  const updateSection = (patch: Partial<SectionDraft>) => {
    applySectionUpdate((current) => ({
      ...current,
      ...patch,
    }));
  };

  const handleFilesChange = (filesFromUploader: File[]) => {
    if (productType !== 'DOWNLOAD' || !section.id) {
      return;
    }

    const getSignature = (file: File) =>
      `${file.name}:${file.size}:${file.lastModified}`;

    filesFromUploader.forEach((file) => {
      const signature = getSignature(file);

      if (uploadedFileSignaturesRef.current.has(signature)) {
        return;
      }

      uploadedFileSignaturesRef.current.add(signature);
      setUploadStatusBySignature((current) => ({
        ...current,
        [signature]: 'uploading',
      }));

      dispatch(
        uploadDownloadSectionFile({
          productId,
          sectionId: section.id ?? '',
          file,
        }),
      )
        .unwrap()
        .then(({ file: uploadedFile }) => {
          if (uploadedFile.id) {
            uploadedFileSignatureByIdRef.current.set(uploadedFile.id, signature);
          }

          setUploadStatusBySignature((current) => ({
            ...current,
            [signature]: 'uploaded',
          }));

          applySectionUpdate((current) => {
            const existingFiles = current.files ?? [];
            const alreadyExists = existingFiles.some(
              (existing) => existing.id === uploadedFile.id,
            );

            if (alreadyExists) {
              return current;
            }

            return {
              ...current,
              files: [...existingFiles, uploadedFile],
            };
          });
        })
        .catch((error) => {
          uploadedFileSignaturesRef.current.delete(signature);
          setUploadStatusBySignature((current) => ({
            ...current,
            [signature]: 'failed',
          }));
          setOperationError(
            typeof error === 'string'
              ? error
              : `Could not upload ${file.name}. Try again.`,
          );
        });
    });
  };

  const handleRemoveUploadedFile = (fileId?: string) => {
    if (!fileId || productType !== 'DOWNLOAD' || !section.id) {
      return;
    }

    dispatch(
      deleteDownloadSectionFile({
        productId,
        sectionId: section.id,
        fileId,
      }),
    )
      .unwrap()
      .then(() => {
        const signature = uploadedFileSignatureByIdRef.current.get(fileId);
        if (signature) {
          uploadedFileSignaturesRef.current.delete(signature);
          uploadedFileSignatureByIdRef.current.delete(fileId);
          setUploadStatusBySignature((current) => {
            const next = { ...current };
            delete next[signature];
            return next;
          });
        }

        applySectionUpdate((current) => ({
          ...current,
          files: (current.files ?? []).filter((file) => file.id !== fileId),
        }));
        setFileDeleteTargetId(null);
      })
      .catch((error) => {
        setOperationError(
          typeof error === 'string'
            ? error
            : 'Could not remove this file. Try again.',
        );
      });
  };

  const handleLessonsChange = (lessons: ProductSection['lessons']) => {
    updateSection({ lessons });
  };

  const isDeleteOpen =
    deleteTargetId === undefined
      ? isLocalDeleteOpen
      : deleteTargetId === (section.id || `${index}`);
  const handleRequestDelete = () => {
    if (deleteTargetId === undefined) {
      setIsLocalDeleteOpen(true);
      return;
    }

    onRequestDelete();
  };
  const handleCancelDelete = () => {
    if (deleteTargetId === undefined) {
      setIsLocalDeleteOpen(false);
      return;
    }

    onCancelDelete();
  };
  const handleConfirmDelete = () => {
    if (deleteTargetId === undefined) {
      onRemove?.(index);
      setIsLocalDeleteOpen(false);
      return;
    }

    onConfirmDelete();
  };
  const entityLabel = productType === 'DOWNLOAD' ? 'file group' : 'section';
  const childCount =
    productType === 'DOWNLOAD'
      ? (section.files ?? []).length
      : (section.lessons ?? []).length;
  const childLabel = productType === 'DOWNLOAD' ? 'files' : 'lessons';
  const sectionDomId = section.id || `temp-${index}`;

  return (
    <section
      className="section-editor content-group"
      id={`section-${sectionDomId}`}
      aria-labelledby={`section-title-${sectionDomId}`}
    >
      <header className="content-group__header">
        <div className="content-group__identity">
          <Icon
            icon={PiRectangleDashed}
            size={22}
            color={getCssVar('--text-primary')}
          />
          <div>
            <span className="content-group__eyebrow">
              {productType === 'DOWNLOAD' ? 'File group' : 'Section'} {index + 1}
            </span>
            <div id={`section-title-${sectionDomId}`}>
              <EditableTitle
                value={section.title}
                placeholder={
                  productType === 'DOWNLOAD'
                    ? `Untitled file group ${index + 1}`
                    : `Untitled section ${index + 1}`
                }
                onChange={(title: string) => updateSection({ title })}
              />
            </div>
          </div>
        </div>
        <div className="content-group__meta">
          <StatusBadge
            label={
              isAutosaving
                ? 'Saving'
                : lastSavedAt
                  ? 'Saved'
                  : `${childCount} ${childLabel}`
            }
            tone={isAutosaving ? 'info' : 'neutral'}
            size="sm"
          />
          <Button
            type="button"
            variant="tertiary"
            size="sm"
            onClick={onMoveUp}
            disabled={!canMoveUp}
            aria-label={`Move ${section.title || entityLabel} up`}
          >
            <Icon icon={HiArrowUp} size={16} color={getCssVar('--text-primary')} />
            <span>Up</span>
          </Button>
          <Button
            type="button"
            variant="tertiary"
            size="sm"
            onClick={onMoveDown}
            disabled={!canMoveDown}
            aria-label={`Move ${section.title || entityLabel} down`}
          >
            <Icon
              icon={HiArrowDown}
              size={16}
              color={getCssVar('--text-primary')}
            />
            <span>Down</span>
          </Button>
          <Button
            type="button"
            variant="danger"
            size="sm"
            onClick={handleRequestDelete}
            aria-label={`Delete ${section.title || entityLabel}`}
          >
            <Icon
              icon={HiOutlineTrash}
              size={16}
              color={getCssVar('--text-primary')}
            />
            <span>Delete</span>
          </Button>
        </div>
      </header>

      <Textarea
        label={
          productType === 'DOWNLOAD'
            ? 'File group description'
            : 'Section description'
        }
        name={`section-description-${sectionDomId}`}
        value={section.description ?? ''}
        onChange={(e: React.ChangeEvent<HTMLTextAreaElement>) =>
          updateSection({ description: e.target.value })
        }
        placeholder={
          productType === 'DOWNLOAD'
            ? 'Describe this group of files.'
            : 'Describe what this section covers.'
        }
        className="section-description"
        block
      />

      {isDeleteOpen && (
        <div className="content-group__confirm" role="alertdialog">
          <div>
            <strong>Delete {section.title || entityLabel}?</strong>
            <p>{deleteCopy}</p>
          </div>
          <div>
            <Button type="button" variant="tertiary" onClick={handleCancelDelete}>
              Cancel
            </Button>
            <Button type="button" variant="danger" onClick={handleConfirmDelete}>
              Delete {entityLabel}
            </Button>
          </div>
        </div>
      )}

      {operationError && (
        <p className="content-group__error" role="alert">
          {operationError}
        </p>
      )}

      {productType === 'COURSE' && (
        <CourseLessons
          productId={productId}
          sectionId={section.id ?? ''}
          lessons={(section as ProductSection).lessons || []}
          onLessonsChange={handleLessonsChange}
        />
      )}

      {productType === 'DOWNLOAD' && (
        <div className="download-specific-fields">
          <div className="download-upload">
            <UppyFileUploader onFilesChange={handleFilesChange} />
          </div>

          {(section.files ?? []).length === 0 ? (
            <div className="content-group__empty">
              <h4>No files in this group yet.</h4>
              <p>Add files customers should receive when they access this Download.</p>
            </div>
          ) : (
            <div className="download-uploaded-files" aria-live="polite">
              {(section.files ?? []).map((file: FileDownloadProductResponse) => {
                const signature = file.id
                  ? uploadedFileSignatureByIdRef.current.get(file.id)
                  : undefined;
                const uploadStatus = signature
                  ? uploadStatusBySignature[signature]
                  : undefined;
                const fileLabel = file.fileName ?? 'Uploaded file';

                return (
                  <div key={file.id ?? file.fileName} className="file-row">
                    <span className="file-row__type">
                      {getFileTypeLabel(file.fileType, file.fileName)}
                    </span>
                    <div className="file-row__details">
                      <strong>{fileLabel}</strong>
                      <span>
                        {formatFileSize(file.size)}
                        {uploadStatus && ` • ${uploadStatus}`}
                      </span>
                    </div>
                    {fileDeleteTargetId === file.id ? (
                      <div className="file-row__confirm">
                        <span>Remove this file?</span>
                        <Button
                          type="button"
                          variant="tertiary"
                          size="sm"
                          onClick={() => setFileDeleteTargetId(null)}
                        >
                          Cancel
                        </Button>
                        <Button
                          type="button"
                          variant="danger"
                          size="sm"
                          onClick={() => handleRemoveUploadedFile(file.id)}
                        >
                          Remove
                        </Button>
                      </div>
                    ) : (
                      <Button
                        type="button"
                        variant="danger"
                        size="sm"
                        onClick={() => setFileDeleteTargetId(file.id ?? null)}
                        aria-label={`Remove ${fileLabel}`}
                      >
                        Remove
                      </Button>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}
    </section>
  );
};

export default SectionEditor;

/* eslint-disable indent */
import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import clsx from 'clsx';

import { Button } from '@shared/ui';
import {
  CreateProductStepOne,
  ConsultationDetailsSection,
  CreateProductSections,
  BuilderSidebar,
  BuilderTab,
  useProductFormFacade,
  useProductFormAnimation,
  BasicInfo,
  ProductPricingSection,
  ProductMediaSection,
  ProductReadinessSection,
  ProductReadinessIssue,
  SectionDraft,
  MembershipContentSection,
  RecurringPricing,
  evaluateProductReadiness,
  MEMBERSHIP_DEFAULT_ORDERING_MODE,
  MembershipContentItem,
  MembershipFeedEntry,
  MembershipOrderingMode,
  MembershipProductFeedEntry,
  orderMembershipFeedEntries,
  resolveMembershipIncludedProducts,
  useGlobalSaveStatus,
} from 'domains/app/features/product-form';
import {
  AppDispatch,
  MembershipContentCreateRequest,
  MembershipContentUpdateRequest,
  ProductGalleryImage,
  ProductPromoVideo,
  ProductWithSections,
  RootState,
} from 'core/api/models';
import { appRoutes } from 'domains/app/routes/routes';
import {
  addImageToProduct,
  addProductGalleryImage,
  addProductPromoVideo,
  getProductSummariesByOwner,
  removeImageFromProduct,
  removeProductGalleryImage,
  removeProductPromoVideo,
  reorderProductGalleryImages,
  selectProductSummaries,
  selectProductsError,
  selectProductsLoading,
  updateProductDetails,
} from 'core/store/product-store';
import {
  createMembershipContent,
  deleteMembershipContent,
  fetchMembershipAggregate,
  selectMembershipAggregateByProductId,
  selectMembershipError,
  selectMembershipLoading,
  selectMembershipSaveError,
  selectMembershipSaving,
  updateMembershipContent,
  updateMembershipFeed,
} from 'core/store/membership-store';
import { ProductWorkspaceShell } from 'domains/app/layouts/product-workspace-shell';
import { mapFormDataToProductPayload } from 'domains/app/features/product-form/utils/form-data-mapper.utils';

import './product-form.styles.scss';

export interface FormErrors {
  name?: string;
  type?: string;
  price?: string;
  api?: string;
}

const getInitialBuilderTab = (): BuilderTab => 'basics';

const getRecurringPricingFromProduct = (
  formData: ReturnType<typeof useProductFormFacade>['formData'],
): RecurringPricing => ({
  amount: typeof formData.price === 'number' ? formData.price : 0,
  currency: formData.currency ?? 'EUR',
  interval: formData.billingInterval ?? 'MONTH',
});

const withFeedPositions = (feed: MembershipFeedEntry[]) =>
  feed.map((entry, index) => ({ ...entry, position: index + 1 }));

const tabCopy: Record<BuilderTab, { title: string; description: string }> = {
  basics: {
    title: 'Basics',
    description: 'Set the Product identity and core customer-facing description.',
  },
  pricing: {
    title: 'Pricing',
    description: 'Configure how customers pay for this Product.',
  },
  sections: {
    title: 'Content structure',
    description: 'Organize the Product content that customers receive after access.',
  },
  'consultation-details': {
    title: 'Availability',
    description: 'Configure the session details used for Consultation bookings.',
  },
  'membership-content': {
    title: 'Membership content',
    description: 'Manage the member-only feed and included Products.',
  },
  media: {
    title: 'Media',
    description: 'Manage Product-owned presentation media used across Storefront and Product pages.',
  },
  readiness: {
    title: 'Readiness',
    description: 'Review known publish blockers and backend readiness feedback.',
  },
};

const ProductForm: React.FC = () => {
  const dispatch = useDispatch<AppDispatch>();
  const navigate = useNavigate();
  const productSummaries = useSelector(selectProductSummaries);
  const productsLoading = useSelector(selectProductsLoading);
  const productsError = useSelector(selectProductsError);
  const {
    user,
    isEditMode,
    productOwnerId,
    formData,
    setFormData,
    setField,
    showRestOfForm,
    setShowRestOfForm,
    showLoadingRestOfForm,
    setShowLoadingRestOfForm,
    errors,
    handleSubmit,
    handleSidebarSectionClick,
    handleSidebarLessonClick,
    sidebarSections,
    isAutosaving,
    hasPendingAutosave,
    flushAutosave,
  } = useProductFormFacade();

  const membershipAggregate = useSelector((state: RootState) =>
    selectMembershipAggregateByProductId(state, formData.id),
  );
  const membershipLoading = useSelector(selectMembershipLoading);
  const membershipError = useSelector(selectMembershipError);
  const membershipSaving = useSelector(selectMembershipSaving);
  const membershipSaveError = useSelector(selectMembershipSaveError);
  const [activeTab, setActiveTab] = useState<BuilderTab | null>(null);
  const [isPublishing, setIsPublishing] = useState(false);
  const [publishError, setPublishError] = useState<string | null>(null);
  const [backendReadinessIssues, setBackendReadinessIssues] = useState<
    ProductReadinessIssue[]
  >([]);
  const membershipRecurringPricing = useMemo(
    () => getRecurringPricingFromProduct(formData),
    [formData],
  );
  const membershipNativeContentItems =
    membershipAggregate?.content ?? [] as MembershipContentItem[];
  const membershipFeedEntries = membershipAggregate?.feed ?? [];
  const membershipOrderingMode =
    membershipAggregate?.config.orderingMode ?? MEMBERSHIP_DEFAULT_ORDERING_MODE;
  const membershipIncludedProductEntries = membershipFeedEntries.filter(
    (entry): entry is MembershipProductFeedEntry => entry.kind === 'PRODUCT',
  );
  const includedProducts = useMemo(
    () =>
      resolveMembershipIncludedProducts(
        membershipIncludedProductEntries,
        productSummaries,
      ),
    [membershipIncludedProductEntries, productSummaries],
  );
  const isMembershipReadinessLoading = Boolean(
    formData.type === 'MEMBERSHIP' &&
      showRestOfForm &&
      (!membershipAggregate || membershipLoading),
  );
  const readinessResult = useMemo(() => evaluateProductReadiness({
    formData,
    recurringPricing: membershipRecurringPricing,
    membershipNativeContentItems,
    membershipIncludedProducts: includedProducts,
    isMembershipLoading: isMembershipReadinessLoading,
  }), [
    formData,
    includedProducts,
    isMembershipReadinessLoading,
    membershipNativeContentItems,
    membershipRecurringPricing,
  ]);
  const displayedReadinessResult = useMemo(() => ({
    ...readinessResult,
    blockers: [
      ...readinessResult.blockers,
      ...backendReadinessIssues,
    ],
    isReadyToPublish:
      readinessResult.isReadyToPublish && backendReadinessIssues.length === 0,
  }), [backendReadinessIssues, readinessResult]);
  const [hasHeroCollapsed, setHasHeroCollapsed] = useState(false);
  const [pendingSidebarScrollTarget, setPendingSidebarScrollTarget] = useState<{
    id: string;
    type: 'section' | 'lesson';
  } | null>(null);

  const container = useRef<HTMLDivElement>(null);
  const formRef = useRef<HTMLFormElement>(null);

  useEffect(() => {
    if (!formData.type || !showRestOfForm) {
      return;
    }

    if (!activeTab) {
      setActiveTab(getInitialBuilderTab());
    }
  }, [formData.type, showRestOfForm]);

  useEffect(() => {
    if (
      formData.type !== 'MEMBERSHIP' ||
      !showRestOfForm ||
      !productOwnerId ||
      productSummaries ||
      productsLoading
    ) {
      return;
    }

    dispatch(getProductSummariesByOwner(productOwnerId));
  }, [
    dispatch,
    formData.type,
    productOwnerId,
    productSummaries,
    productsLoading,
    showRestOfForm,
  ]);

  useEffect(() => {
    if (formData.type !== 'MEMBERSHIP' || !formData.id || !showRestOfForm) {
      return;
    }

    if (membershipAggregate || membershipLoading) {
      return;
    }

    dispatch(fetchMembershipAggregate(formData.id));
  }, [
    dispatch,
    formData.id,
    formData.type,
    membershipAggregate,
    membershipLoading,
    showRestOfForm,
  ]);

  useEffect(() => {
    if (activeTab !== 'sections' || !pendingSidebarScrollTarget) {
      return;
    }

    const timeoutId = window.setTimeout(() => {
      if (pendingSidebarScrollTarget.type === 'section') {
        handleSidebarSectionClick(pendingSidebarScrollTarget.id);
      } else {
        handleSidebarLessonClick(pendingSidebarScrollTarget.id);
      }

      setPendingSidebarScrollTarget(null);
    }, 0);

    return () => window.clearTimeout(timeoutId);
  }, [
    activeTab,
    pendingSidebarScrollTarget,
    handleSidebarLessonClick,
    handleSidebarSectionClick,
  ]);

  const handleSidebarSectionNavigation = (sectionId: string) => {
    if (activeTab === 'sections') {
      handleSidebarSectionClick(sectionId);
      return;
    }

    setPendingSidebarScrollTarget({ id: sectionId, type: 'section' });
    setActiveTab('sections');
  };

  const handleSidebarLessonNavigation = (lessonId: string) => {
    if (activeTab === 'sections') {
      handleSidebarLessonClick(lessonId);
      return;
    }

    setPendingSidebarScrollTarget({ id: lessonId, type: 'lesson' });
    setActiveTab('sections');
  };

  useProductFormAnimation(container, showRestOfForm, () => {
    setHasHeroCollapsed(true);
  });
  const saveStatus = useGlobalSaveStatus(
    isAutosaving || productsLoading || membershipSaving,
    Boolean(errors.api || productsError || membershipSaveError),
    {
      minSavingMs: 200,
      savedVisibleMs: 2000,
    },
  );

  if (!user || !user.id) {
    return <p>You must be logged in to create a product.</p>;
  }

  if (!isEditMode && !productOwnerId) {
    return <p>Select a creator owner before creating a product.</p>;
  }

  if (isEditMode && productsLoading && !showRestOfForm) {
    return (
      <ProductWorkspaceShell
        productType={formData.type}
        productTitle={formData.name}
        productStatus={formData.status}
        isEditMode={isEditMode}
        showWorkspace={false}
        saveStatus="idle"
        onBack={() => navigate(appRoutes.products)}
      >
        <main className="product-builder-state" aria-busy="true">
          <h1>Loading Product workspace</h1>
          <p>Preparing this Product for editing.</p>
        </main>
      </ProductWorkspaceShell>
    );
  }

  if (isEditMode && errors.api && !showRestOfForm) {
    return (
      <ProductWorkspaceShell
        productType={formData.type}
        productTitle={formData.name}
        productStatus={formData.status}
        isEditMode={isEditMode}
        showWorkspace={false}
        saveStatus="error"
        onBack={() => navigate(appRoutes.products)}
      >
        <main className="product-builder-state" role="alert">
          <h1>Product workspace unavailable</h1>
          <p>{errors.api}</p>
          <Button
            type="button"
            variant="secondary"
            onClick={() => navigate(appRoutes.products)}
          >
            Back to Products
          </Button>
        </main>
      </ProductWorkspaceShell>
    );
  }

  const hasReadinessBlockers = readinessResult.blockers.length > 0 ||
    readinessResult.isEvaluating;
  const isPublished = formData.status === 'PUBLISHED';
  const isMembership = formData.type === 'MEMBERSHIP';
  const canPreview = Boolean(formData.id);
  const previewDisabledReason = formData.id
    ? undefined
    : 'Save this Product before opening a private preview.';
  const publishHelpText = isPublished
    ? 'This Product is already published. Unpublish is not part of the current MVP lifecycle.'
    : isMembership
    ? 'Membership publishing is not available yet. Content metadata can be saved, but subscriptions, entitlements, and member access are unavailable.'
    : hasReadinessBlockers
    ? 'Publish will open Readiness until known blockers are resolved.'
    : 'Publish uses backend readiness validation after local checks pass.';

  useEffect(() => {
    setBackendReadinessIssues([]);
  }, [formData]);

  const backendReadinessDestinationByPath: Record<string, BuilderTab> = {
    name: 'basics',
    price: 'pricing',
    'details.sections': 'sections',
    'details.lessons': 'sections',
    'details.files': 'sections',
    'details.durationMinutes': 'consultation-details',
    'details.meetingMethod': 'consultation-details',
    'details.customLocation': 'consultation-details',
    'details.weeklyAvailability': 'consultation-details',
    status: 'readiness',
  };

  const isBackendReadinessError = (
    error: unknown,
  ): error is { message: string; errors: Record<string, string> } =>
    Boolean(
      error &&
      typeof error === 'object' &&
      'errors' in error &&
      typeof (error as { errors?: unknown }).errors === 'object',
    );

  const toBackendReadinessIssues = (
    errors: Record<string, string>,
  ): ProductReadinessIssue[] =>
    Object.entries(errors).map(([path, message]) => ({
      id: `backend-readiness-${path}`,
      severity: 'BLOCKER',
      title: path,
      description: message,
      destination: backendReadinessDestinationByPath[path] ?? 'readiness',
    }));

  const handleWorkspaceBack = async () => {
    try {
      await flushAutosave();
      navigate(appRoutes.products);
    } catch {
      const shouldLeave = window.confirm(
        'Latest Product changes could not be saved. Leave the workspace anyway?',
      );

      if (shouldLeave) {
        navigate(appRoutes.products);
      }
    }
  };

  const handlePreview = () => {
    if (!formData.id || !canPreview) {
      return;
    }

    navigate(appRoutes.productsPreview(formData.id));
  };

  const handlePublish = async () => {
    if (isPublished || isPublishing || isMembership) {
      return;
    }

    setPublishError(null);
    setBackendReadinessIssues([]);

    try {
      setIsPublishing(true);
      await flushAutosave();
    } catch {
      setActiveTab('readiness');
      setPublishError('Latest Product changes could not be saved. Resolve the save issue and try Publish again.');
      setIsPublishing(false);
      return;
    }

    if (hasReadinessBlockers) {
      setActiveTab('readiness');
      setPublishError(
        readinessResult.isEvaluating
          ? 'Readiness is still evaluating required Product data. Try again once it finishes loading.'
          : 'Resolve blockers before publishing this Product.',
      );
      setIsPublishing(false);
      return;
    }

    try {
      const payload = mapFormDataToProductPayload(
        {
          ...formData,
          status: 'PUBLISHED',
        },
        user,
      );
      const updatedProduct = await dispatch(updateProductDetails(payload)).unwrap();
      setField('status', updatedProduct.status ?? 'PUBLISHED');
    } catch (error) {
      if (isBackendReadinessError(error)) {
        setBackendReadinessIssues(toBackendReadinessIssues(error.errors));
        setPublishError(error.message);
      } else {
        setPublishError('Publish failed. Check the Product details and try again.');
      }
      setActiveTab('readiness');
    } finally {
      setIsPublishing(false);
    }
  };

  const renderReadinessPanel = () => (
    <ProductReadinessSection
      result={displayedReadinessResult}
      publishError={publishError}
      onNavigateToDestination={(destination) => setActiveTab(destination)}
    />
  );

  const renderActiveTabContent = () => {
    switch (activeTab) {
      case 'basics':
        return (
          <BasicInfo
            formData={formData}
            setField={setField}
            errors={errors}
            isEditMode={isEditMode}
          />
        );

      case 'pricing':
        return (
          <ProductPricingSection
            formData={formData}
            setField={setField}
            onMembershipRecurringPricingChange={
              handleMembershipRecurringPricingChange
            }
          />
        );

      case 'sections':
        return (
          <CreateProductSections
            sections={(formData as ProductWithSections).sections ?? []}
            productType={formData.type}
            productId={formData.id ?? ''}
            onSectionsChange={(sections) =>
              setField('sections', sections as SectionDraft[])
            }
          />
        );

      case 'consultation-details':
        return (
          <ConsultationDetailsSection
            formData={formData}
            errors={errors}
            setFormData={setFormData}
          />
        );

      case 'membership-content':
        return (
          <MembershipContentSection
            ownerId={productOwnerId}
            currentProductId={formData.id}
            nativeContentItems={membershipNativeContentItems}
            feedEntries={membershipFeedEntries}
            orderingMode={membershipOrderingMode}
            includedProductEntries={membershipIncludedProductEntries}
            productSummaries={productSummaries}
            includedProducts={includedProducts}
            isLoadingProducts={productsLoading || membershipLoading}
            productsError={productsError || membershipError}
            onAddNativeContentItem={handleCreateMembershipContent}
            onUpdateNativeContentItem={handleUpdateMembershipContent}
            onDeleteNativeContentItem={handleDeleteMembershipContent}
            onOrderingModeChange={handleMembershipOrderingModeChange}
            onAddIncludedProducts={handleAddIncludedProducts}
            onRemoveIncludedProduct={handleRemoveIncludedProduct}
            onMoveFeedEntry={handleMoveMembershipFeedEntry}
          />
        );

      case 'media':
        return (
          <ProductMediaSection
            productId={formData.id}
            productTitle={formData.name}
            thumbnailUrl={formData.imageUrl}
            galleryImages={formData.galleryImages as ProductGalleryImage[]}
            promoVideo={formData.promoVideo as ProductPromoVideo | null}
            onUploadThumbnail={handleUploadThumbnail}
            onRemoveThumbnail={handleRemoveThumbnail}
            onAddGalleryImage={handleAddGalleryImage}
            onRemoveGalleryImage={handleRemoveGalleryImage}
            onReorderGalleryImages={handleReorderGalleryImages}
            onUploadPromoVideo={handleUploadPromoVideo}
            onRemovePromoVideo={handleRemovePromoVideo}
          />
        );

      case 'readiness':
        return renderReadinessPanel();

      default:
        return null;
    }
  };

  const updateMembershipFeedForCurrentProduct = async (
    feed: MembershipFeedEntry[],
    orderingMode: MembershipOrderingMode = membershipOrderingMode,
  ) => {
    if (!formData.id) {
      throw new Error('Save this Membership before updating its content feed.');
    }

    await dispatch(
      updateMembershipFeed({
        productId: formData.id,
        payload: {
          orderingMode,
          feed: withFeedPositions(feed),
        },
      }),
    ).unwrap();
  };

  const handleMembershipRecurringPricingChange = (pricing: RecurringPricing) => {
    setField('price', pricing.amount);
    setField('pricingModel', 'RECURRING');
    setField('currency', pricing.currency);
    setField('billingInterval', pricing.interval);
  };

  const handleCreateMembershipContent = async (
    payload: MembershipContentCreateRequest,
  ) => {
    if (!formData.id) {
      throw new Error('Save this Membership before adding content.');
    }

    const result = await dispatch(
      createMembershipContent({ productId: formData.id, payload }),
    ).unwrap();

    const newEntry: MembershipFeedEntry = {
      entryId: `content:${result.content.id}`,
      kind: 'CONTENT',
      contentId: result.content.id,
      addedAt: result.content.createdAt,
    };
    const nextFeed =
      membershipOrderingMode === 'MANUAL'
        ? [newEntry, ...membershipFeedEntries]
        : [...membershipFeedEntries, newEntry];

    try {
      await updateMembershipFeedForCurrentProduct(nextFeed);
    } catch {
      try {
        await updateMembershipFeedForCurrentProduct(nextFeed);
      } catch {
        throw new Error(
          'Content was created, but it could not be attached to the Membership feed. Try again after the feed saves.',
        );
      }
    }
  };

  const handleUpdateMembershipContent = async (
    contentId: string,
    payload: MembershipContentUpdateRequest,
  ) => {
    if (!formData.id) {
      throw new Error('Save this Membership before updating content.');
    }

    await dispatch(
      updateMembershipContent({
        productId: formData.id,
        contentId,
        payload,
      }),
    ).unwrap();
  };

  const handleDeleteMembershipContent = async (contentId: string) => {
    if (!formData.id) {
      throw new Error('Save this Membership before deleting content.');
    }

    await dispatch(
      deleteMembershipContent({ productId: formData.id, contentId }),
    ).unwrap();
  };

  const handleMembershipOrderingModeChange = async (
    orderingMode: MembershipOrderingMode,
  ) => {
    const nextFeed =
      orderingMode === 'MANUAL' && membershipOrderingMode === 'NEWEST_FIRST'
        ? orderMembershipFeedEntries(membershipFeedEntries, 'NEWEST_FIRST')
        : membershipFeedEntries;

    await updateMembershipFeedForCurrentProduct(nextFeed, orderingMode);
  };

  const handleAddIncludedProducts = async (
    productIds: string[],
    addedAt: string,
  ) => {
    const existingProductIds = new Set(
      membershipIncludedProductEntries.map((entry) => entry.productId),
    );
    const newEntries = productIds
      .filter((productId) => !existingProductIds.has(productId))
      .map<MembershipFeedEntry>((productId) => ({
        entryId: `product:${productId}`,
        kind: 'PRODUCT',
        productId,
        addedAt,
      }));

    if (newEntries.length === 0) {
      return;
    }

    await updateMembershipFeedForCurrentProduct(
      membershipOrderingMode === 'MANUAL'
        ? [...newEntries, ...membershipFeedEntries]
        : [...membershipFeedEntries, ...newEntries],
    );
  };

  const handleRemoveIncludedProduct = async (productId?: string) => {
    if (!productId) {
      return;
    }

    await updateMembershipFeedForCurrentProduct(
      membershipFeedEntries.filter(
        (entry) => entry.kind !== 'PRODUCT' || entry.productId !== productId,
      ),
    );
  };

  const handleMoveMembershipFeedEntry = async (
    entryId: string,
    direction: 'UP' | 'DOWN',
  ) => {
    if (membershipOrderingMode !== 'MANUAL') {
      throw new Error('Switch to Manual order before moving feed entries.');
    }

    const currentIndex = membershipFeedEntries.findIndex(
      (entry) => entry.entryId === entryId,
    );
    const nextIndex = direction === 'UP' ? currentIndex - 1 : currentIndex + 1;

    if (
      currentIndex === -1 ||
      nextIndex < 0 ||
      nextIndex >= membershipFeedEntries.length
    ) {
      throw new Error('This feed entry cannot move any farther.');
    }

    const nextFeed = [...membershipFeedEntries];
    const currentEntry = nextFeed[currentIndex];

    nextFeed[currentIndex] = nextFeed[nextIndex];
    nextFeed[nextIndex] = currentEntry;

    await updateMembershipFeedForCurrentProduct(nextFeed);
  };

  const handleUploadThumbnail = async (file: File) => {
    if (!formData.id) {
      throw new Error('Save this Product before uploading a thumbnail.');
    }

    const result = await dispatch(
      addImageToProduct({ productId: formData.id, image: file }),
    ).unwrap();
    setField('imageUrl', result.imageUrl);

    return result.imageUrl;
  };

  const handleRemoveThumbnail = async () => {
    if (!formData.id) {
      throw new Error('Save this Product before removing a thumbnail.');
    }

    await dispatch(removeImageFromProduct({ productId: formData.id })).unwrap();
    setField('imageUrl', undefined);
  };

  const handleAddGalleryImage = async (file: File) => {
    if (!formData.id) {
      throw new Error('Save this Product before adding gallery images.');
    }

    const result = await dispatch(
      addProductGalleryImage({ productId: formData.id, image: file }),
    ).unwrap();
    setFormData((currentFormData) => ({
      ...currentFormData,
      galleryImages: [...(currentFormData.galleryImages ?? []), result.image]
        .slice()
        .sort((first, second) => first.position - second.position),
    }));

    return result.image;
  };

  const handleRemoveGalleryImage = async (imageId: string) => {
    if (!formData.id) {
      throw new Error('Save this Product before removing gallery images.');
    }

    await dispatch(
      removeProductGalleryImage({ productId: formData.id, imageId }),
    ).unwrap();
    setField(
      'galleryImages',
      (formData.galleryImages ?? [])
        .filter((image) => image.id !== imageId)
        .map((image, index) => ({ ...image, position: index + 1 })),
    );
  };

  const handleReorderGalleryImages = async (imageIds: string[]) => {
    if (!formData.id) {
      throw new Error('Save this Product before reordering gallery images.');
    }

    const result = await dispatch(
      reorderProductGalleryImages({ productId: formData.id, imageIds }),
    ).unwrap();
    setField('galleryImages', result.images);

    return result.images;
  };

  const handleUploadPromoVideo = async (file: File) => {
    if (!formData.id) {
      throw new Error('Save this Product before uploading a promo video.');
    }

    const result = await dispatch(
      addProductPromoVideo({ productId: formData.id, video: file }),
    ).unwrap();
    setField('promoVideo', result.promoVideo);

    return result.promoVideo;
  };

  const handleRemovePromoVideo = async () => {
    if (!formData.id) {
      throw new Error('Save this Product before removing a promo video.');
    }

    await dispatch(removeProductPromoVideo({ productId: formData.id })).unwrap();
    setField('promoVideo', null);
  };

  const workspaceNavigation =
    showRestOfForm && activeTab ? (
      <BuilderSidebar
        productType={formData.type}
        activeTab={activeTab}
        sections={sidebarSections}
        onChange={(tab) => setActiveTab(tab)}
        onSectionClick={handleSidebarSectionNavigation}
        onLessonClick={handleSidebarLessonNavigation}
      />
    ) : null;

  return (
    <ProductWorkspaceShell
      productType={formData.type}
      productTitle={formData.name}
      productStatus={formData.status}
      isEditMode={isEditMode}
      showWorkspace={showRestOfForm}
      saveStatus={saveStatus}
      hasPendingAutosave={hasPendingAutosave}
      canPublish={showRestOfForm && !isPublished && !isPublishing && !isMembership}
      publishDisabledReason={
        isPublished
          ? 'This Product is already published.'
          : isMembership
          ? 'Membership publishing is not available yet.'
          : undefined
      }
      isPublishing={isPublishing}
      canPreview={canPreview}
      previewDisabledReason={previewDisabledReason}
      publishHelpText={publishHelpText}
      onBack={handleWorkspaceBack}
      onPreview={handlePreview}
      onPublish={handlePublish}
      navigation={workspaceNavigation}
    >
      <div ref={container}>
        <form id="product-builder-form" ref={formRef} onSubmit={handleSubmit}>
        {!showRestOfForm && (
          <div
            className={clsx('product-create-hero', {
              'product-create-hero__collapsed': showRestOfForm,
              'product-create-hero__hidden': hasHeroCollapsed,
            })}
          >
            <CreateProductStepOne
              formData={formData}
              setField={setField}
              errors={errors}
              showRestOfForm={showRestOfForm}
              setShowRestOfForm={setShowRestOfForm}
              setShowLoadingRestOfForm={setShowLoadingRestOfForm}
              userId={productOwnerId ?? ''}
            />
          </div>
        )}

        {showLoadingRestOfForm && <p>Loading...</p>}

        {showRestOfForm && activeTab && (
          <div
            className={clsx('product-builder', {
              'product-builder__full': showRestOfForm,
            })}
          >
            <div className="product-create-section">
              <section
                id={`tab-panel-${activeTab}`}
                className="product-builder-panel"
                role="tabpanel"
                aria-labelledby={`builder-tab-${activeTab}`}
              >
                <div className="product-builder-panel__header">
                  <h2>{tabCopy[activeTab].title}</h2>
                  <p>{tabCopy[activeTab].description}</p>
                </div>
                <div className="product-builder-panel__body">
                  {renderActiveTabContent()}
                </div>
              </section>
            </div>
          </div>
        )}
        </form>
      </div>
    </ProductWorkspaceShell>
  );
};

